-- action_elementaire_coherente()
CREATE OR REPLACE FUNCTION public.action_elementaire_coherente()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _te RECORD;
  _somme numeric;
BEGIN
  SELECT te.user_id, te.organization_id, te.hours, te.status, te.date
    INTO _te
  FROM public.time_entries te WHERE te.id = NEW.time_entry_id;

  IF _te IS NULL THEN
    RAISE EXCEPTION 'Cette action ne se rattache a aucune imputation.';
  END IF;

  NEW.organization_id := _te.organization_id;

  -- Une imputation validee est un constat : son detail ne bouge plus.
  IF _te.status = 'approved' AND NOT public.est_directeur_associe(auth.uid()) THEN
    RAISE EXCEPTION 'Cette imputation est validee : son detail ne se modifie plus.';
  END IF;

  -- Le collaborateur renseigne SES actions, comme vous l'avez pose.
  IF auth.uid() IS NOT NULL
     AND _te.user_id <> auth.uid()
     AND NOT public.est_directeur_associe(auth.uid()) THEN
    RAISE EXCEPTION 'Les actions elementaires sont renseignees par le collaborateur lui-meme.';
  END IF;

  -- La somme des actions ne peut depasser les heures de la journee imputee.
  SELECT COALESCE(sum(ae.heures), 0) INTO _somme
  FROM public.actions_elementaires ae
  WHERE ae.time_entry_id = NEW.time_entry_id
    AND (TG_OP = 'INSERT' OR ae.id <> NEW.id);

  IF NEW.heures IS NOT NULL AND _te.hours IS NOT NULL
     AND _somme + NEW.heures > _te.hours THEN
    RAISE EXCEPTION
      'Le detail depasse la journee : % h deja detaillees, % h ajoutees, pour % h imputees.',
      _somme, NEW.heures, _te.hours;
  END IF;

  NEW.updated_at := now();
  RETURN NEW;
END $function$
;

-- add_mission_members_after_insert()
CREATE OR REPLACE FUNCTION public.add_mission_members_after_insert()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _me uuid := auth.uid();
BEGIN
  -- Hors session utilisateur, auth.uid() est NULL : on n'inscrit personne
  -- plutôt que d'inscrire un fantôme.
  IF _me IS NOT NULL THEN
    INSERT INTO public.mission_members (mission_id, user_id, role)
    VALUES (NEW.id, _me, public.best_leader_role(_me))
    ON CONFLICT (mission_id, user_id) DO NOTHING;
  END IF;

  IF NEW.director_id IS NOT NULL AND NEW.director_id IS DISTINCT FROM _me THEN
    INSERT INTO public.mission_members (mission_id, user_id, role)
    VALUES (NEW.id, NEW.director_id,
            public.best_leader_role(NEW.director_id))
    ON CONFLICT (mission_id, user_id) DO NOTHING;
  END IF;

  IF NEW.chief_id IS NOT NULL AND NEW.chief_id IS DISTINCT FROM _me
     AND NEW.chief_id IS DISTINCT FROM NEW.director_id THEN
    INSERT INTO public.mission_members (mission_id, user_id, role)
    VALUES (NEW.id, NEW.chief_id,
            public.best_mission_role(NEW.chief_id, 'chef_mission'))
    ON CONFLICT (mission_id, user_id) DO NOTHING;
  END IF;

  RETURN NEW;
END; $function$
;

-- add_project_members_after_insert()
CREATE OR REPLACE FUNCTION public.add_project_members_after_insert()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  INSERT INTO public.project_members (project_id, user_id, role)
  VALUES (NEW.id, auth.uid(), 'lead')
  ON CONFLICT (project_id, user_id) DO NOTHING;

  IF NEW.lead_id IS NOT NULL AND NEW.lead_id != auth.uid() THEN
    INSERT INTO public.project_members (project_id, user_id, role)
    VALUES (NEW.id, NEW.lead_id, 'lead')
    ON CONFLICT (project_id, user_id) DO NOTHING;
  END IF;

  RETURN NEW;
END;
$function$
;

-- aligner_roles_hors_plage()
CREATE OR REPLACE FUNCTION public.aligner_roles_hors_plage()
 RETURNS TABLE(source text, nom text, mission text, role_avant text, role_apres text, rang smallint)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _r RECORD; _nouveau text;
BEGIN
  -- Les appartenances d'abord : le staffing s'aligne ensuite sur elles.
  FOR _r IN
    SELECT mm.mission_id, mm.user_id, mm.role,
           p.full_name, m.name AS mission_name,
           public.profile_rank(mm.user_id) AS rk
    FROM mission_members mm
    JOIN profiles p ON p.id = mm.user_id
    JOIN missions  m ON m.id = mm.mission_id
    WHERE public.profile_rank(mm.user_id) IS NOT NULL
      AND public.profile_rank(mm.user_id)
          NOT BETWEEN public.mission_role_min_rank(mm.role)
                  AND public.mission_role_max_rank(mm.role)
  LOOP
    _nouveau := public.rank_to_mission_role(_r.rk);
    UPDATE mission_members SET role = _nouveau
     WHERE mission_id = _r.mission_id AND user_id = _r.user_id;

    RETURN QUERY SELECT 'membre'::text, _r.full_name::text, _r.mission_name::text,
      public.mission_role_label(_r.role), public.mission_role_label(_nouveau), _r.rk;
  END LOOP;

  -- Puis les affectations qui resteraient hors plage.
  FOR _r IN
    SELECT s.id, s.user_id, s.role, p.full_name, m.name AS mission_name,
           public.profile_rank(s.user_id) AS rk
    FROM staffing_assignments s
    JOIN profiles p ON p.id = s.user_id
    JOIN missions  m ON m.id = s.mission_id
    WHERE public.profile_rank(s.user_id) IS NOT NULL
      AND public.profile_rank(s.user_id)
          NOT BETWEEN public.mission_role_min_rank(s.role)
                  AND public.mission_role_max_rank(s.role)
  LOOP
    _nouveau := public.rank_to_mission_role(_r.rk);
    UPDATE staffing_assignments SET role = _nouveau WHERE id = _r.id;

    RETURN QUERY SELECT 'affectation'::text, _r.full_name::text, _r.mission_name::text,
      public.mission_role_label(_r.role), public.mission_role_label(_nouveau), _r.rk;
  END LOOP;
END; $function$
;

-- ancre_historique_grade(_user_id uuid)
CREATE OR REPLACE FUNCTION public.ancre_historique_grade(_user_id uuid)
 RETURNS date
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT LEAST(
    COALESCE((SELECT p.created_at::date FROM profiles p WHERE p.id = _user_id),
             CURRENT_DATE),
    COALESCE((SELECT min(m.start_date) FROM missions m
               JOIN mission_members mm ON mm.mission_id = m.id
              WHERE mm.user_id = _user_id AND m.start_date IS NOT NULL),
             CURRENT_DATE));
$function$
;

-- assign_evaluator(_mission_id uuid, _evaluatee_id uuid, _evaluator_id uuid, _eval_type eval_type, _exercice smallint, _due_date date, _practice eval_practice, _dossier_id uuid)
CREATE OR REPLACE FUNCTION public.assign_evaluator(_mission_id uuid, _evaluatee_id uuid, _evaluator_id uuid, _eval_type eval_type DEFAULT 'mission'::eval_type, _exercice smallint DEFAULT NULL::smallint, _due_date date DEFAULT NULL::date, _practice eval_practice DEFAULT NULL::eval_practice, _dossier_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _org uuid; _ee int; _er int; _rk_ee int; _rk_er int;
BEGIN
  IF NOT public.est_directeur_associe(auth.uid()) THEN
    RAISE EXCEPTION 'La désignation des évaluateurs revient au directeur associé.';
  END IF;
  SELECT organization_id INTO _org FROM profiles WHERE id = auth.uid();
  SELECT grade_level INTO _ee FROM profiles WHERE id = _evaluatee_id AND organization_id = _org;
  SELECT grade_level INTO _er FROM profiles WHERE id = _evaluator_id AND organization_id = _org;
  IF _ee IS NULL OR _er IS NULL THEN RAISE EXCEPTION 'Collaborateur ou évaluateur introuvable dans votre cabinet.'; END IF;
  IF _evaluator_id = _evaluatee_id THEN RAISE EXCEPTION 'Un collaborateur ne peut pas s''évaluer lui-même.'; END IF;

  IF _eval_type = 'mission' THEN
    IF _mission_id IS NULL OR NOT EXISTS (SELECT 1 FROM missions WHERE id = _mission_id AND organization_id = _org) THEN
      RAISE EXCEPTION 'Mission introuvable dans votre cabinet.'; END IF;
    SELECT CASE role WHEN 'associe' THEN 1 WHEN 'directeur_mission' THEN 2 WHEN 'chef_mission' THEN 3 WHEN 'auditeur_experimente' THEN 4 WHEN 'auditeur' THEN 5 WHEN 'auditeur_junior' THEN 6 END
      INTO _rk_ee FROM mission_members WHERE mission_id = _mission_id AND user_id = _evaluatee_id;
    SELECT CASE role WHEN 'associe' THEN 1 WHEN 'directeur_mission' THEN 2 WHEN 'chef_mission' THEN 3 WHEN 'auditeur_experimente' THEN 4 WHEN 'auditeur' THEN 5 WHEN 'auditeur_junior' THEN 6 END
      INTO _rk_er FROM mission_members WHERE mission_id = _mission_id AND user_id = _evaluator_id;
    IF _rk_ee IS NULL OR _rk_er IS NULL THEN RAISE EXCEPTION 'L''évaluateur et le collaborateur doivent tous deux être membres de l''équipe de la mission.'; END IF;
    IF _rk_er >= _rk_ee THEN RAISE EXCEPTION 'Dans une mission, l''évaluateur doit dominer le collaborateur par son rôle.'; END IF;
    _dossier_id := NULL;
  ELSIF _eval_type = 'dossier' THEN
    IF _dossier_id IS NULL OR NOT EXISTS (SELECT 1 FROM client_fiscal_profile WHERE id = _dossier_id AND organization_id = _org) THEN
      RAISE EXCEPTION 'Dossier comptable introuvable dans votre cabinet.'; END IF;
    IF _er >= _ee THEN RAISE EXCEPTION 'Hors mission, l''évaluateur doit être d''un grade supérieur à celui du collaborateur.'; END IF;
    _mission_id := NULL;
  ELSIF _eval_type = 'annuelle' THEN
    IF _exercice IS NULL THEN RAISE EXCEPTION 'Précisez l''exercice de l''évaluation annuelle.'; END IF;
    IF _er >= _ee THEN RAISE EXCEPTION 'Hors mission, l''évaluateur doit être d''un grade supérieur à celui du collaborateur.'; END IF;
    IF EXISTS (SELECT 1 FROM evaluation_assignments WHERE evaluatee_id = _evaluatee_id AND eval_type = 'annuelle' AND COALESCE(exercice,0) = _exercice AND status <> 'annulee') THEN
      RAISE EXCEPTION 'Un évaluateur annuel est déjà désigné pour ce collaborateur sur cet exercice. Retirez la désignation existante avant d''en faire une autre.'; END IF;
    _mission_id := NULL; _dossier_id := NULL;
  ELSE
    IF _er >= _ee THEN RAISE EXCEPTION 'L''évaluateur doit être d''un grade supérieur à celui du collaborateur.'; END IF;
  END IF;

  IF EXISTS (SELECT 1 FROM evaluation_assignments WHERE status <> 'annulee' AND eval_type = _eval_type AND evaluatee_id = _evaluatee_id AND evaluator_id = _evaluator_id
      AND mission_id IS NOT DISTINCT FROM _mission_id AND dossier_id IS NOT DISTINCT FROM _dossier_id AND COALESCE(exercice,0) = COALESCE(_exercice,0)) THEN
    RAISE EXCEPTION 'Cet évaluateur est déjà désigné pour ce collaborateur.'; END IF;

  INSERT INTO evaluation_assignments (organization_id, mission_id, dossier_id, eval_type, exercice, practice, evaluator_id, evaluatee_id, assigned_by, due_date)
  VALUES (_org, _mission_id, _dossier_id, _eval_type, _exercice, _practice, _evaluator_id, _evaluatee_id, auth.uid(), _due_date);

  INSERT INTO notifications (user_id, type, title, content, entity_type, entity_id, priority)
  VALUES (_evaluator_id, 'evaluation_assigned', 'Évaluation à réaliser',
    'Vous êtes désigné évaluateur de ' || COALESCE((SELECT full_name FROM profiles WHERE id = _evaluatee_id), 'un collaborateur') ||
    COALESCE(' pour la mission ' || (SELECT name FROM missions WHERE id = _mission_id), '') || '.',
    CASE WHEN _mission_id IS NOT NULL THEN 'mission' ELSE 'evaluation' END, _mission_id, 'normal');
  RETURN jsonb_build_object('success', true);
END; $function$
;

-- attach_free_upload_to_obligation(_portal_document_id uuid, _obligation_document_id uuid)
CREATE OR REPLACE FUNCTION public.attach_free_upload_to_obligation(_portal_document_id uuid, _obligation_document_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _org uuid;
  _pd RECORD;
  _od_client uuid;
BEGIN
  SELECT p.organization_id INTO _org FROM profiles p WHERE p.id = auth.uid();

  SELECT * INTO _pd FROM portal_documents WHERE id = _portal_document_id;
  IF _pd IS NULL OR _pd.organization_id <> _org THEN
    RAISE EXCEPTION 'Document introuvable';
  END IF;

  SELECT op.client_id INTO _od_client
  FROM obligation_documents od
  JOIN obligation_periods op ON op.id = od.obligation_period_id
  WHERE od.id = _obligation_document_id;

  IF _od_client IS DISTINCT FROM _pd.client_id THEN
    RAISE EXCEPTION 'Cette pièce ne concerne pas le même client';
  END IF;

  UPDATE obligation_documents
     SET status = 'deposee',
         source = 'portail',
         file_path = _pd.file_path,
         file_name = _pd.file_name,
         deposited_at = _pd.uploaded_at,
         reject_reason = NULL
   WHERE id = _obligation_document_id;

  UPDATE portal_documents
     SET obligation_document_id = _obligation_document_id
   WHERE id = _portal_document_id;

  RETURN jsonb_build_object('success', true);
END;
$function$
;

-- auto_set_org_id()
CREATE OR REPLACE FUNCTION public.auto_set_org_id()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.organization_id IS NULL THEN
    NEW.organization_id := public.get_user_organization_id(auth.uid());
  END IF;
  RETURN NEW;
END;
$function$
;

-- best_leader_role(_user_id uuid)
CREATE OR REPLACE FUNCTION public.best_leader_role(_user_id uuid)
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _rank smallint := public.profile_rank(_user_id);
BEGIN
  IF _rank IS NULL THEN RETURN 'auditeur_junior'; END IF;
  IF _rank >= 16   THEN RETURN 'associe'; END IF;
  IF _rank >= 10   THEN RETURN 'directeur_mission'; END IF;
  RETURN public.rank_to_mission_role(_rank);
END; $function$
;

-- best_mission_role(_user_id uuid, _wanted text)
CREATE OR REPLACE FUNCTION public.best_mission_role(_user_id uuid, _wanted text)
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _rank smallint := public.profile_rank(_user_id);
        _min  smallint := public.mission_role_min_rank(_wanted);
        _max  smallint := public.mission_role_max_rank(_wanted);
BEGIN
  IF _rank IS NULL THEN RETURN 'auditeur_junior'; END IF;
  IF _min IS NOT NULL AND _rank BETWEEN _min AND _max THEN RETURN _wanted; END IF;
  RETURN public.rank_to_mission_role(_rank);
END; $function$
;

-- block_if_org_suspended()
CREATE OR REPLACE FUNCTION public.block_if_org_suspended()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NOT public.is_org_active(NEW.organization_id) THEN
    RAISE EXCEPTION 'Votre organisation est suspendue. Contactez le support.';
  END IF;
  RETURN NEW;
END; $function$
;

-- budget_de_la_mission(_mission_id uuid)
CREATE OR REPLACE FUNCTION public.budget_de_la_mission(_mission_id uuid)
 RETURNS TABLE(montant numeric, devise text, notes text, fixe_par text, le boolean)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT mb.amount, mb.currency, mb.notes, p.full_name,
         public.peut_fixer_le_budget(auth.uid(), _mission_id)
  FROM public.mission_budgets mb
  LEFT JOIN public.profiles p ON p.id = mb.created_by
  WHERE mb.mission_id = _mission_id
    AND public.peut_voir_le_budget(auth.uid(), _mission_id);
$function$
;

-- budget_range_hors_de_la_fiche()
CREATE OR REPLACE FUNCTION public.budget_range_hors_de_la_fiche()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  -- Seul le MONTANT est un secret. budget_currency vaut « XOF » par defaut sur
  -- toutes vos missions : si ce declencheur s'en emouvait, chaque creation de
  -- mission fabriquerait une ligne de budget vide. Vu a l'essai.
  IF NEW.budget_amount IS NULL THEN
    RETURN NULL;
  END IF;

  INSERT INTO public.mission_budgets (mission_id, organization_id, amount, currency, created_by)
  VALUES (NEW.id, NEW.organization_id, NEW.budget_amount,
          COALESCE(NEW.budget_currency, 'XOF'), auth.uid())
  ON CONFLICT (mission_id) DO UPDATE
    SET amount = COALESCE(EXCLUDED.amount, public.mission_budgets.amount),
        currency = COALESCE(EXCLUDED.currency, public.mission_budgets.currency),
        updated_at = now();

  -- On vide le MONTANT, et lui seul : la devise reste dans la fiche, elle ne
  -- dit rien. La mise a jour redeclenche ce declencheur, qui s'arrete alors a
  -- sa premiere ligne.
  UPDATE public.missions
     SET budget_amount = NULL
   WHERE id = NEW.id AND budget_amount IS NOT NULL;

  RETURN NULL;
END $function$
;

-- budgets_du_cabinet()
CREATE OR REPLACE FUNCTION public.budgets_du_cabinet()
 RETURNS TABLE(mission_id uuid, code text, intitule text, statut text, montant numeric, devise text, notes text, fixe_par text, peut_le_fixer boolean)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT m.id, m.code, m.name, m.status,
         mb.amount, mb.currency, mb.notes, p.full_name,
         public.peut_fixer_le_budget(auth.uid(), m.id)
  FROM public.missions m
  LEFT JOIN public.mission_budgets mb ON mb.mission_id = m.id
  LEFT JOIN public.profiles p ON p.id = mb.created_by
  WHERE m.organization_id = (SELECT pr.organization_id
                             FROM public.profiles pr WHERE pr.id = auth.uid())
    -- La regle de visibilite du budget, et elle seule : l'associe et le
    -- directeur de mission de CETTE mission. Les missions sans budget sont
    -- incluses, car ce sont celles qu'il faut pouvoir doter.
    AND public.peut_voir_le_budget(auth.uid(), m.id)
  ORDER BY m.code;
$function$
;

