CREATE OR REPLACE FUNCTION public.caller_organization_id()
 RETURNS uuid
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT organization_id FROM public.profiles WHERE id = auth.uid()
$function$
;

-- caller_sees_user(_user_id uuid)
CREATE OR REPLACE FUNCTION public.caller_sees_user(_user_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _mine uuid; _theirs uuid; _admin boolean := false;
BEGIN
  IF _user_id IS NULL THEN RETURN false; END IF;
  IF _user_id = auth.uid() THEN RETURN true; END IF;

  SELECT organization_id INTO _mine   FROM profiles WHERE id = auth.uid();
  SELECT organization_id INTO _theirs FROM profiles WHERE id = _user_id;

  IF _mine IS NOT NULL AND _mine = _theirs THEN RETURN true; END IF;

  -- Le super-administrateur, si le module est installé
  IF to_regprocedure('public.is_platform_admin(text)') IS NOT NULL THEN
    EXECUTE 'SELECT public.is_platform_admin()' INTO _admin;
  END IF;
  RETURN COALESCE(_admin, false);
END $function$
;

-- can_access_committee(_committee_id uuid)
CREATE OR REPLACE FUNCTION public.can_access_committee(_committee_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT EXISTS (
    SELECT 1
    FROM public.committees c
    LEFT JOIN public.missions m ON m.id = c.mission_id
    WHERE c.id = _committee_id
      AND (
        -- Comité de mission : membre de la mission, ou responsable
        (c.mission_id IS NOT NULL AND (
           EXISTS (SELECT 1 FROM public.mission_members mm
                    WHERE mm.mission_id = c.mission_id AND mm.user_id = auth.uid())
           OR m.organization_id = public.get_user_organization_id(auth.uid())
              AND (SELECT p.grade_level FROM public.profiles p WHERE p.id = auth.uid()) <= 2
        ))
        -- Comité d'organisation : réservé DA/DM
        OR (c.mission_id IS NULL
            AND c.organization_id = public.get_user_organization_id(auth.uid())
            AND (SELECT p.grade_level FROM public.profiles p WHERE p.id = auth.uid()) <= 2)
        -- Membre du comité
        OR EXISTS (SELECT 1 FROM public.committee_members cm2
                    WHERE cm2.committee_id = c.id AND cm2.user_id = auth.uid())
      )
  );
$function$
;

-- can_access_document(_user_id uuid, _doc_id uuid)
CREATE OR REPLACE FUNCTION public.can_access_document(_user_id uuid, _doc_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT EXISTS (
    SELECT 1 FROM public.documents d
    JOIN public.profiles p ON p.id = _user_id
    WHERE d.id = _doc_id
      AND d.organization_id = p.organization_id
      AND (
        d.uploaded_by = _user_id
        OR EXISTS (SELECT 1 FROM public.document_shares ds
                    WHERE ds.document_id = d.id AND ds.shared_with = _user_id)
        -- LE DOSSIER DECIDE : c'est la matrice des quatre dossiers.
        OR (d.folder_id IS NOT NULL AND public.peut_voir_dossier(_user_id, d.folder_id))
        -- Piece de mission sans dossier : l'appartenance seule, le temps que
        -- le front range tout dans les dossiers.
        OR (d.folder_id IS NULL AND d.mission_id IS NOT NULL
            AND public.can_access_mission(_user_id, d.mission_id))
        OR (d.folder_id IS NULL AND d.project_id IS NOT NULL
            AND public.can_access_project(_user_id, d.project_id))
        OR (d.folder_id IS NULL AND d.committee_id IS NOT NULL AND EXISTS (
              SELECT 1 FROM public.committee_members cm
              WHERE cm.committee_id = d.committee_id AND cm.user_id = _user_id))
        -- Document rattache a RIEN : hors mission, le grade decide.
        OR (d.folder_id IS NULL AND d.mission_id IS NULL AND d.project_id IS NULL
            AND d.committee_id IS NULL AND COALESCE(p.grade_level, 8) <= 3)
      )
  );
$function$
;

-- can_access_mission(_user_id uuid, _mission_id uuid)
CREATE OR REPLACE FUNCTION public.can_access_mission(_user_id uuid, _mission_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT EXISTS (
    SELECT 1
    FROM public.missions m
    JOIN public.profiles p ON p.id = _user_id
    WHERE m.id = _mission_id
      AND m.organization_id = p.organization_id
      AND (
        -- L'appartenance, et elle seule. Le niveau de grade n'ouvre plus
        -- rien : un associe hors mission ne voit rien de cette mission.
        EXISTS (
          SELECT 1 FROM public.mission_members mm
          WHERE mm.mission_id = m.id AND mm.user_id = _user_id
        )
        -- Les designations de la fiche restent reconnues, pour ne verrouiller
        -- personne a cause d'une incoherence entre la fiche et l'equipe.
        OR m.director_id = _user_id
        OR m.chief_id    = _user_id
      )
  );
$function$
;

-- can_access_project(_user_id uuid, _project_id uuid)
CREATE OR REPLACE FUNCTION public.can_access_project(_user_id uuid, _project_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT EXISTS (
    SELECT 1
    FROM public.projects p
    JOIN public.profiles pr ON pr.id = _user_id
    WHERE p.id = _project_id
      AND p.organization_id = pr.organization_id
      AND (
        -- Le contournement par le grade est retire : un responsable hors
        -- mission n'accede pas davantage aux projets de cette mission.
        p.lead_id = _user_id
        OR public.can_access_mission(_user_id, p.mission_id)
        OR EXISTS (
          SELECT 1 FROM public.project_members pm
          WHERE pm.project_id = p.id AND pm.user_id = _user_id
        )
      )
  );
$function$
;

-- can_access_task(_user_id uuid, _task_id uuid)
CREATE OR REPLACE FUNCTION public.can_access_task(_user_id uuid, _task_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT EXISTS (
    SELECT 1
    FROM public.tasks t
    JOIN public.projects p ON p.id = t.project_id
    JOIN public.profiles pr ON pr.id = _user_id
    WHERE t.id = _task_id
      AND t.organization_id = pr.organization_id
      AND p.organization_id = pr.organization_id
      AND (
        t.created_by = _user_id
        OR p.lead_id = _user_id
        OR public.can_access_project(_user_id, p.id)
        OR EXISTS (
          SELECT 1 FROM public.task_assignments ta
          WHERE ta.task_id = t.id AND ta.user_id = _user_id
        )
      )
  );
$function$
;

-- can_create_mission(_user_id uuid, _organization_id uuid)
CREATE OR REPLACE FUNCTION public.can_create_mission(_user_id uuid, _organization_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT EXISTS (
    SELECT 1
    FROM public.profiles p
    WHERE p.id = _user_id
      AND p.organization_id = _organization_id
      AND COALESCE(p.grade_level, 8) <= 3
  )
$function$
;

-- can_insert_project(_user_id uuid, _mission_id uuid, _organization_id uuid)
CREATE OR REPLACE FUNCTION public.can_insert_project(_user_id uuid, _mission_id uuid, _organization_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT EXISTS (
    SELECT 1
    FROM public.profiles p
    JOIN public.missions m ON m.id = _mission_id
    WHERE p.id = _user_id
      AND p.organization_id IS NOT NULL
      AND m.organization_id = p.organization_id
      AND _organization_id = p.organization_id
      AND (
        COALESCE(p.grade_level, 8) <= 3
        OR m.director_id = _user_id
        OR m.chief_id = _user_id
        OR EXISTS (
          SELECT 1
          FROM public.mission_members mm
          WHERE mm.mission_id = m.id
            AND mm.user_id = _user_id
        )
      )
  )
$function$
;

-- can_read_category(_category_id uuid)
CREATE OR REPLACE FUNCTION public.can_read_category(_category_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT EXISTS (
    SELECT 1 FROM public.evaluation_categories c
    JOIN public.evaluation_templates t ON t.id = c.template_id
    WHERE c.id = _category_id
      AND t.organization_id = (SELECT p.organization_id FROM public.profiles p WHERE p.id = auth.uid())
  );
$function$
;

-- can_read_evaluation(_evaluation_id uuid)
CREATE OR REPLACE FUNCTION public.can_read_evaluation(_evaluation_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT EXISTS (
    SELECT 1 FROM public.evaluations e
    WHERE e.id = _evaluation_id
      AND (
        e.evaluator_id = auth.uid()
        OR (e.evaluatee_id = auth.uid() AND e.status <> 'brouillon')
        OR (
          e.organization_id = (SELECT p.organization_id FROM public.profiles p
                                WHERE p.id = auth.uid())
          AND e.status IN ('validee','arbitrage','cloturee')
          AND CASE
                -- Evaluation de MISSION : l'appartenance decide.
                WHEN e.mission_id IS NOT NULL
                  THEN public.can_access_mission(auth.uid(), e.mission_id)
                -- Evaluation de DOSSIER comptable : le grade decide, comme
                -- vous l'avez pose.
                ELSE (SELECT p.grade_level FROM public.profiles p
                       WHERE p.id = auth.uid()) <= 2
              END
        )
      )
  );
$function$
;

-- can_read_template(_template_id uuid)
CREATE OR REPLACE FUNCTION public.can_read_template(_template_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT EXISTS (
    SELECT 1 FROM public.evaluation_templates t
    WHERE t.id = _template_id
      AND t.organization_id = (SELECT p.organization_id FROM public.profiles p WHERE p.id = auth.uid())
  );
$function$
;

-- can_score_evaluation(_evaluation_id uuid)
CREATE OR REPLACE FUNCTION public.can_score_evaluation(_evaluation_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT EXISTS (
    SELECT 1 FROM public.evaluations e
    WHERE e.id = _evaluation_id
      AND e.evaluator_id = auth.uid()
      AND e.status IN ('brouillon', 'observations_recues', 'revisee')
  );
$function$
;

-- can_see_user_info(viewer_id uuid, target_id uuid)
CREATE OR REPLACE FUNCTION public.can_see_user_info(viewer_id uuid, target_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT CASE
    -- Chacun se voit lui-meme.
    WHEN viewer_id = target_id THEN true
    ELSE EXISTS (
      SELECT 1
      FROM public.profiles v, public.profiles t
      WHERE v.id = viewer_id AND t.id = target_id
        -- Jamais au-dela de son cabinet.
        AND v.organization_id IS NOT NULL
        AND v.organization_id = t.organization_id
        -- STRICTEMENT superieur : deux pairs ne se voient pas.
        -- grade_level va de 1 (Directeur Associe) a 8 (stagiaire), donc
        -- « superieur » veut dire « plus petit ».
        AND v.grade_level IS NOT NULL
        AND t.grade_level IS NOT NULL
        AND v.grade_level < t.grade_level
    )
  END;
$function$
;

-- check_template_weights(_template_id uuid)
CREATE OR REPLACE FUNCTION public.check_template_weights(_template_id uuid)
 RETURNS numeric
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT COALESCE(SUM(weight), 0) FROM public.evaluation_categories WHERE template_id = _template_id;
$function$
;

-- compute_evaluation_score(_evaluation_id uuid)
CREATE OR REPLACE FUNCTION public.compute_evaluation_score(_evaluation_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _tpl uuid;
  _org uuid;
  _total numeric := 0;
  _complete boolean := true;
  _cats jsonb := '[]'::jsonb;
  _rec RECORD;
  _appr_code text; _appr_label text;
BEGIN
  SELECT template_id, organization_id INTO _tpl, _org
  FROM evaluations WHERE id = _evaluation_id;

  IF _tpl IS NULL THEN RAISE EXCEPTION 'Évaluation introuvable'; END IF;

  FOR _rec IN
    SELECT c.id, c.code, c.label, c.weight,
           COUNT(s.id)                          AS nb_sub,
           COUNT(es.score)                      AS nb_notes,
           AVG(es.score)::numeric               AS moyenne
    FROM evaluation_categories c
    JOIN evaluation_subcriteria s ON s.category_id = c.id
    LEFT JOIN evaluation_scores es
           ON es.subcriterion_id = s.id AND es.evaluation_id = _evaluation_id
    WHERE c.template_id = _tpl
    GROUP BY c.id, c.code, c.label, c.weight, c.sort_order
    ORDER BY c.sort_order, c.code
  LOOP
    IF _rec.nb_notes < _rec.nb_sub THEN _complete := false; END IF;

    _total := _total + CASE WHEN _rec.moyenne IS NULL THEN 0
                            ELSE (_rec.moyenne / 5.0) * _rec.weight END;

    _cats := _cats || jsonb_build_object(
      'code', _rec.code, 'label', _rec.label,
      'weight', _rec.weight,
      'note', ROUND(COALESCE(_rec.moyenne, 0), 2),
      'contribution', ROUND(COALESCE((_rec.moyenne / 5.0) * _rec.weight, 0) * 100, 2),
      'scored', _rec.nb_notes, 'total', _rec.nb_sub);
  END LOOP;

  _total := ROUND(_total * 100, 2);

  SELECT code, label INTO _appr_code, _appr_label
  FROM evaluation_scale
  WHERE organization_id = _org AND _total >= min_score AND _total <= max_score
  ORDER BY sort_order LIMIT 1;

  RETURN jsonb_build_object(
    'weighted_score', _total,
    'appreciation', _appr_code,
    'appreciation_label', _appr_label,
    'is_complete', _complete,
    'categories', _cats);
END;
$function$
;

-- create_mission_with_members(_name text, _description text, _type text, _client_id uuid, _director_id uuid, _chief_id uuid, _budget_amount numeric, _budget_currency text, _start_date date, _end_date date, _priority text)
CREATE OR REPLACE FUNCTION public.create_mission_with_members(_name text, _description text DEFAULT NULL::text, _type text DEFAULT NULL::text, _client_id uuid DEFAULT NULL::uuid, _director_id uuid DEFAULT NULL::uuid, _chief_id uuid DEFAULT NULL::uuid, _budget_amount numeric DEFAULT NULL::numeric, _budget_currency text DEFAULT 'XOF'::text, _start_date date DEFAULT NULL::date, _end_date date DEFAULT NULL::date, _priority text DEFAULT 'medium'::text)
 RETURNS missions
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _user_id uuid := auth.uid();
  _org_id uuid;
  _grade_level integer;
  _mission public.missions;
  _code text;
  _year text := to_char(now(), 'YYYY');
  _priority_clean text := COALESCE(NULLIF(_priority, ''), 'medium');
  _currency_clean text := COALESCE(NULLIF(_budget_currency, ''), 'XOF');
BEGIN
  IF _user_id IS NULL THEN
    RAISE EXCEPTION 'Utilisateur non authentifié';
  END IF;

  SELECT p.organization_id, COALESCE(p.grade_level, 8)
    INTO _org_id, _grade_level
  FROM public.profiles p
  WHERE p.id = _user_id;

  IF _org_id IS NULL THEN
    RAISE EXCEPTION 'Votre profil n''est rattaché à aucune organisation';
  END IF;

  IF _grade_level > 3 THEN
    RAISE EXCEPTION 'Vous n''avez pas le droit de créer une mission';
  END IF;

  IF NULLIF(trim(_name), '') IS NULL THEN
    RAISE EXCEPTION 'Le nom de la mission est obligatoire';
  END IF;

  IF _priority_clean = 'urgent' THEN
    _priority_clean := 'critical';
  END IF;

  IF _priority_clean NOT IN ('low', 'medium', 'high', 'critical') THEN
    _priority_clean := 'medium';
  END IF;

  IF _currency_clean NOT IN ('XOF', 'XAF', 'EUR', 'USD') THEN
    _currency_clean := 'XOF';
  END IF;

  IF _client_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM public.clients c WHERE c.id = _client_id AND c.organization_id = _org_id
  ) THEN
    RAISE EXCEPTION 'Le client sélectionné est invalide pour votre organisation';
  END IF;

  IF _director_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM public.profiles p WHERE p.id = _director_id AND p.organization_id = _org_id
  ) THEN
    RAISE EXCEPTION 'Le Directeur de Mission sélectionné est invalide pour votre organisation';
  END IF;

  IF _chief_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM public.profiles p WHERE p.id = _chief_id AND p.organization_id = _org_id
  ) THEN
    RAISE EXCEPTION 'Le Chef de Mission sélectionné est invalide pour votre organisation';
  END IF;

  SELECT 'MIS-' || _year || '-' || lpad((COUNT(*) + 1)::text, 3, '0')
    INTO _code
  FROM public.missions m
  WHERE m.organization_id = _org_id
    AND m.code LIKE 'MIS-' || _year || '-%';

  INSERT INTO public.missions (
    organization_id,
    client_id,
    name,
    description,
    code,
    type,
    status,
    director_id,
    chief_id,
    budget_amount,
    budget_currency,
    start_date,
    end_date,
    priority
  ) VALUES (
    _org_id,
    _client_id,
    trim(_name),
    NULLIF(trim(COALESCE(_description, '')), ''),
    _code,
    NULLIF(_type, ''),
    'draft',
    _director_id,
    _chief_id,
    _budget_amount,
    _currency_clean,
    _start_date,
    _end_date,
    _priority_clean
  )
  RETURNING * INTO _mission;

  INSERT INTO public.mission_members (mission_id, user_id, role)
  VALUES (_mission.id, _user_id, CASE WHEN _user_id = _director_id THEN public.best_leader_role(_user_id) WHEN _user_id = _chief_id THEN public.best_mission_role(_user_id, 'chef_mission') ELSE public.best_mission_role(_user_id, 'auditeur_experimente') END)
  ON CONFLICT (mission_id, user_id) DO UPDATE SET role = EXCLUDED.role;

  IF _director_id IS NOT NULL THEN
    INSERT INTO public.mission_members (mission_id, user_id, role)
    VALUES (_mission.id, _director_id, public.best_leader_role(_director_id))
    ON CONFLICT (mission_id, user_id) DO UPDATE SET role = EXCLUDED.role;
  END IF;

  IF _chief_id IS NOT NULL THEN
    INSERT INTO public.mission_members (mission_id, user_id, role)
    VALUES (_mission.id, _chief_id, public.best_mission_role(_chief_id, 'chef_mission'))
    ON CONFLICT (mission_id, user_id) DO UPDATE SET role = EXCLUDED.role;
  END IF;

  RETURN _mission;
END;
$function$
;

-- create_organization_for_current_user(_name text, _slug text, _subscription_plan text, _max_users integer, _max_storage_gb integer, _settings jsonb, _full_name text, _phone text)
CREATE OR REPLACE FUNCTION public.create_organization_for_current_user(_name text, _slug text, _subscription_plan text DEFAULT 'free'::text, _max_users integer DEFAULT 5, _max_storage_gb integer DEFAULT 5, _settings jsonb DEFAULT '{}'::jsonb, _full_name text DEFAULT NULL::text, _phone text DEFAULT NULL::text)
 RETURNS organizations
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _user_id uuid := auth.uid();
  _email text;
  _existing_org_id uuid;
  _org public.organizations;
  _clean_name text := NULLIF(trim(_name), '');
  _base_slug text := NULLIF(trim(_slug), '');
  _final_slug text;
  _attempt int := 0;
BEGIN
  IF _user_id IS NULL THEN
    RAISE EXCEPTION 'Utilisateur non authentifié';
  END IF;

  SELECT email, organization_id INTO _email, _existing_org_id
  FROM public.profiles WHERE id = _user_id;

  IF _existing_org_id IS NOT NULL THEN
    RAISE EXCEPTION 'Votre compte est déjà rattaché à une organisation';
  END IF;

  IF _clean_name IS NULL OR length(_clean_name) < 2 THEN
    RAISE EXCEPTION 'Le nom de l''organisation est obligatoire';
  END IF;

  IF _base_slug IS NULL OR length(_base_slug) < 2 THEN
    _base_slug := lower(regexp_replace(_clean_name, '[^a-zA-Z0-9]+', '-', 'g'));
    _base_slug := trim(both '-' from _base_slug);
  END IF;
  _base_slug := lower(_base_slug);

  -- Trouver un slug unique propre (sans suffixe random) : base, base-2, base-3, ...
  _final_slug := _base_slug;
  WHILE EXISTS (SELECT 1 FROM public.organizations WHERE slug = _final_slug) LOOP
    _attempt := _attempt + 1;
    _final_slug := _base_slug || '-' || (_attempt + 1)::text;
    IF _attempt > 100 THEN
      _final_slug := _base_slug || '-' || substr(replace(gen_random_uuid()::text, '-', ''), 1, 6);
      EXIT;
    END IF;
  END LOOP;

  INSERT INTO public.organizations (name, slug, subscription_plan, max_users, max_storage_gb, settings)
  VALUES (
    _clean_name, _final_slug,
    COALESCE(NULLIF(_subscription_plan, ''), 'free'),
    COALESCE(_max_users, 5),
    COALESCE(_max_storage_gb, 5),
    COALESCE(_settings, '{}'::jsonb)
  )
  RETURNING * INTO _org;

  INSERT INTO public.profiles (id, organization_id, email, full_name, phone, grade)
  VALUES (
    _user_id, _org.id,
    COALESCE(_email, ''),
    COALESCE(NULLIF(trim(_full_name), ''), split_part(COALESCE(_email, ''), '@', 1), 'Utilisateur'),
    NULLIF(trim(_phone), ''),
    'DA'
  )
  ON CONFLICT (id) DO UPDATE SET
    organization_id = EXCLUDED.organization_id,
    full_name = EXCLUDED.full_name,
    phone = EXCLUDED.phone,
    grade = 'DA',
    updated_at = now();

  INSERT INTO public.user_roles (user_id, role, organization_id)
  VALUES (_user_id, 'owner', _org.id)
  ON CONFLICT (user_id, role) DO UPDATE SET organization_id = EXCLUDED.organization_id;

  INSERT INTO public.personal_workspaces (user_id, organization_id)
  VALUES (_user_id, _org.id)
  ON CONFLICT DO NOTHING;

  RETURN _org;
END;
$function$
;

-- create_portal_invitation(_client_id uuid, _email text, _full_name text)
CREATE OR REPLACE FUNCTION public.create_portal_invitation(_client_id uuid, _email text, _full_name text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _org uuid;
  _grade integer;
  _client_org uuid;
  _client_name text;
  _existing uuid;
  _inv RECORD;
BEGIN
  SELECT p.organization_id, p.grade_level INTO _org, _grade
  FROM profiles p WHERE p.id = auth.uid();

  IF _grade IS NULL OR _grade > 3 THEN
    RAISE EXCEPTION 'Accès refusé : invitation réservée aux responsables';
  END IF;

  IF _email IS NULL OR _email !~ '^[^@\s]+@[^@\s]+\.[^@\s]+$' THEN
    RAISE EXCEPTION 'Adresse email invalide';
  END IF;

  SELECT c.organization_id, c.name INTO _client_org, _client_name
  FROM clients c WHERE c.id = _client_id;

  IF _client_org IS NULL THEN
    RAISE EXCEPTION 'Client introuvable';
  END IF;
  IF _client_org <> _org THEN
    RAISE EXCEPTION 'Ce client n''appartient pas à votre organisation';
  END IF;

  -- Refus si l'email est déjà un membre du cabinet (étanchéité des deux mondes)
  IF EXISTS (SELECT 1 FROM profiles p WHERE lower(p.email) = lower(_email)) THEN
    RAISE EXCEPTION 'Cette adresse correspond à un membre du cabinet. Utilisez une adresse distincte pour l''accès client.';
  END IF;

  -- Un compte client actif existe-t-il déjà pour cet email ?
  SELECT pu.id INTO _existing FROM portal_users pu
  WHERE lower(pu.email) = lower(_email) AND pu.is_active;

  IF _existing IS NOT NULL THEN
    RAISE EXCEPTION 'Un accès client existe déjà pour cette adresse';
  END IF;

  -- Annuler une invitation précédente encore en attente
  UPDATE portal_invitations
     SET status = 'revoked', revoked_at = now(), revoked_by = auth.uid()
   WHERE client_id = _client_id
     AND lower(email) = lower(_email)
     AND status = 'pending';

  INSERT INTO portal_invitations
    (organization_id, client_id, email, full_name, invited_by)
  VALUES (_org, _client_id, lower(_email), _full_name, auth.uid())
  RETURNING * INTO _inv;

  RETURN jsonb_build_object(
    'success', true,
    'invitation_id', _inv.id,
    'token', _inv.token,
    'email', _inv.email,
    'client_name', _client_name,
    'expires_at', _inv.expires_at
  );
END;
$function$
;

-- create_project_with_members(_mission_id uuid, _name text, _description text, _lead_id uuid, _budget_allocated numeric, _start_date date, _end_date date)
CREATE OR REPLACE FUNCTION public.create_project_with_members(_mission_id uuid, _name text, _description text DEFAULT NULL::text, _lead_id uuid DEFAULT NULL::uuid, _budget_allocated numeric DEFAULT NULL::numeric, _start_date date DEFAULT NULL::date, _end_date date DEFAULT NULL::date)
 RETURNS projects
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _user_id uuid := auth.uid();
  _org_id uuid;
  _grade_level integer;
  _mission_org_id uuid;
  _project public.projects;
  _code text;
  _year text := to_char(now(), 'YYYY');
BEGIN
  IF _user_id IS NULL THEN
    RAISE EXCEPTION 'Utilisateur non authentifié';
  END IF;

  SELECT p.organization_id, COALESCE(p.grade_level, 8)
    INTO _org_id, _grade_level
  FROM public.profiles p
  WHERE p.id = _user_id;

  IF _org_id IS NULL THEN
    RAISE EXCEPTION 'Votre profil n''est rattaché à aucune organisation';
  END IF;

  SELECT m.organization_id
    INTO _mission_org_id
  FROM public.missions m
  WHERE m.id = _mission_id;

  IF _mission_org_id IS NULL THEN
    RAISE EXCEPTION 'Mission introuvable';
  END IF;

  IF _mission_org_id <> _org_id THEN
    RAISE EXCEPTION 'La mission sélectionnée est invalide pour votre organisation';
  END IF;

  IF _grade_level > 3 AND NOT public.can_access_mission(_user_id, _mission_id) THEN
    RAISE EXCEPTION 'Vous n''avez pas le droit de créer un projet sur cette mission';
  END IF;

  IF NULLIF(trim(_name), '') IS NULL THEN
    RAISE EXCEPTION 'Le nom du projet est obligatoire';
  END IF;

  IF _lead_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM public.profiles p WHERE p.id = _lead_id AND p.organization_id = _org_id
  ) THEN
    RAISE EXCEPTION 'Le chef de projet sélectionné est invalide pour votre organisation';
  END IF;

  SELECT 'PRJ-' || _year || '-' || lpad((COUNT(*) + 1)::text, 3, '0')
    INTO _code
  FROM public.projects p
  WHERE p.mission_id = _mission_id
    AND p.code LIKE 'PRJ-' || _year || '-%';

  INSERT INTO public.projects (
    mission_id,
    organization_id,
    name,
    description,
    code,
    status,
    lead_id,
    budget_allocated,
    start_date,
    end_date
  ) VALUES (
    _mission_id,
    _org_id,
    trim(_name),
    NULLIF(trim(COALESCE(_description, '')), ''),
    _code,
    'planning',
    _lead_id,
    COALESCE(_budget_allocated, 0),
    _start_date,
    _end_date
  )
  RETURNING * INTO _project;

  INSERT INTO public.project_members (project_id, user_id, role)
  VALUES (
    _project.id,
    _user_id,
    CASE WHEN _lead_id = _user_id THEN 'lead' ELSE 'member' END
  )
  ON CONFLICT (project_id, user_id) DO UPDATE SET role = EXCLUDED.role;

  IF _lead_id IS NOT NULL THEN
    INSERT INTO public.project_members (project_id, user_id, role)
    VALUES (_project.id, _lead_id, 'lead')
    ON CONFLICT (project_id, user_id) DO UPDATE SET role = EXCLUDED.role;
  END IF;

  RETURN _project;
END;
$function$
;

-- creer_les_dossiers_de_mission(_mission_id uuid)
CREATE OR REPLACE FUNCTION public.creer_les_dossiers_de_mission(_mission_id uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _org uuid;
  _client uuid;
  _n integer := 0;
BEGIN
  SELECT organization_id INTO _org FROM public.missions WHERE id = _mission_id;
  IF _org IS NULL THEN RETURN 0; END IF;

  -- Le conteneur « Dossier client ».
  INSERT INTO public.document_folders (organization_id, mission_id, parent_id, name, kind, is_system)
  VALUES (_org, _mission_id, NULL, 'Dossier client', 'dossier_client', true)
  ON CONFLICT (mission_id, kind) WHERE kind IS NOT NULL DO NOTHING;

  SELECT id INTO _client FROM public.document_folders
   WHERE mission_id = _mission_id AND kind = 'dossier_client';

  -- Les trois niveaux de chargement et le dossier des rapports, sous le conteneur.
  INSERT INTO public.document_folders (organization_id, mission_id, parent_id, name, kind, is_system)
  VALUES
    (_org, _mission_id, _client, 'Dossier permanent', 'dossier_permanent', true),
    (_org, _mission_id, _client, 'Dossier important', 'dossier_important', true),
    (_org, _mission_id, _client, 'Dossier courant',   'dossier_courant',   true),
    (_org, _mission_id, _client, 'Dossier Rapport et synthèse', 'dossier_rapport_synthese', true)
  ON CONFLICT (mission_id, kind) WHERE kind IS NOT NULL DO NOTHING;

  SELECT count(*) INTO _n FROM public.document_folders
   WHERE mission_id = _mission_id AND is_system;
  RETURN _n;
END $function$
;

-- current_portal_client()
CREATE OR REPLACE FUNCTION public.current_portal_client()
 RETURNS uuid
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT pu.client_id FROM public.portal_users pu
  WHERE pu.id = auth.uid() AND pu.is_active;
$function$
;

-- decide_evaluation_arbitration(_evaluation_id uuid, _decision text, _comment text, _revised_score numeric)
CREATE OR REPLACE FUNCTION public.decide_evaluation_arbitration(_evaluation_id uuid, _decision text, _comment text, _revised_score numeric DEFAULT NULL::numeric)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _grade int; _org uuid; _e RECORD;
BEGIN
  SELECT p.organization_id, p.grade_level INTO _org, _grade
  FROM profiles p WHERE p.id = auth.uid();
  IF COALESCE(_grade, 99) > 1 THEN
    RAISE EXCEPTION 'Accès refusé : la décision d''arbitrage relève du Directeur Associé';
  END IF;
  IF _decision NOT IN ('maintien', 'revision', 'annulation') THEN
    RAISE EXCEPTION 'Décision invalide';
  END IF;
  IF _comment IS NULL OR length(trim(_comment)) < 10 THEN
    RAISE EXCEPTION 'La décision doit être motivée';
  END IF;

  SELECT * INTO _e FROM evaluations WHERE id = _evaluation_id AND organization_id = _org;
  IF _e IS NULL THEN RAISE EXCEPTION 'Évaluation introuvable'; END IF;

  UPDATE evaluation_arbitrations
     SET decision = _decision, decision_comment = _comment,
         revised_score = _revised_score, decided_by = auth.uid(), decided_at = now()
   WHERE evaluation_id = _evaluation_id AND decided_at IS NULL;

  UPDATE evaluations
     SET status = 'cloturee',
         weighted_score = CASE WHEN _decision = 'revision' AND _revised_score IS NOT NULL
                               THEN _revised_score ELSE weighted_score END,
         updated_at = now()
   WHERE id = _evaluation_id;

  INSERT INTO evaluation_exchanges (evaluation_id, round, actor_id, action, message, score_after)
  VALUES (_evaluation_id, _e.round_count, auth.uid(), 'arbitrage_decision', _comment,
          COALESCE(_revised_score, _e.weighted_score));

  INSERT INTO notifications (user_id, type, title, content, entity_type, entity_id, priority)
  SELECT unnest(ARRAY[_e.evaluator_id, _e.evaluatee_id]), 'evaluation_arbitration_decided',
    'Décision d''arbitrage', 'Décision : ' || _decision || '. ' || _comment,
    'evaluation', _evaluation_id, 'high';

  RETURN jsonb_build_object('success', true, 'decision', _decision);
END; $function$
;

-- designation_coherente()
CREATE OR REPLACE FUNCTION public.designation_coherente()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _org_ev uuid; _org_ee uuid;
  _gr_ev smallint; _gr_ee smallint;
  _ro_ev smallint; _ro_ee smallint;
BEGIN
  SELECT organization_id, COALESCE(grade_level, 8) INTO _org_ev, _gr_ev
  FROM public.profiles WHERE id = NEW.evaluator_id;
  SELECT organization_id, COALESCE(grade_level, 8) INTO _org_ee, _gr_ee
  FROM public.profiles WHERE id = NEW.evaluatee_id;

  IF _org_ev IS NULL OR _org_ee IS NULL OR _org_ev <> _org_ee THEN
    RAISE EXCEPTION 'L''evaluateur et l''evalue doivent appartenir au meme cabinet.';
  END IF;

  IF NEW.organization_id IS NULL THEN
    NEW.organization_id := _org_ee;
  ELSIF NEW.organization_id <> _org_ee THEN
    RAISE EXCEPTION 'La designation ne porte pas le cabinet de l''evalue.';
  END IF;

  IF NEW.eval_type = 'mission' THEN
    -- Dans une mission, le role prime sur le grade.
    SELECT min(public.niveau_role(mm.role)) INTO _ro_ev
    FROM public.mission_members mm
    WHERE mm.mission_id = NEW.mission_id AND mm.user_id = NEW.evaluator_id;

    SELECT min(public.niveau_role(mm.role)) INTO _ro_ee
    FROM public.mission_members mm
    WHERE mm.mission_id = NEW.mission_id AND mm.user_id = NEW.evaluatee_id;

    IF _ro_ee IS NULL THEN
      RAISE EXCEPTION 'L''evalue n''est pas membre de cette mission : il n''y a rien a y evaluer.';
    END IF;
    IF _ro_ev IS NULL THEN
      RAISE EXCEPTION 'L''evaluateur n''est pas membre de cette mission : il n''en voit rien, il ne peut pas l''evaluer.';
    END IF;
    -- Strictement : deux pairs ne s'evaluent pas, c'est votre regle des pairs.
    IF _ro_ev >= _ro_ee THEN
      RAISE EXCEPTION 'Dans une mission, l''evaluateur doit avoir un role superieur a celui de l''evalue. Ici, le role de l''evaluateur n''est pas au-dessus.';
    END IF;

  ELSE
    -- Dossier comptable et evaluation annuelle : le grade decide, comme vous
    -- l'avez pose pour les dossiers comptables.
    IF _gr_ev >= _gr_ee THEN
      RAISE EXCEPTION 'Hors mission, l''evaluateur doit etre d''un grade superieur a celui de l''evalue.';
    END IF;

    IF NEW.eval_type = 'annuelle' AND NEW.exercice IS NULL THEN
      RAISE EXCEPTION 'Une evaluation annuelle porte sur un exercice : renseignez-le.';
    END IF;
  END IF;

  IF NEW.assigned_by IS NULL THEN
    NEW.assigned_by := auth.uid();
  END IF;

  RETURN NEW;
END $function$
;

-- dirige_la_mission_du_dossier(_user_id uuid, _folder_id uuid)
CREATE OR REPLACE FUNCTION public.dirige_la_mission_du_dossier(_user_id uuid, _folder_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT EXISTS (
    SELECT 1 FROM public.mission_members mm
    WHERE mm.mission_id = public.mission_du_dossier(_folder_id)
      AND mm.user_id = _user_id
      AND public.niveau_role(mm.role) <= 3
  );
$function$
;

-- disponibilite(_debut date, _fin date)
CREATE OR REPLACE FUNCTION public.disponibilite(_debut date, _fin date)
 RETURNS TABLE(collaborateur_id uuid, collaborateur text, grade text, staffe boolean, missions text, jours_ouvrables integer, capacite_heures numeric, heures_planifiees numeric, heures_imputees numeric, heures_disponibles numeric, taux_occupation numeric)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  WITH mon_org AS (
    SELECT p.organization_id AS org FROM public.profiles p WHERE p.id = auth.uid()
  ),
  gens AS (
    SELECT p.id, p.full_name, p.grade, p.organization_id
    FROM public.profiles p, mon_org
    WHERE p.organization_id = mon_org.org
      AND p.grade_level IS NOT NULL
      -- La disponibilite est une donnee personnelle : on ne voit que ceux
      -- qu'on a le droit de voir, et soi-meme.
      AND (p.id = auth.uid() OR public.can_see_user_info(auth.uid(), p.id))
  )
  SELECT
    g.id,
    g.full_name,
    g.grade,
    EXISTS (
      SELECT 1 FROM public.mission_members mm
      JOIN public.missions m ON m.id = mm.mission_id
      WHERE mm.user_id = g.id AND public.mission_occupe(m.status)
    ) AS staffe,
    -- Les missions NOMMEES sont celles dont l'observateur fait partie. Les
    -- autres sont comptees, jamais nommees : savoir qu'un collaborateur est
    -- occupe est une donnee de charge, savoir PAR QUOI est une donnee de
    -- mission.
    COALESCE(
      NULLIF(concat_ws(', ',
        (SELECT string_agg(DISTINCT m.name, ', ' ORDER BY m.name)
         FROM public.mission_members mm
         JOIN public.missions m ON m.id = mm.mission_id
         WHERE mm.user_id = g.id AND public.mission_occupe(m.status)
           AND (g.id = auth.uid() OR public.can_access_mission(auth.uid(), m.id))),
        (SELECT CASE WHEN count(*) = 0 THEN NULL
                     WHEN count(*) = 1 THEN '1 mission hors de votre portee'
                     ELSE count(*)||' missions hors de votre portee' END
         FROM (SELECT DISTINCT m.id
               FROM public.mission_members mm
               JOIN public.missions m ON m.id = mm.mission_id
               WHERE mm.user_id = g.id AND public.mission_occupe(m.status)
                 AND g.id <> auth.uid()
                 AND NOT public.can_access_mission(auth.uid(), m.id)) s)
      ), ''), '—') AS missions,
    public.jours_ouvrables(_debut, _fin, g.organization_id) AS jours_ouvrables,
    (public.jours_ouvrables(_debut, _fin, g.organization_id)
      * COALESCE((SELECT o.working_hours_per_day FROM public.organizations o
                   WHERE o.id = g.organization_id), 8))::numeric AS capacite_heures,
    COALESCE((SELECT sum(pe.planned_hours) FROM public.plan_entries pe
               WHERE pe.user_id = g.id AND pe.plan_date BETWEEN _debut AND _fin), 0)::numeric,
    COALESCE((SELECT sum(te.hours) FROM public.time_entries te
               WHERE te.user_id = g.id AND te.date BETWEEN _debut AND _fin), 0)::numeric,
    -- Le reste se mesure sur le PLUS GRAND du planifie et de l'impute : pour
    -- les jours a venir c'est le plan qui engage, pour les jours ecoules
    -- c'est le temps reellement passe qui fait foi.
    GREATEST(
      (public.jours_ouvrables(_debut, _fin, g.organization_id)
        * COALESCE((SELECT o.working_hours_per_day FROM public.organizations o
                     WHERE o.id = g.organization_id), 8))
      - GREATEST(
          COALESCE((SELECT sum(pe.planned_hours) FROM public.plan_entries pe
                     WHERE pe.user_id = g.id AND pe.plan_date BETWEEN _debut AND _fin), 0),
          COALESCE((SELECT sum(te.hours) FROM public.time_entries te
                     WHERE te.user_id = g.id AND te.date BETWEEN _debut AND _fin), 0)),
      0)::numeric AS heures_disponibles,
    CASE WHEN public.jours_ouvrables(_debut, _fin, g.organization_id) = 0 THEN NULL
         ELSE round(
           100 * GREATEST(
             COALESCE((SELECT sum(pe.planned_hours) FROM public.plan_entries pe
                        WHERE pe.user_id = g.id AND pe.plan_date BETWEEN _debut AND _fin), 0),
             COALESCE((SELECT sum(te.hours) FROM public.time_entries te
                        WHERE te.user_id = g.id AND te.date BETWEEN _debut AND _fin), 0))
           / (public.jours_ouvrables(_debut, _fin, g.organization_id)
              * COALESCE((SELECT o.working_hours_per_day FROM public.organizations o
                           WHERE o.id = g.organization_id), 8)), 1)
    END AS taux_occupation
  FROM gens g
  ORDER BY staffe, g.full_name;
$function$
;

-- dossier_exercice_window(_dossier_id uuid, _exercice smallint)
CREATE OR REPLACE FUNCTION public.dossier_exercice_window(_dossier_id uuid, _exercice smallint)
 RETURNS TABLE(period_start date, period_end date)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _em smallint; _org uuid; _fsm smallint;
  _fs date; _fe date; _c1 date; _c2 date; _close date;
BEGIN
  SELECT COALESCE(f.exercice_end_month, 12), f.organization_id
    INTO _em, _org
  FROM client_fiscal_profile f WHERE f.id = _dossier_id;
  IF _em IS NULL THEN RETURN; END IF;

  -- La fenêtre de l'exercice DU CABINET : c'est elle que porte la colonne
  -- evaluations.exercice, et c'est elle qui sert à la synthèse annuelle.
  SELECT COALESCE(fiscal_year_start_month, 1) INTO _fsm
  FROM organizations WHERE id = _org;
  _fs := make_date(_exercice::int, COALESCE(_fsm,1)::int, 1);
  _fe := (_fs + INTERVAL '1 year - 1 day')::date;

  -- L'exercice comptable du client évalué est celui qui s'est CLÔTURÉ dans
  -- l'exercice du cabinet. Un cabinet qui clôture en juin évalue ainsi, sur
  -- son exercice 2025 (juillet 2025 → juin 2026), le dossier d'un client qui
  -- a clôturé au 31 décembre 2025.
  _c1 := (make_date(EXTRACT(YEAR FROM _fs)::int, _em::int, 1)
            + INTERVAL '1 month - 1 day')::date;
  _c2 := (make_date(EXTRACT(YEAR FROM _fe)::int, _em::int, 1)
            + INTERVAL '1 month - 1 day')::date;

  IF    _c1 BETWEEN _fs AND _fe THEN _close := _c1;
  ELSIF _c2 BETWEEN _fs AND _fe THEN _close := _c2;
  ELSE  _close := _c2;   -- exercices cabinet et client alignés au même mois
  END IF;

  RETURN QUERY SELECT
    (_close + INTERVAL '1 day' - INTERVAL '1 year')::date,
    _close;
END; $function$
;

-- dossier_label(_dossier_id uuid)
CREATE OR REPLACE FUNCTION public.dossier_label(_dossier_id uuid)
 RETURNS text
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT c.name
  FROM client_fiscal_profile f JOIN clients c ON c.id = f.client_id
  WHERE f.id = _dossier_id;
$function$
;

-- dossier_participants(_dossier_id uuid, _exercice smallint)
CREATE OR REPLACE FUNCTION public.dossier_participants(_dossier_id uuid, _exercice smallint)
 RETURNS TABLE(user_id uuid)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _client uuid; _s date; _e date;
BEGIN
  SELECT f.client_id INTO _client
  FROM client_fiscal_profile f WHERE f.id = _dossier_id;
  IF _client IS NULL THEN RETURN; END IF;

  SELECT w.period_start, w.period_end INTO _s, _e
  FROM public.dossier_exercice_window(_dossier_id, _exercice) w;

  RETURN QUERY
  SELECT DISTINCT u FROM (
    SELECT op.assigned_to AS u FROM obligation_periods op
     WHERE op.client_id = _client AND op.status <> 'na'
       AND op.period_end BETWEEN _s AND _e
    UNION
    SELECT op.deposed_by FROM obligation_periods op
     WHERE op.client_id = _client AND op.status <> 'na'
       AND op.period_end BETWEEN _s AND _e
    UNION
    SELECT o.responsible_id FROM client_obligations o
     WHERE o.client_id = _client AND COALESCE(o.is_active, true)
    UNION
    SELECT f.collaborateur_id FROM client_fiscal_profile f
     WHERE f.id = _dossier_id
  ) s WHERE u IS NOT NULL;
END; $function$
;

-- dossier_systeme_protege()
CREATE OR REPLACE FUNCTION public.dossier_systeme_protege()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF TG_OP = 'DELETE' THEN
    -- On reconnait une CASCADE a ceci : la mission qui portait ce dossier
    -- n'existe deja plus, PostgreSQL ayant supprime le parent d'abord. On
    -- laisse alors les dossiers partir avec leur mission.
    IF OLD.mission_id IS NOT NULL
       AND NOT EXISTS (SELECT 1 FROM public.missions m WHERE m.id = OLD.mission_id) THEN
      RETURN OLD;
    END IF;

    -- Suppression directe d'un dossier de structure : toujours refusee.
    IF OLD.is_system THEN
      RAISE EXCEPTION
        'Le dossier « % » fait partie de la structure de la mission : il ne se supprime pas. Supprimez la mission si c''est ce que vous voulez.',
        OLD.name;
    END IF;
    RETURN OLD;
  END IF;

  IF OLD.is_system AND NEW.kind IS DISTINCT FROM OLD.kind THEN
    RAISE EXCEPTION 'La sorte du dossier « % » ne se change pas : elle porte ses droits d''acces.', OLD.name;
  END IF;
  IF OLD.is_system AND NEW.mission_id IS DISTINCT FROM OLD.mission_id THEN
    RAISE EXCEPTION 'Un dossier de la structure ne change pas de mission.';
  END IF;
  RETURN NEW;
END $function$
;

-- dossiers_de_la_mission(_mission_id uuid)
CREATE OR REPLACE FUNCTION public.dossiers_de_la_mission(_mission_id uuid)
 RETURNS TABLE(id uuid, sorte text, nom text, parent_id uuid, profondeur smallint, ordre smallint, est_structure boolean, peut_deposer boolean, peut_supprimer boolean, pieces bigint)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT
    f.id,
    f.kind AS sorte,
    f.name AS nom,
    f.parent_id,
    (CASE WHEN f.parent_id IS NULL THEN 0 ELSE 1 END)::smallint AS profondeur,
    (CASE f.kind
       WHEN 'dossier_client'            THEN 1
       WHEN 'dossier_permanent'  THEN 2
       WHEN 'dossier_important'  THEN 3
       WHEN 'dossier_courant'    THEN 4
       WHEN 'dossier_rapport_synthese'  THEN 5
       ELSE 6
     END)::smallint AS ordre,
    f.is_system AS est_structure,
    public.peut_deposer_dans_dossier(auth.uid(), f.id) AS peut_deposer,
    -- Supprimer une piece du dossier : la direction de la mission.
    public.dirige_la_mission_du_dossier(auth.uid(), f.id) AS peut_supprimer,
    (SELECT count(*) FROM public.documents d WHERE d.folder_id = f.id) AS pieces
  FROM public.document_folders f
  WHERE public.mission_du_dossier(f.id) = _mission_id
    -- Ce qu'on n'a pas le droit de voir n'apparait pas.
    AND public.peut_voir_dossier(auth.uid(), f.id)
  ORDER BY ordre, f.name;
$function$
;

-- doter_la_mission_de_ses_dossiers()
CREATE OR REPLACE FUNCTION public.doter_la_mission_de_ses_dossiers()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  PERFORM public.creer_les_dossiers_de_mission(NEW.id);
  RETURN NEW;
END $function$
;

-- echelon_occupe_protege()
CREATE OR REPLACE FUNCTION public.echelon_occupe_protege()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _qui text; _combien int;
BEGIN
  IF TG_OP = 'DELETE' THEN
    SELECT count(*), string_agg(p.full_name, ', ' ORDER BY p.full_name)
      INTO _combien, _qui
    FROM public.profiles p
    WHERE p.organization_id = OLD.organization_id
      AND p.practice = OLD.practice
      AND lower(btrim(p.grade_echelon)) = lower(btrim(OLD.echelon));

    IF _combien > 0 THEN
      RAISE EXCEPTION
        'L''echelon « % » est occupe par % collaborateur(s) : %. Leur rang deviendrait indetermine, et leurs droits avec. Deplacez-les d''abord.',
        OLD.echelon, _combien, _qui;
    END IF;

    -- Il peut aussi vivre dans l'historique des grades, qui est une archive :
    -- le supprimer rendrait les promotions passees illisibles.
    IF EXISTS (SELECT 1 FROM public.grade_history gh
                WHERE gh.organization_id = OLD.organization_id
                  AND gh.practice = OLD.practice
                  AND lower(btrim(gh.grade_echelon)) = lower(btrim(OLD.echelon))) THEN
      RAISE EXCEPTION
        'L''echelon « % » figure dans l''historique des grades : le supprimer rendrait cet historique illisible. Desactivez-le plutot (is_active = false), une fois qu''il est vide.',
        OLD.echelon;
    END IF;

    RETURN OLD;
  END IF;

  -- Combien de collaborateurs y sont assis aujourd'hui ?
  SELECT count(*), string_agg(p.full_name, ', ' ORDER BY p.full_name)
    INTO _combien, _qui
  FROM public.profiles p
  WHERE p.organization_id = OLD.organization_id
    AND p.practice = OLD.practice
    AND lower(btrim(p.grade_echelon)) = lower(btrim(OLD.echelon));

  -- Desactiver un echelon occupe : meme objection que le supprimer.
  IF OLD.is_active AND NOT NEW.is_active AND _combien > 0 THEN
    RAISE EXCEPTION
      'L''echelon « % » est occupe par % collaborateur(s) : %. On ne le desactive pas tant qu''ils y sont.',
      OLD.echelon, _combien, _qui;
  END IF;

  -- Le renommer est pire que le supprimer : le rattachement se fait par le
  -- texte, et casserait sans la moindre erreur.
  IF lower(btrim(NEW.echelon)) IS DISTINCT FROM lower(btrim(OLD.echelon))
     AND _combien > 0
     AND COALESCE(current_setting('dgc.renommage_echelon', true), '') <> 'oui' THEN
    RAISE EXCEPTION
      'L''echelon « % » est occupe par % collaborateur(s) : le renommer directement casserait leur rattachement en silence. Passez par renommer_echelon(id, nouveau_nom), qui propage le nouveau nom aux profils et a l''historique.',
      OLD.echelon, _combien;
  END IF;

  RETURN NEW;
END $function$
;

-- echelons_promouvables(_user_id uuid)
CREATE OR REPLACE FUNCTION public.echelons_promouvables(_user_id uuid)
 RETURNS TABLE(echelon text, grade text, rang smallint, sens text)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _p RECORD; _rk smallint;
BEGIN
  SELECT organization_id, practice INTO _p FROM profiles WHERE id = _user_id;
  _rk := public.profile_rank(_user_id);

  RETURN QUERY
  SELECT g.echelon, g.maps_to_grade, g.rank,
         CASE WHEN _rk IS NULL      THEN 'premiere affectation'
              WHEN g.rank > _rk     THEN 'promotion'
              WHEN g.rank < _rk     THEN 'retrogradation'
              ELSE 'echelon actuel' END
  FROM evaluation_grades g
  WHERE g.organization_id = _p.organization_id
    AND g.practice = _p.practice
    AND g.is_active
  ORDER BY g.rank DESC;
END; $function$
;

-- encadrer_invitation()
CREATE OR REPLACE FUNCTION public.encadrer_invitation()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.token IS NULL OR length(NEW.token) < 32 THEN
    RAISE EXCEPTION 'Jeton d''invitation trop court : 32 caracteres au moins.';
  END IF;
  NEW.email      := lower(trim(NEW.email));
  NEW.status     := 'pending';
  NEW.role       := 'member';
  NEW.expires_at := now() + interval '7 days';
  NEW.created_at := now();
  IF auth.uid() IS NOT NULL THEN
    NEW.invited_by := auth.uid();
  END IF;
  RETURN NEW;
END;
$function$
;

-- enforce_composition_avant_activation()
CREATE OR REPLACE FUNCTION public.enforce_composition_avant_activation()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _liste text := ''; _d RECORD;
BEGIN
  IF NEW.status <> 'active' OR COALESCE(OLD.status, '') = 'active' THEN
    RETURN NEW;
  END IF;

  FOR _d IN SELECT * FROM public.mission_composition_defauts(NEW.id) LOOP
    _liste := _liste || format(E'\n  · %s : %s', _d.defaut, _d.detail);
  END LOOP;

  IF _liste <> '' THEN
    -- Un seul %, un seul argument : en plpgsql, %% est un pourcent litteral
    -- et ne consomme rien.
    RAISE EXCEPTION 'Cette mission ne peut pas devenir active, sa composition est incomplete :%',
      _liste || E'\n\n  Completez l''equipe, puis reessayez.';
  END IF;

  RETURN NEW;
END; $function$
;

-- enforce_mission_role_rank()
CREATE OR REPLACE FUNCTION public.enforce_mission_role_rank()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _rank smallint; _min smallint; _max smallint;
BEGIN
  _min := public.mission_role_min_rank(NEW.role);
  _max := public.mission_role_max_rank(NEW.role);
  IF _min IS NULL THEN RETURN NEW; END IF;   -- hors vocabulaire : le CHECK tranche

  _rank := public.profile_rank(NEW.user_id);

  IF _rank IS NULL THEN
    IF NEW.role = 'auditeur_junior' THEN RETURN NEW; END IF;
    RAISE EXCEPTION
      'Renseignez le grade et l''echelon de ce collaborateur avant de lui confier le role "%"', NEW.role;
  END IF;

  IF _rank < _min THEN
    RAISE EXCEPTION
      'Grade insuffisant pour le role "%" : rang % atteint, rang % requis au minimum',
      NEW.role, _rank, _min;
  END IF;

  IF _rank > _max THEN
    RAISE EXCEPTION
      'Grade trop eleve pour le role "%" : rang % atteint, rang % au maximum. Un grade superieur appelle un autre role.',
      NEW.role, _rank, _max;
  END IF;

  RETURN NEW;
END; $function$
;

-- enforce_mission_tenant()
CREATE OR REPLACE FUNCTION public.enforce_mission_tenant()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _org_mission uuid; _org_membre uuid; _nom_mission text;
BEGIN
  SELECT m.organization_id, m.name INTO _org_mission, _nom_mission
  FROM missions m WHERE m.id = NEW.mission_id;

  -- Mission inconnue : la clé étrangère tranchera, ce n'est pas notre rôle.
  IF _org_mission IS NULL THEN RETURN NEW; END IF;

  SELECT p.organization_id INTO _org_membre
  FROM profiles p WHERE p.id = NEW.user_id;

  IF _org_membre IS NULL THEN
    RAISE EXCEPTION
      'Ce collaborateur n''est rattache a aucun cabinet : rattachez sa fiche avant de l''inscrire a une mission';
  END IF;

  IF _org_membre <> _org_mission THEN
    RAISE EXCEPTION
      'Cloison entre cabinets : ce collaborateur appartient a un autre cabinet que la mission « % »',
      COALESCE(_nom_mission, '?');
  END IF;

  -- Sur le staffing, la colonne organization_id doit suivre la mission.
  IF TG_TABLE_NAME = 'staffing_assignments' THEN
    IF NEW.organization_id IS NULL THEN
      NEW.organization_id := _org_mission;
    ELSIF NEW.organization_id <> _org_mission THEN
      RAISE EXCEPTION
        'L''affectation porte un cabinet different de celui de sa mission';
    END IF;
  END IF;

  RETURN NEW;
END; $function$
;

-- est_affecte_a_la_tache(_user_id uuid, _task_id uuid)
CREATE OR REPLACE FUNCTION public.est_affecte_a_la_tache(_user_id uuid, _task_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT EXISTS (
    SELECT 1 FROM public.task_assignments ta
    WHERE ta.task_id = _task_id AND ta.user_id = _user_id
  );
$function$
;

-- est_designe_pour_evaluer(_evaluateur uuid, _evalue uuid, _mission uuid, _dossier uuid, _exercice smallint)
CREATE OR REPLACE FUNCTION public.est_designe_pour_evaluer(_evaluateur uuid, _evalue uuid, _mission uuid, _dossier uuid, _exercice smallint)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT EXISTS (
    SELECT 1 FROM public.evaluation_assignments ea
    WHERE ea.evaluator_id = _evaluateur
      AND ea.evaluatee_id = _evalue
      AND ea.status <> 'annulee'
      AND ea.mission_id IS NOT DISTINCT FROM _mission
      AND ea.dossier_id IS NOT DISTINCT FROM _dossier
      AND (ea.exercice IS NULL OR _exercice IS NULL OR ea.exercice = _exercice)
  );
$function$
;

-- est_directeur_associe(_user_id uuid)
CREATE OR REPLACE FUNCTION public.est_directeur_associe(_user_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT EXISTS (
    SELECT 1 FROM public.profiles p
    WHERE p.id = _user_id
      AND p.organization_id IS NOT NULL
      AND COALESCE(p.grade_level, 8) = 1
  );
$function$
;

-- est_direction_du_cabinet(_org text)
CREATE OR REPLACE FUNCTION public.est_direction_du_cabinet(_org text)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT EXISTS (SELECT 1 FROM public.profiles p
    WHERE p.id = auth.uid() AND p.organization_id::text = _org AND p.grade_level <= 2)
$function$
;

-- est_plomberie_de_compte(_table text)
CREATE OR REPLACE FUNCTION public.est_plomberie_de_compte(_table text)
 RETURNS boolean
 LANGUAGE sql
 IMMUTABLE
AS $function$
  SELECT _table LIKE 'auth.%'
      OR _table IN ('profiles', 'public.profiles', 'user_roles', 'public.user_roles');
$function$
;

-- evaluation_designee()
CREATE OR REPLACE FUNCTION public.evaluation_designee()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  -- Hors session utilisateur (migration, reprise), on ne juge pas.
  IF auth.uid() IS NULL THEN RETURN NEW; END IF;

  -- Le directeur associe n'a pas besoin d'etre designe pour lui-meme.
  IF public.est_directeur_associe(auth.uid())
     AND NEW.evaluator_id = auth.uid() THEN
    RETURN NEW;
  END IF;

  IF NEW.evaluator_id <> auth.uid() THEN
    RAISE EXCEPTION 'On ne cree pas une evaluation au nom de quelqu''un d''autre.';
  END IF;

  IF NOT public.est_designe_pour_evaluer(
       NEW.evaluator_id, NEW.evaluatee_id, NEW.mission_id, NEW.dossier_id, NEW.exercice) THEN
    RAISE EXCEPTION 'Vous n''etes pas designe pour evaluer cette personne sur cet objet. C''est le directeur associe qui designe les evaluateurs.';
  END IF;

  RETURN NEW;
END $function$
;

-- evaluation_weight(_mode text, _weight_basis numeric, _period_start date, _period_end date)
CREATE OR REPLACE FUNCTION public.evaluation_weight(_mode text, _weight_basis numeric, _period_start date, _period_end date)
 RETURNS numeric
 LANGUAGE sql
 IMMUTABLE
AS $function$
  SELECT CASE _mode
    WHEN 'charge' THEN GREATEST(COALESCE(_weight_basis, 1), 0.01)
    WHEN 'duree'  THEN GREATEST(
      COALESCE((_period_end - _period_start)::numeric, 1), 1)
    ELSE 1
  END;
$function$
;

-- exercice_label(_exercice smallint, _org uuid)
CREATE OR REPLACE FUNCTION public.exercice_label(_exercice smallint, _org uuid)
 RETURNS text
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT CASE
    WHEN _exercice IS NULL THEN NULL
    WHEN COALESCE((SELECT fiscal_year_start_month FROM organizations WHERE id = _org), 1) = 1
      THEN _exercice::text
    ELSE _exercice::text || ' - ' || (_exercice + 1)::text
  END;
$function$
;

-- exercice_label_dossier(_dossier_id uuid, _exercice smallint)
CREATE OR REPLACE FUNCTION public.exercice_label_dossier(_dossier_id uuid, _exercice smallint)
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _s date; _e date;
BEGIN
  SELECT w.period_start, w.period_end INTO _s, _e
  FROM public.dossier_exercice_window(_dossier_id, _exercice) w;
  IF _s IS NULL THEN RETURN _exercice::text; END IF;
  IF EXTRACT(YEAR FROM _s) = EXTRACT(YEAR FROM _e)
  THEN RETURN EXTRACT(YEAR FROM _s)::int::text;
  ELSE RETURN EXTRACT(YEAR FROM _s)::int::text || ' - '
           || EXTRACT(YEAR FROM _e)::int::text;
  END IF;
END; $function$
;

-- expire_portal_invitations()
CREATE OR REPLACE FUNCTION public.expire_portal_invitations()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _n integer;
BEGIN
  UPDATE portal_invitations
     SET status = 'expired'
   WHERE status = 'pending' AND expires_at < now();
  GET DIAGNOSTICS _n = ROW_COUNT;
  RETURN _n;
END; $function$
;

-- fiscal_exercice(_d date, _org uuid)
CREATE OR REPLACE FUNCTION public.fiscal_exercice(_d date, _org uuid)
 RETURNS smallint
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT CASE
    WHEN _d IS NULL THEN NULL
    WHEN EXTRACT(MONTH FROM _d)::int >= COALESCE(
           (SELECT fiscal_year_start_month FROM organizations WHERE id = _org), 1)
      THEN EXTRACT(YEAR FROM _d)::smallint
    ELSE (EXTRACT(YEAR FROM _d)::int - 1)::smallint
  END;
$function$
;

-- generate_obligation_periods(_year integer, _month integer)
CREATE OR REPLACE FUNCTION public.generate_obligation_periods(_year integer, _month integer DEFAULT NULL::integer)
 RETURNS TABLE(created_count integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _org uuid;
  _grade integer;
  _rec RECORD;
  _m integer;
  _pstart date;
  _pend date;
  _due date;
  _label text;
  _count integer := 0;
BEGIN
  SELECT p.organization_id, p.grade_level INTO _org, _grade
  FROM profiles p WHERE p.id = auth.uid();

  IF _grade IS NULL OR _grade > 3 THEN
    RAISE EXCEPTION 'Accès refusé : génération réservée aux responsables';
  END IF;

  FOR _rec IN
    SELECT co.id AS cli_obl_id, co.client_id, co.responsible_id, co.custom_deadline_day,
           ot.id AS type_id, ot.code, ot.periodicite, ot.deadline_day,
           ot.deadline_month, ot.deadline_offset_months, ot.applies_to_regimes,
           cfp.regime_fiscal, cfp.collaborateur_id
    FROM client_obligations co
    JOIN obligation_types ot ON ot.id = co.obligation_type_id
    LEFT JOIN client_fiscal_profile cfp ON cfp.client_id = co.client_id
    WHERE co.organization_id = _org
      AND co.is_active = true
      AND ot.is_active = true
      AND (co.end_date IS NULL OR co.end_date >= make_date(_year, COALESCE(_month, 1), 1))
  LOOP
    -- Filtrer sur le régime fiscal si l'obligation le restreint
    CONTINUE WHEN _rec.applies_to_regimes IS NOT NULL
                  AND _rec.regime_fiscal IS NOT NULL
                  AND NOT (_rec.regime_fiscal = ANY(_rec.applies_to_regimes));

    IF _rec.periodicite = 'mensuelle' THEN
      FOR _m IN COALESCE(_month, 1)..COALESCE(_month, 12) LOOP
        _pstart := make_date(_year, _m, 1);
        _pend   := (_pstart + INTERVAL '1 month - 1 day')::date;
        _label  := to_char(_pstart, 'YYYY-MM');
        _due    := (_pstart
                    + make_interval(months => COALESCE(_rec.deadline_offset_months, 1))
                    + make_interval(days => COALESCE(_rec.custom_deadline_day, _rec.deadline_day, 15) - 1))::date;

        INSERT INTO obligation_periods
          (organization_id, client_id, client_obligation_id, obligation_type_id,
           period_label, period_start, period_end, due_date, assigned_to)
        VALUES (_org, _rec.client_id, _rec.cli_obl_id, _rec.type_id,
                _label, _pstart, _pend, _due,
                COALESCE(_rec.responsible_id, _rec.collaborateur_id))
        ON CONFLICT (client_id, obligation_type_id, period_label) DO NOTHING;
        IF FOUND THEN _count := _count + 1; END IF;
      END LOOP;

    ELSIF _rec.periodicite = 'trimestrielle' THEN
      FOR _m IN 1..4 LOOP
        CONTINUE WHEN _month IS NOT NULL AND _m <> ((_month - 1) / 3 + 1);
        _pstart := make_date(_year, (_m - 1) * 3 + 1, 1);
        _pend   := (_pstart + INTERVAL '3 months - 1 day')::date;
        _label  := 'T' || _m || ' ' || _year;
        _due    := (_pend + INTERVAL '1 day'
                    + make_interval(days => COALESCE(_rec.custom_deadline_day, _rec.deadline_day, 15) - 1))::date;

        INSERT INTO obligation_periods
          (organization_id, client_id, client_obligation_id, obligation_type_id,
           period_label, period_start, period_end, due_date, assigned_to)
        VALUES (_org, _rec.client_id, _rec.cli_obl_id, _rec.type_id,
                _label, _pstart, _pend, _due,
                COALESCE(_rec.responsible_id, _rec.collaborateur_id))
        ON CONFLICT (client_id, obligation_type_id, period_label) DO NOTHING;
        IF FOUND THEN _count := _count + 1; END IF;
      END LOOP;

    ELSIF _rec.periodicite = 'annuelle' THEN
      CONTINUE WHEN _month IS NOT NULL;   -- annuel généré seulement en mode année
      _pstart := make_date(_year, 1, 1);
      _pend   := make_date(_year, 12, 31);
      _label  := 'Exercice ' || _year;
      -- Échéance l'année suivante (dépôt sur N+1)
      _due    := make_date(_year + 1, COALESCE(_rec.deadline_month, 6),
                           LEAST(COALESCE(_rec.custom_deadline_day, _rec.deadline_day, 30), 28));

      INSERT INTO obligation_periods
        (organization_id, client_id, client_obligation_id, obligation_type_id,
         period_label, period_start, period_end, due_date, assigned_to)
      VALUES (_org, _rec.client_id, _rec.cli_obl_id, _rec.type_id,
              _label, _pstart, _pend, _due,
              COALESCE(_rec.responsible_id, _rec.collaborateur_id))
      ON CONFLICT (client_id, obligation_type_id, period_label) DO NOTHING;
      IF FOUND THEN _count := _count + 1; END IF;
    END IF;
  END LOOP;

  RETURN QUERY SELECT _count;
END;
$function$
;

-- generate_period_documents(_period_id uuid)
CREATE OR REPLACE FUNCTION public.generate_period_documents(_period_id uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _type_id uuid;
  _count integer := 0;
BEGIN
  SELECT obligation_type_id INTO _type_id
  FROM obligation_periods WHERE id = _period_id;

  INSERT INTO obligation_documents
    (obligation_period_id, document_type_id, label, is_required, status)
  SELECT _period_id, odt.id, odt.label, odt.is_required, 'attendue'
  FROM obligation_document_types odt
  WHERE odt.obligation_type_id = _type_id
    AND NOT EXISTS (
      SELECT 1 FROM obligation_documents od
      WHERE od.obligation_period_id = _period_id
        AND od.document_type_id = odt.id
    );
  GET DIAGNOSTICS _count = ROW_COUNT;
  RETURN _count;
END;
$function$
;

-- get_activity_detail(_target_user uuid, _start_date date, _end_date date)
CREATE OR REPLACE FUNCTION public.get_activity_detail(_target_user uuid, _start_date date DEFAULT ((CURRENT_DATE - '30 days'::interval))::date, _end_date date DEFAULT CURRENT_DATE)
 RETURNS TABLE(report_date date, active_seconds integer, idle_seconds integer, professional_seconds integer, professional_ratio numeric, category_breakdown jsonb, top_apps jsonb, files_synced integer, first_activity timestamp with time zone, last_activity timestamp with time zone)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
#variable_conflict use_column
DECLARE
  _viewer_org uuid;
  _viewer_grade integer;
  _target_org uuid;
BEGIN
  SELECT vp.organization_id, vp.grade_level
    INTO _viewer_org, _viewer_grade
  FROM public.profiles vp
  WHERE vp.id = auth.uid();

  SELECT tp.organization_id
    INTO _target_org
  FROM public.profiles tp
  WHERE tp.id = _target_user;

  -- Un collaborateur voit ses propres données ; DA/DM voient leur organisation
  IF NOT (
    _target_user = auth.uid()
    OR (_viewer_grade IS NOT NULL AND _viewer_grade <= 2 AND _viewer_org = _target_org)
  ) THEN
    RAISE EXCEPTION 'Accès refusé';
  END IF;

  RETURN QUERY
  SELECT
    ar.report_date,
    ar.active_seconds,
    ar.idle_seconds,
    ar.professional_seconds,
    CASE WHEN ar.active_seconds > 0
      THEN ROUND((ar.professional_seconds::numeric / ar.active_seconds) * 100)
      ELSE 0 END,
    ar.category_breakdown,
    ar.top_apps,
    ar.files_synced,
    ar.first_activity,
    ar.last_activity
  FROM public.activity_reports ar
  WHERE ar.user_id = _target_user
    AND ar.report_date BETWEEN _start_date AND _end_date
  ORDER BY ar.report_date DESC;
END;
$function$
;

-- get_activity_kpis(_start_date date, _end_date date)
CREATE OR REPLACE FUNCTION public.get_activity_kpis(_start_date date DEFAULT ((CURRENT_DATE - '7 days'::interval))::date, _end_date date DEFAULT CURRENT_DATE)
 RETURNS TABLE(total_collaborators bigint, active_collaborators bigint, avg_professional_ratio numeric, total_active_hours numeric, total_files_synced bigint)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
#variable_conflict use_column
DECLARE
  _viewer_org uuid;
  _viewer_grade integer;
BEGIN
  SELECT vp.organization_id, vp.grade_level
    INTO _viewer_org, _viewer_grade
  FROM public.profiles vp
  WHERE vp.id = auth.uid();

  IF _viewer_grade IS NULL OR _viewer_grade > 2 THEN
    RAISE EXCEPTION 'Accès refusé : supervision réservée aux directeurs';
  END IF;

  RETURN QUERY
  SELECT
    (SELECT COUNT(*) FROM public.profiles cp WHERE cp.organization_id = _viewer_org)::bigint,
    COUNT(DISTINCT ar.user_id)::bigint,
    COALESCE(CASE WHEN SUM(ar.active_seconds) > 0
      THEN ROUND((SUM(ar.professional_seconds)::numeric / SUM(ar.active_seconds)) * 100)
      ELSE 0 END, 0),
    COALESCE(ROUND(SUM(ar.active_seconds)::numeric / 3600, 1), 0),
    COALESCE(SUM(ar.files_synced), 0)::bigint
  FROM public.activity_reports ar
  WHERE ar.organization_id = _viewer_org
    AND ar.report_date BETWEEN _start_date AND _end_date;
END;
$function$
;

-- get_activity_supervision(_start_date date, _end_date date)
CREATE OR REPLACE FUNCTION public.get_activity_supervision(_start_date date DEFAULT ((CURRENT_DATE - '7 days'::interval))::date, _end_date date DEFAULT CURRENT_DATE)
 RETURNS TABLE(user_id uuid, full_name text, grade text, grade_level integer, days_active bigint, total_active_seconds bigint, total_professional_seconds bigint, avg_professional_ratio numeric, total_files_synced bigint, last_activity timestamp with time zone)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
#variable_conflict use_column
DECLARE
  _viewer_org uuid;
  _viewer_grade integer;
BEGIN
  -- Qualifier avec l'alias vp pour éviter l'ambiguïté avec les colonnes de sortie
  SELECT vp.organization_id, vp.grade_level
    INTO _viewer_org, _viewer_grade
  FROM public.profiles vp
  WHERE vp.id = auth.uid();

  IF _viewer_grade IS NULL OR _viewer_grade > 2 THEN
    RAISE EXCEPTION 'Accès refusé : supervision réservée aux directeurs';
  END IF;

  RETURN QUERY
  SELECT
    ar.user_id,
    p.full_name,
    p.grade,
    p.grade_level,
    COUNT(DISTINCT ar.report_date)::bigint,
    SUM(ar.active_seconds)::bigint,
    SUM(ar.professional_seconds)::bigint,
    CASE WHEN SUM(ar.active_seconds) > 0
      THEN ROUND((SUM(ar.professional_seconds)::numeric / SUM(ar.active_seconds)) * 100)
      ELSE 0 END,
    SUM(ar.files_synced)::bigint,
    MAX(ar.last_activity)
  FROM public.activity_reports ar
  JOIN public.profiles p ON p.id = ar.user_id
  WHERE ar.organization_id = _viewer_org
    AND ar.report_date BETWEEN _start_date AND _end_date
  GROUP BY ar.user_id, p.full_name, p.grade, p.grade_level
  ORDER BY 8 DESC;
END;
$function$
;

-- get_annual_campaign(_exercice smallint)
CREATE OR REPLACE FUNCTION public.get_annual_campaign(_exercice smallint DEFAULT NULL::smallint)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _org uuid; _grade int; _ex smallint;
BEGIN
 SELECT organization_id,grade_level INTO _org,_grade FROM profiles WHERE id=auth.uid();
 IF _org IS NULL OR COALESCE(_grade,99)>2 THEN RAISE EXCEPTION 'Accès refusé : suivi réservé à la direction'; END IF;
 _ex:=COALESCE(_exercice,public.fiscal_exercice(CURRENT_DATE,_org));
 RETURN jsonb_build_object('exercice',_ex,'lignes',COALESCE((SELECT jsonb_agg(jsonb_build_object('assignment_id',a.id,'evaluatee_id',a.evaluatee_id,'evaluator_id',a.evaluator_id,'evaluation_id',e.id,'collaborateur',pe.full_name,'grade',pe.grade,'echelon',pe.grade_echelon,'practice',pe.practice,'evaluateur',pr.full_name,'due_date',a.due_date,'statut',COALESCE(e.status,'non_ouverte'),'score',e.weighted_score,'appreciation',e.appreciation_label,'desaccord',COALESCE(e.disagreement,false),'nb_missions_exercice',(SELECT COUNT(*) FROM evaluations m WHERE m.evaluatee_id=a.evaluatee_id AND m.eval_type='mission' AND m.exercice=_ex AND m.status IN ('validee','cloturee'))) ORDER BY pe.grade_level,pe.full_name) FROM evaluation_assignments a JOIN profiles pe ON pe.id=a.evaluatee_id LEFT JOIN profiles pr ON pr.id=a.evaluator_id LEFT JOIN evaluations e ON e.assignment_id=a.id WHERE a.organization_id=_org AND a.eval_type='annuelle' AND a.exercice=_ex AND a.status<>'annulee'),'[]'::jsonb));
END $function$
;

-- get_client_dossiers()
CREATE OR REPLACE FUNCTION public.get_client_dossiers()
 RETURNS TABLE(client_id uuid, client_name text, regime_fiscal text, collaborateur_name text, nb_obligations bigint, nb_en_retard bigint, nb_a_faire bigint, prochaine_echeance date, sante text)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
#variable_conflict use_column
DECLARE
  _org uuid;
BEGIN
  SELECT p.organization_id INTO _org FROM profiles p WHERE p.id = auth.uid();

  RETURN QUERY
  SELECT
    c.id,
    c.name,
    cfp.regime_fiscal,
    pr.full_name,
    COUNT(op.id),
    COUNT(op.id) FILTER (WHERE op.due_date < CURRENT_DATE AND op.status NOT IN ('depose','na')),
    COUNT(op.id) FILTER (WHERE op.status IN ('a_faire','pieces_attendues')),
    MIN(op.due_date) FILTER (WHERE op.status NOT IN ('depose','na')),
    CASE
      WHEN COUNT(op.id) FILTER (WHERE op.due_date < CURRENT_DATE AND op.status NOT IN ('depose','na')) > 0
        THEN 'retard'
      WHEN COUNT(op.id) FILTER (WHERE op.due_date <= CURRENT_DATE + 7 AND op.status NOT IN ('depose','na')) > 0
        THEN 'vigilance'
      ELSE 'ok'
    END
  FROM clients c
  LEFT JOIN client_fiscal_profile cfp ON cfp.client_id = c.id
  LEFT JOIN profiles pr ON pr.id = cfp.collaborateur_id
  LEFT JOIN obligation_periods op ON op.client_id = c.id
  WHERE c.organization_id = _org
  GROUP BY c.id, c.name, cfp.regime_fiscal, pr.full_name
  ORDER BY 6 DESC, c.name;
END;
$function$
;

-- get_client_portal_access(_client_id uuid)
CREATE OR REPLACE FUNCTION public.get_client_portal_access(_client_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _org uuid;
  _grade integer;
  _client_org uuid;
BEGIN
  SELECT p.organization_id, p.grade_level INTO _org, _grade
  FROM profiles p WHERE p.id = auth.uid();

  SELECT c.organization_id INTO _client_org FROM clients c WHERE c.id = _client_id;
  IF _client_org IS DISTINCT FROM _org THEN
    RAISE EXCEPTION 'Accès refusé';
  END IF;

  RETURN jsonb_build_object(
    'accounts', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
        'id', pu.id, 'email', pu.email, 'full_name', pu.full_name,
        'phone', pu.phone, 'is_active', pu.is_active,
        'activated_at', pu.activated_at, 'last_seen_at', pu.last_seen_at,
        'invited_at', pu.invited_at
      ) ORDER BY pu.created_at)
      FROM portal_users pu WHERE pu.client_id = _client_id
    ), '[]'::jsonb),
    'pending_invitations', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
        'id', pi.id, 'email', pi.email, 'full_name', pi.full_name,
        'invited_at', pi.invited_at, 'expires_at', pi.expires_at,
        'is_expired', (pi.expires_at < now())
      ) ORDER BY pi.invited_at DESC)
      FROM portal_invitations pi
      WHERE pi.client_id = _client_id AND pi.status = 'pending'
    ), '[]'::jsonb)
  );
END;
$function$
;

-- get_client_shared_documents(_client_id uuid)
CREATE OR REPLACE FUNCTION public.get_client_shared_documents(_client_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _org uuid;
  _client_org uuid;
BEGIN
  SELECT p.organization_id INTO _org FROM profiles p WHERE p.id = auth.uid();
  SELECT c.organization_id INTO _client_org FROM clients c WHERE c.id = _client_id;

  IF _client_org IS DISTINCT FROM _org THEN
    RAISE EXCEPTION 'Accès refusé';
  END IF;

  RETURN jsonb_build_object(
    'shared', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
        'id', pd.id, 'title', pd.title, 'description', pd.description,
        'category', pd.category, 'file_name', pd.file_name, 'file_path', pd.file_path,
        'file_size', pd.file_size, 'uploaded_at', pd.uploaded_at,
        'uploaded_by', pr.full_name,
        'first_downloaded_at', pd.first_downloaded_at,
        'download_count', pd.download_count,
        'is_available', pd.is_available
      ) ORDER BY pd.uploaded_at DESC)
      FROM portal_documents pd
      LEFT JOIN profiles pr ON pr.id = pd.uploaded_by_staff
      WHERE pd.client_id = _client_id AND pd.direction = 'to_client'
    ), '[]'::jsonb),
    'received', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
        'id', pd.id, 'title', pd.title, 'category', pd.category,
        'file_name', pd.file_name, 'file_path', pd.file_path,
        'file_size', pd.file_size, 'uploaded_at', pd.uploaded_at,
        'uploaded_by', pu.full_name, 'uploaded_by_email', pu.email
      ) ORDER BY pd.uploaded_at DESC)
      FROM portal_documents pd
      LEFT JOIN portal_users pu ON pu.id = pd.uploaded_by_client
      WHERE pd.client_id = _client_id AND pd.direction = 'from_client'
    ), '[]'::jsonb)
  );
END;
$function$
;

-- get_deposits_inbox(_only_mine boolean)
CREATE OR REPLACE FUNCTION public.get_deposits_inbox(_only_mine boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _org uuid;
  _grade integer;
BEGIN
  SELECT p.organization_id, p.grade_level INTO _org, _grade
  FROM profiles p WHERE p.id = auth.uid();

  IF _org IS NULL THEN
    RAISE EXCEPTION 'Accès refusé';
  END IF;

  RETURN jsonb_build_object(
    -- Pièces déposées via une déclaration, en attente de validation
    'pending', COALESCE((
      SELECT jsonb_agg(item ORDER BY (item->>'deposited_at') DESC)
      FROM (
        SELECT jsonb_build_object(
          'document_id', od.id,
          'label', od.label,
          'file_name', od.file_name,
          'file_path', od.file_path,
          'deposited_at', od.deposited_at,
          'deposited_by', od.deposited_by_contact,
          'source', od.source,
          'client_id', op.client_id,
          'client_name', c.name,
          'period_id', op.id,
          'period_label', op.period_label,
          'obligation_code', ot.code,
          'obligation_label', ot.label,
          'due_date', op.due_date,
          'is_late', (op.due_date < CURRENT_DATE),
          'assigned_to', op.assigned_to,
          'assigned_name', pr.full_name
        ) AS item
        FROM obligation_documents od
        JOIN obligation_periods op ON op.id = od.obligation_period_id
        JOIN obligation_types ot ON ot.id = op.obligation_type_id
        JOIN clients c ON c.id = op.client_id
        LEFT JOIN profiles pr ON pr.id = op.assigned_to
        WHERE op.organization_id = _org
          AND od.status = 'deposee'
          AND (NOT _only_mine OR op.assigned_to = auth.uid())
      ) sub
    ), '[]'::jsonb),

    -- Envois libres du client (hors déclaration)
    'free_uploads', COALESCE((
      SELECT jsonb_agg(item ORDER BY (item->>'uploaded_at') DESC)
      FROM (
        SELECT jsonb_build_object(
          'document_id', pd.id,
          'title', pd.title,
          'category', pd.category,
          'file_name', pd.file_name,
          'file_path', pd.file_path,
          'uploaded_at', pd.uploaded_at,
          'client_id', pd.client_id,
          'client_name', c.name,
          'uploaded_by', pu.email
        ) AS item
        FROM portal_documents pd
        JOIN clients c ON c.id = pd.client_id
        LEFT JOIN portal_users pu ON pu.id = pd.uploaded_by_client
        WHERE pd.organization_id = _org
          AND pd.direction = 'from_client'
          AND pd.uploaded_at >= now() - INTERVAL '30 days'
      ) sub
    ), '[]'::jsonb),

    'counts', jsonb_build_object(
      'pending_total', (
        SELECT COUNT(*) FROM obligation_documents od
        JOIN obligation_periods op ON op.id = od.obligation_period_id
        WHERE op.organization_id = _org AND od.status = 'deposee'
      ),
      'pending_mine', (
        SELECT COUNT(*) FROM obligation_documents od
        JOIN obligation_periods op ON op.id = od.obligation_period_id
        WHERE op.organization_id = _org AND od.status = 'deposee'
          AND op.assigned_to = auth.uid()
      )
    )
  );
END;
$function$
;

-- get_dossier_evaluations(_dossier_id uuid)
CREATE OR REPLACE FUNCTION public.get_dossier_evaluations(_dossier_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _org uuid; _grade int; _me uuid := auth.uid(); _f RECORD;
BEGIN
  SELECT p.organization_id, p.grade_level INTO _org, _grade
  FROM profiles p WHERE p.id = _me;

  SELECT * INTO _f FROM client_fiscal_profile
   WHERE id = _dossier_id AND organization_id = _org;
  IF _f IS NULL THEN RETURN '[]'::jsonb; END IF;

  -- Mêmes droits de lecture que l'ouverture de campagne.
  IF NOT (
    _f.collaborateur_id = _me
    OR COALESCE(_grade, 99) <= 2
    OR EXISTS (SELECT 1 FROM client_obligations o
               WHERE o.client_id = _f.client_id AND o.responsible_id = _me
                 AND COALESCE(o.is_active, true))
  ) THEN
    RETURN '[]'::jsonb;
  END IF;

  RETURN COALESCE((
    SELECT jsonb_agg(jsonb_build_object(
      'id', e.id,
      'status', e.status,
      'weighted_score', e.weighted_score,
      'appreciation_label', e.appreciation_label,
      'exercice', e.exercice,
      'periode', public.exercice_label_dossier(e.dossier_id, e.exercice),
      'practice', e.practice,
      'echelon', e.echelon,
      'evaluatee', jsonb_build_object('id', pe.id, 'full_name', pe.full_name,
                                      'grade', pe.grade),
      'evaluator', jsonb_build_object('id', pv.id, 'full_name', pv.full_name,
                                      'grade', pv.grade)
    ) ORDER BY pe.grade_level, pe.full_name)
    FROM evaluations e
    JOIN profiles pe ON pe.id = e.evaluatee_id
    JOIN profiles pv ON pv.id = e.evaluator_id
    WHERE e.dossier_id = _dossier_id
  ), '[]'::jsonb);
END; $function$
;

-- get_evaluation_feedback(_evaluation_id uuid)
CREATE OR REPLACE FUNCTION public.get_evaluation_feedback(_evaluation_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _e RECORD; _grade int; _org uuid;
BEGIN
 SELECT * INTO _e FROM evaluations WHERE id=_evaluation_id;
 IF _e IS NULL THEN RAISE EXCEPTION 'Évaluation introuvable'; END IF;
 SELECT organization_id,grade_level INTO _org,_grade FROM profiles WHERE id=auth.uid();
 IF _org IS NULL OR _e.organization_id<>_org OR _e.evaluatee_id=auth.uid() OR (_e.evaluator_id<>auth.uid() AND COALESCE(_grade,99)>2) THEN RAISE EXCEPTION 'Accès refusé : les avis consultatifs sont destinés à l''évaluateur'; END IF;
 RETURN COALESCE((SELECT jsonb_agg(jsonb_build_object('id',f.id,'contributeur',p.full_name,'grade',p.grade,'mission_code',(SELECT code FROM missions WHERE id=f.mission_id),'statut',f.status,'appreciation',f.overall,'points_forts',f.strengths,'axes_progres',f.improvements,'sollicite_le',f.requested_at,'rendu_le',f.submitted_at) ORDER BY f.requested_at) FROM evaluation_feedback f JOIN profiles p ON p.id=f.contributor_id WHERE f.evaluation_id=_evaluation_id),'[]'::jsonb);
END $function$
;

-- get_evaluation_form(_evaluation_id uuid)
CREATE OR REPLACE FUNCTION public.get_evaluation_form(_evaluation_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _e RECORD; _res jsonb;
BEGIN
  IF NOT public.can_read_evaluation(_evaluation_id) THEN
    RAISE EXCEPTION 'Accès refusé';
  END IF;

  SELECT * INTO _e FROM evaluations WHERE id = _evaluation_id;

  SELECT jsonb_build_object(
    'evaluation', jsonb_build_object(
      'id', _e.id, 'status', _e.status, 'eval_type', _e.eval_type,
      'practice', _e.practice, 'echelon', _e.echelon,
      'mission_id', _e.mission_id, 'mission_code', _e.mission_code, 'objet', CASE WHEN _e.dossier_id IS NOT NULL THEN 'dossier' ELSE 'mission' END,
      'mission_name', COALESCE(public.dossier_label(_e.dossier_id), (SELECT name FROM missions WHERE id = _e.mission_id)),
      'period_start', _e.period_start, 'period_end', _e.period_end,
      'exercice', _e.exercice,
      'weighted_score', _e.weighted_score,
      'appreciation', _e.appreciation, 'appreciation_label', _e.appreciation_label,
      'round_count', _e.round_count,
      'evaluator_comment', _e.evaluator_comment,
      'collaborator_comment', _e.collaborator_comment,
      'has_objection', _e.has_objection,
      'disagreement', _e.disagreement, 'disagreement_reason', _e.disagreement_reason,
      'sent_at', _e.sent_at, 'observed_at', _e.observed_at, 'validated_at', _e.validated_at,
      'is_evaluator', (_e.evaluator_id = auth.uid()),
      'is_evaluatee', (_e.evaluatee_id = auth.uid()),
      'evaluator', (SELECT jsonb_build_object('id', p.id, 'full_name', p.full_name, 'grade', p.grade)
                      FROM profiles p WHERE p.id = _e.evaluator_id),
      'evaluatee', (SELECT jsonb_build_object('id', p.id, 'full_name', p.full_name,
                                              'grade', p.grade, 'echelon', p.grade_echelon)
                      FROM profiles p WHERE p.id = _e.evaluatee_id)
    ),
    'categories', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
        'id', c.id, 'code', c.code, 'label', c.label, 'weight', c.weight,
        'subcriteria', (
          SELECT COALESCE(jsonb_agg(jsonb_build_object(
            'id', s.id, 'label', s.label,
            'score', es.score, 'comment', es.comment
          ) ORDER BY s.sort_order), '[]'::jsonb)
          FROM evaluation_subcriteria s
          LEFT JOIN evaluation_scores es
                 ON es.subcriterion_id = s.id AND es.evaluation_id = _evaluation_id
          WHERE s.category_id = c.id)
      ) ORDER BY c.sort_order, c.code)
      FROM evaluation_categories c WHERE c.template_id = _e.template_id
    ), '[]'::jsonb),
    'scale', COALESCE((
      SELECT jsonb_agg(jsonb_build_object('code', code, 'label', label,
             'min', min_score, 'max', max_score, 'color', color) ORDER BY sort_order)
      FROM evaluation_scale WHERE organization_id = _e.organization_id
    ), '[]'::jsonb),
    'exchanges', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
        'round', x.round, 'action', x.action, 'message', x.message,
        'actor', (SELECT full_name FROM profiles WHERE id = x.actor_id),
        'score_after', x.score_after, 'created_at', x.created_at) ORDER BY x.created_at)
      FROM evaluation_exchanges x WHERE x.evaluation_id = _evaluation_id
    ), '[]'::jsonb)
  ) INTO _res;

  RETURN _res;
END; $function$
;

-- get_evaluation_header(_evaluation_id uuid)
CREATE OR REPLACE FUNCTION public.get_evaluation_header(_evaluation_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _e RECORD; _me RECORD;
BEGIN
  SELECT * INTO _e FROM evaluations WHERE id = _evaluation_id;
  IF _e IS NULL THEN RAISE EXCEPTION 'Évaluation introuvable'; END IF;

  SELECT p.id, p.organization_id, p.grade_level INTO _me
  FROM profiles p WHERE p.id = auth.uid();

  IF NOT (
    _e.evaluator_id = _me.id
    OR (_e.evaluatee_id = _me.id AND _e.status <> 'brouillon')
    OR (_e.organization_id = _me.organization_id
        AND COALESCE(_me.grade_level, 99) <= 2)
  ) THEN
    RAISE EXCEPTION 'Accès refusé à cette évaluation';
  END IF;

  RETURN jsonb_build_object(
    'collaborateur', (SELECT full_name FROM profiles WHERE id = _e.evaluatee_id),
    -- Le grade s'écrit en toutes lettres : c'est l'échelon, pas le sigle.
    'grade',         _e.echelon,
    'code_mission',  _e.mission_code,
    'evaluateur',    (SELECT full_name FROM profiles WHERE id = _e.evaluator_id),
    -- Le département vient du travail évalué, figé à l'ouverture.
    'departement',   COALESCE(_e.departement,
                       public.resolve_evaluation_departement(
                         _e.mission_id, _e.dossier_id, _e.organization_id)),
    'client',        CASE WHEN _e.dossier_id IS NOT NULL
                       THEN public.dossier_label(_e.dossier_id)
                       ELSE (SELECT c.name FROM clients c
                             JOIN missions m ON m.client_id = c.id
                             WHERE m.id = _e.mission_id) END,
    'objet',         CASE WHEN _e.dossier_id IS NOT NULL
                       THEN 'dossier' ELSE 'mission' END,
    'periode',       CASE WHEN _e.dossier_id IS NOT NULL
                       THEN public.exercice_label_dossier(_e.dossier_id, _e.exercice)
                       ELSE public.exercice_label(_e.exercice, _e.organization_id) END,
    'date_evaluation', COALESCE(_e.validated_at, _e.sent_at, _e.created_at),
    -- l'interface sait si le code reste modifiable
    'code_modifiable', _e.status NOT IN ('validee', 'cloturee'),
    -- et si les blocs de suivi doivent figurer au PDF
    'desaccord',     _e.disagreement OR _e.has_objection
  );
END; $function$
;

-- get_evaluation_history(_user_id uuid, _cycles smallint)
CREATE OR REPLACE FUNCTION public.get_evaluation_history(_user_id uuid, _cycles smallint DEFAULT NULL::smallint)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _org uuid; _grade int; _n smallint; _ex smallint;
  _rows jsonb := '[]'::jsonb; _i int; _g jsonb;
  _scores numeric[] := '{}';
BEGIN
  IF auth.uid() IS NULL OR NOT EXISTS (SELECT 1 FROM public.profiles target JOIN public.profiles caller ON caller.organization_id=target.organization_id WHERE target.id=_user_id AND caller.id=auth.uid() AND (target.id=auth.uid() OR COALESCE(caller.grade_level,99)<=2)) THEN RAISE EXCEPTION 'Accès refusé à cette synthèse'; END IF;
  SELECT p.organization_id, p.grade_level INTO _org, _grade
  FROM profiles p WHERE p.id = auth.uid();

  IF _user_id <> auth.uid() AND COALESCE(_grade, 99) > 2 THEN
    RAISE EXCEPTION 'Accès refusé';
  END IF;

  SELECT COALESCE(_cycles, eval_history_cycles) INTO _n
  FROM organizations WHERE id = _org;

  _ex := public.fiscal_exercice(CURRENT_DATE, _org);

  FOR _i IN 0 .. (_n - 1) LOOP
    _g := public.get_global_evaluation(_user_id, (_ex - _i)::smallint);

    -- Un exercice sans aucune évaluation n'entre pas dans la trajectoire
    CONTINUE WHEN (_g->>'score_global') IS NULL;

    _scores := _scores || ((_g->>'score_global')::numeric);
    _rows := _rows || jsonb_build_array(jsonb_build_object(
      'exercice', (_ex - _i),
      'score_global', (_g->>'score_global')::numeric,
      'score_missions', (_g->>'score_missions')::numeric,
      'score_annuelle', (_g->>'score_annuelle')::numeric,
      'nb_missions', (_g->>'nb_missions')::int,
      'nb_evaluateurs', (_g->'agregat_missions'->>'nb_evaluateurs')::int,
      'appreciation', _g->>'appreciation',
      'appreciation_label', _g->>'appreciation_label',
      'provisoire', (_g->>'provisoire')::boolean
    ));
  END LOOP;

  RETURN jsonb_build_object(
    'user_id', _user_id,
    'cycles_demandes', _n,
    'cycles_disponibles', jsonb_array_length(_rows),
    'cycles', _rows,
    'score_moyen', CASE WHEN array_length(_scores, 1) > 0
      THEN ROUND((SELECT AVG(s) FROM unnest(_scores) s), 2) END,
    -- La tendance compare le cycle le plus récent au précédent
    'tendance', CASE
      WHEN array_length(_scores, 1) < 2 THEN NULL
      WHEN _scores[1] - _scores[2] >=  3 THEN 'progression'
      WHEN _scores[1] - _scores[2] <= -3 THEN 'recul'
      ELSE 'stable' END,
    'variation', CASE WHEN array_length(_scores, 1) >= 2
      THEN ROUND(_scores[1] - _scores[2], 2) END,
    'eligible_decision', array_length(_scores, 1) >= 2
  );
END; $function$
;

-- get_evaluation_pdf_data(_evaluation_id uuid)
CREATE OR REPLACE FUNCTION public.get_evaluation_pdf_data(_evaluation_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  RETURN public.get_evaluation_pdf_data_base(_evaluation_id)
      || jsonb_build_object('entete', public.get_evaluation_header(_evaluation_id));
END; $function$
;

-- get_evaluation_pdf_data_base(_evaluation_id uuid)
CREATE OR REPLACE FUNCTION public.get_evaluation_pdf_data_base(_evaluation_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _e RECORD; _me RECORD; _org RECORD;
  _is_evaluator boolean; _is_evaluatee boolean; _is_direction boolean;
BEGIN
  SELECT * INTO _e FROM evaluations WHERE id = _evaluation_id;
  IF _e IS NULL THEN RAISE EXCEPTION 'Évaluation introuvable'; END IF;

  SELECT p.id, p.organization_id, p.grade_level, p.full_name
    INTO _me FROM profiles p WHERE p.id = auth.uid();

  _is_evaluator := _e.evaluator_id = _me.id;
  _is_evaluatee := _e.evaluatee_id = _me.id;
  _is_direction := _e.organization_id = _me.organization_id
                   AND COALESCE(_me.grade_level, 99) <= 2;

  -- Mêmes règles que la policy eval_read : le collaborateur ne
  -- télécharge jamais un brouillon, la direction n'accède qu'aux
  -- évaluations validées.
  IF NOT (
    _is_evaluator
    OR (_is_evaluatee AND _e.status <> 'brouillon')
    OR (_is_direction AND _e.status IN ('validee','arbitrage','cloturee'))
  ) THEN
    RAISE EXCEPTION 'Accès refusé à cette évaluation';
  END IF;

  SELECT o.name, o.logo_url INTO _org
  FROM organizations o WHERE o.id = _e.organization_id;

  RETURN jsonb_build_object(
    'organization_id', _e.organization_id,
    'organisation', jsonb_build_object('nom', _org.name, 'logo', _org.logo_url),
    'evaluation', jsonb_build_object(
      'id', _e.id,
      'type', _e.eval_type,
      'statut', _e.status,
      'exercice', _e.exercice,
      'practice', _e.practice,
      'echelon', _e.echelon,
      'code_mission', _e.mission_code,
      'objet', CASE WHEN _e.dossier_id IS NOT NULL THEN 'dossier' ELSE 'mission' END, 'mission', COALESCE(public.dossier_label(_e.dossier_id), (SELECT name FROM missions WHERE id = _e.mission_id)),
      'client', COALESCE(public.dossier_label(_e.dossier_id), (SELECT c.name FROM clients c JOIN missions m ON m.client_id = c.id WHERE m.id = _e.mission_id)),
      'periode_debut', _e.period_start,
      'periode_fin', _e.period_end,
      'score', _e.weighted_score,
      'appreciation', _e.appreciation_label,
      'commentaire_evaluateur', _e.evaluator_comment,
      'observations_collaborateur', _e.collaborator_comment,
      'nb_echanges', _e.round_count,
      'objection', COALESCE(_e.has_objection, false),
      'desaccord', COALESCE(_e.disagreement, false),
      'motif_desaccord', _e.disagreement_reason,
      'envoyee_le', _e.sent_at,
      'observee_le', _e.observed_at,
      'validee_le', _e.validated_at,
      'validee_par', (SELECT full_name FROM profiles WHERE id = _e.validated_by),
      'accuse_lecture_le', _e.acknowledged_at
    ),
    'collaborateur', (
      SELECT jsonb_build_object('nom', full_name, 'grade', grade,
        'echelon', grade_echelon, 'practice', practice, 'email', email)
      FROM profiles WHERE id = _e.evaluatee_id),
    'evaluateur', (
      SELECT jsonb_build_object('nom', full_name, 'grade', grade,
        'echelon', grade_echelon, 'email', email)
      FROM profiles WHERE id = _e.evaluator_id),
    'categories', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
        'code', c.code, 'libelle', c.label, 'ponderation', c.weight,
        'note', (SELECT ROUND(AVG(s.score)::numeric, 2) FROM evaluation_scores s
                 JOIN evaluation_subcriteria sc2 ON sc2.id = s.subcriterion_id
                 WHERE s.evaluation_id = _e.id AND sc2.category_id = c.id),
        'sous_criteres', COALESCE((
          SELECT jsonb_agg(jsonb_build_object(
            'libelle', sc.label,
            'note', (SELECT s.score FROM evaluation_scores s
                     WHERE s.evaluation_id = _e.id AND s.subcriterion_id = sc.id),
            'commentaire', (SELECT s.comment FROM evaluation_scores s
                     WHERE s.evaluation_id = _e.id AND s.subcriterion_id = sc.id)
          ) ORDER BY sc.sort_order)
          FROM evaluation_subcriteria sc WHERE sc.category_id = c.id
        ), '[]'::jsonb)
      ) ORDER BY c.sort_order)
      FROM evaluation_categories c WHERE c.template_id = _e.template_id
    ), '[]'::jsonb),
    'echelle', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
        'libelle', label, 'min', min_score, 'max', max_score) ORDER BY sort_order)
      FROM evaluation_scale WHERE organization_id = _e.organization_id
    ), '[]'::jsonb),
    'echanges', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
        'date', x.created_at, 'action', x.action, 'round', x.round,
        'auteur', (SELECT full_name FROM profiles WHERE id = x.actor_id),
        'commentaire', x.message,
        'score_avant', x.score_before, 'score_apres', x.score_after) ORDER BY x.created_at)
      FROM evaluation_exchanges x WHERE x.evaluation_id = _e.id
    ), '[]'::jsonb),
    -- §5.5 : les avis consultatifs ne sont jamais communiqués à l'évalué
    'avis_consultatifs', CASE WHEN _is_evaluator OR _is_direction THEN COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
        'contributeur', p.full_name, 'grade', p.grade,
        'appreciation', f.overall, 'points_forts', f.strengths,
        'axes_progres', f.improvements) ORDER BY f.submitted_at)
      FROM evaluation_feedback f JOIN profiles p ON p.id = f.contributor_id
      WHERE f.evaluation_id = _e.id AND f.status = 'rendu'
    ), '[]'::jsonb) ELSE '[]'::jsonb END,
    'lecteur', jsonb_build_object(
      'nom', _me.full_name,
      'role', CASE WHEN _is_evaluator THEN 'evaluateur'
                   WHEN _is_evaluatee THEN 'collaborateur'
                   ELSE 'direction' END)
  );
END; $function$
;

-- get_evaluation_registre(_exercice smallint, _practice eval_practice, _user_id uuid)
CREATE OR REPLACE FUNCTION public.get_evaluation_registre(_exercice smallint DEFAULT NULL::smallint, _practice eval_practice DEFAULT NULL::eval_practice, _user_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _org uuid; _grade int; _ex smallint;
BEGIN
  SELECT p.organization_id, p.grade_level INTO _org, _grade
  FROM profiles p WHERE p.id = auth.uid();

  IF COALESCE(_grade, 99) > 2 THEN
    RAISE EXCEPTION 'Accès refusé : le registre d''évaluation globale est réservé à la direction et à la DRH';
  END IF;

  _ex := COALESCE(_exercice, public.fiscal_exercice(CURRENT_DATE, _org));

  RETURN jsonb_build_object(
    'exercice', _ex,
    'lignes', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
        'evaluation_id', e.id,
        'exercice', e.exercice,
        'type', e.eval_type,
        'code_mission', COALESCE(e.mission_code, '—'),
        'objet', CASE WHEN e.dossier_id IS NOT NULL THEN 'dossier' ELSE 'mission' END, 'mission', COALESCE(public.dossier_label(e.dossier_id), (SELECT name FROM missions WHERE id = e.mission_id)),
        'client', COALESCE(public.dossier_label(e.dossier_id), (SELECT c.name FROM clients c JOIN missions m ON m.client_id = c.id WHERE m.id = e.mission_id)),
        'collaborateur_id', e.evaluatee_id,
        'collaborateur', pe.full_name,
        'grade', pe.grade,
        'echelon', e.echelon,
        'code_practice', e.practice,
        'evaluateur_id', e.evaluator_id,
        'evaluateur', pr.full_name,
        'evaluateur_grade', pr.grade,
        'periode_debut', e.period_start,
        'periode_fin', e.period_end,
        'charge', e.weight_basis,
        'significative', e.is_significant,
        'score', e.weighted_score,
        'appreciation', e.appreciation_label,
        'nb_echanges', e.round_count,
        'objection', COALESCE(e.has_objection, false),
        'desaccord', COALESCE(e.disagreement, false),
        'statut', e.status,
        'validee_le', e.validated_at
      ) ORDER BY pe.grade_level, pe.full_name, e.eval_type DESC, e.period_end)
      FROM evaluations e
      JOIN profiles pe ON pe.id = e.evaluatee_id
      LEFT JOIN profiles pr ON pr.id = e.evaluator_id
      WHERE e.organization_id = _org
        AND e.exercice = _ex
        AND e.status IN ('validee', 'arbitrage', 'cloturee')
        AND (_practice IS NULL OR e.practice = _practice)
        AND (_user_id IS NULL OR e.evaluatee_id = _user_id)
    ), '[]'::jsonb),
    'totaux', (
      SELECT jsonb_build_object(
        'nb_evaluations', COUNT(*),
        'nb_collaborateurs', COUNT(DISTINCT e.evaluatee_id),
        'nb_evaluateurs', COUNT(DISTINCT e.evaluator_id),
        'nb_missions', COUNT(DISTINCT COALESCE(e.mission_id, e.dossier_id)),
        'nb_objections', COUNT(*) FILTER (WHERE e.has_objection),
        'nb_desaccords', COUNT(*) FILTER (WHERE e.disagreement),
        'nb_annuelles', COUNT(*) FILTER (WHERE e.eval_type = 'annuelle'),
        'score_moyen', ROUND(AVG(e.weighted_score), 2))
      FROM evaluations e
      WHERE e.organization_id = _org AND e.exercice = _ex
        AND e.status IN ('validee','arbitrage','cloturee')
        AND (_practice IS NULL OR e.practice = _practice)
        AND (_user_id IS NULL OR e.evaluatee_id = _user_id)
    )
  );
END; $function$
;

-- get_global_evaluation(_user_id uuid, _exercice smallint)
CREATE OR REPLACE FUNCTION public.get_global_evaluation(_user_id uuid, _exercice smallint)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _org uuid; _grade int;
  _nom text; _gr text; _ech text; _prac public.eval_practice;
  _agg jsonb; _missions numeric; _nb_missions int; _annuelle numeric; _ann_id uuid;
  _global numeric; _provisoire boolean;
  -- Scalaires et non un RECORD : un exercice sans aucune évaluation
  -- laisserait un RECORD non assigné, et la trajectoire sur plusieurs
  -- cycles plante en le lisant.
  _appr_code text; _appr_label text; _appr_rh text;
  _obj_moy numeric; _nb_obj int; _nb_obj_notes int;
  _wm numeric; _wa numeric;
BEGIN
  IF auth.uid() IS NULL OR NOT EXISTS (SELECT 1 FROM public.profiles target JOIN public.profiles caller ON caller.organization_id=target.organization_id WHERE target.id=_user_id AND caller.id=auth.uid() AND (target.id=auth.uid() OR COALESCE(caller.grade_level,99)<=2)) THEN RAISE EXCEPTION 'Accès refusé à cette synthèse'; END IF;
  SELECT p.organization_id, p.grade_level INTO _org, _grade
  FROM profiles p WHERE p.id = auth.uid();

  IF _user_id <> auth.uid() AND COALESCE(_grade, 99) > 2 THEN
    RAISE EXCEPTION 'Accès refusé';
  END IF;

  SELECT eval_weight_missions, eval_weight_annuelle INTO _wm, _wa
  FROM organizations WHERE id = _org;

  _agg := public.get_mission_aggregate(_user_id, _exercice);
  _missions   := (_agg->>'score')::numeric;
  _nb_missions := COALESCE((_agg->>'nb_missions')::int, 0);

  SELECT weighted_score, id INTO _annuelle, _ann_id FROM evaluations
  WHERE evaluatee_id = _user_id AND eval_type = 'annuelle'
    AND status IN ('validee','cloturee') AND exercice = _exercice
  ORDER BY validated_at DESC LIMIT 1;

  -- Les deux volets présents : pondération du cabinet, renormalisée
  -- si les poids ne totalisent pas 1. Un seul volet : il porte seul
  -- le score, et la synthèse est signalée provisoire. Une évaluation
  -- qui n'a pas eu lieu n'est pas une note de zéro.
  IF _annuelle IS NOT NULL AND _nb_missions > 0 THEN
    _global := ROUND((_missions * _wm + _annuelle * _wa) / NULLIF(_wm + _wa, 0), 2);
    _provisoire := false;
  ELSIF _annuelle IS NOT NULL THEN
    _global := ROUND(_annuelle, 2); _provisoire := true;
  ELSIF _nb_missions > 0 THEN
    _global := ROUND(_missions, 2); _provisoire := true;
  ELSE
    _global := NULL; _provisoire := true;
  END IF;

  SELECT AVG(achievement_rate), COUNT(*), COUNT(achievement_rate)
    INTO _obj_moy, _nb_obj, _nb_obj_notes
  FROM evaluation_objectives
  WHERE user_id = _user_id AND exercice = _exercice;

  IF _global IS NOT NULL THEN
    SELECT code, label, hr_consequence
      INTO _appr_code, _appr_label, _appr_rh
    FROM evaluation_scale
    WHERE organization_id = _org AND _global >= min_score AND _global <= max_score
    ORDER BY sort_order LIMIT 1;
  END IF;

  SELECT full_name, grade, grade_echelon, practice
    INTO _nom, _gr, _ech, _prac
  FROM profiles WHERE id = _user_id;

  RETURN jsonb_build_object(
    'exercice', _exercice,
    'collaborateur', _nom, 'grade', _gr,
    'echelon', _ech, 'practice', _prac,
    'ponderation', jsonb_build_object('missions', _wm, 'annuelle', _wa),
    'score_missions', _missions,
    'nb_missions', _nb_missions,
    'agregat_missions', _agg,
    'score_annuelle', CASE WHEN _annuelle IS NOT NULL THEN ROUND(_annuelle, 2) END,
    'annuelle_disponible', _annuelle IS NOT NULL,
    'score_global', _global,
    'provisoire', _provisoire,
    'appreciation', _appr_code, 'appreciation_label', _appr_label,
    -- Une conséquence RH ne se lit pas sur une synthèse incomplète :
    -- elle n'est pas renvoyée tant qu'il manque un des deux volets.
    'consequence_rh', CASE WHEN NOT _provisoire THEN _appr_rh END,
    'objectifs_taux_moyen', CASE WHEN _nb_obj_notes > 0 THEN ROUND(_obj_moy, 1) END,
    'objectifs_notes', _nb_obj_notes, 'objectifs_total', _nb_obj,
    'missions', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
        'evaluation_id', e.id,
        'mission_code', e.mission_code,
        'objet', CASE WHEN e.dossier_id IS NOT NULL THEN 'dossier' ELSE 'mission' END, 'mission_name', COALESCE(public.dossier_label(e.dossier_id), (SELECT name FROM missions WHERE id = e.mission_id)),
        'practice', e.practice, 'echelon', e.echelon,
        'score', e.weighted_score, 'appreciation', e.appreciation_label,
        'evaluateur', (SELECT full_name FROM profiles WHERE id = e.evaluator_id),
        'evaluateur_grade', (SELECT grade FROM profiles WHERE id = e.evaluator_id),
        'periode_debut', e.period_start, 'periode_fin', e.period_end,
        'charge', e.weight_basis,
        'significative', e.is_significant,
        'desaccord', COALESCE(e.disagreement, false),
        'validated_at', e.validated_at) ORDER BY e.period_end, e.validated_at)
      FROM evaluations e
      WHERE e.evaluatee_id = _user_id AND e.eval_type = 'mission'
        AND e.status IN ('validee','cloturee') AND e.exercice = _exercice
    ), '[]'::jsonb),
    'annuelle', (
      SELECT jsonb_build_object(
        'evaluation_id', e.id, 'score', e.weighted_score,
        'appreciation', e.appreciation_label,
        'evaluateur', (SELECT full_name FROM profiles WHERE id = e.evaluator_id),
        'validated_at', e.validated_at)
      FROM evaluations e WHERE e.id = _ann_id),
    'objectifs', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
        'id', id, 'title', title, 'specific', specific, 'measurable', measurable,
        'achievable', achievable, 'realistic', realistic, 'deadline', deadline,
        'status', status, 'achievement_rate', achievement_rate,
        'achievement_comment', achievement_comment,
        'evaluated_at', evaluated_at) ORDER BY sort_order)
      FROM evaluation_objectives WHERE user_id = _user_id AND exercice = _exercice
    ), '[]'::jsonb)
  );
END; $function$
;

-- get_invitation_by_token(_token text)
CREATE OR REPLACE FUNCTION public.get_invitation_by_token(_token text)
 RETURNS TABLE(email text, grade text, organization_name text, organization_id uuid, status text)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT 
    i.email,
    i.grade,
    o.name AS organization_name,
    i.organization_id,
    i.status
  FROM public.invitations i
  LEFT JOIN public.organizations o ON o.id = i.organization_id
  WHERE i.token = _token
    AND i.status = 'pending'
    AND (i.expires_at IS NULL OR i.expires_at > now())
  LIMIT 1;
$function$
;

-- get_member_removal_impact(_mission_id uuid, _user_id uuid)
CREATE OR REPLACE FUNCTION public.get_member_removal_impact(_mission_id uuid, _user_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _res jsonb;
BEGIN
  IF NOT public.can_access_mission(_mission_id) THEN
    RAISE EXCEPTION 'Accès refusé à cette mission';
  END IF;

  SELECT jsonb_build_object(
    'is_member', EXISTS (SELECT 1 FROM mission_members mm WHERE mm.mission_id = _mission_id AND mm.user_id = _user_id),
    'is_director', EXISTS (SELECT 1 FROM missions m WHERE m.id = _mission_id AND m.director_id = _user_id),
    'is_chief', EXISTS (SELECT 1 FROM missions m WHERE m.id = _mission_id AND m.chief_id = _user_id),
    'projects', (SELECT count(*) FROM project_members pm JOIN projects p ON p.id = pm.project_id
                 WHERE p.mission_id = _mission_id AND pm.user_id = _user_id),
    'tasks', (SELECT count(*) FROM task_assignments ta JOIN tasks t ON t.id = ta.task_id
              JOIN projects p ON p.id = t.project_id
              WHERE p.mission_id = _mission_id AND ta.user_id = _user_id),
    'staffing', (SELECT count(*) FROM staffing_assignments sa
                 WHERE sa.mission_id = _mission_id AND sa.user_id = _user_id AND sa.status <> 'cancelled'),
    'documents', (SELECT count(*) FROM documents d WHERE d.mission_id = _mission_id AND d.uploaded_by = _user_id),
    'hours', (SELECT COALESCE(sum(te.hours), 0) FROM time_entries te
              WHERE te.mission_id = _mission_id AND te.user_id = _user_id)
  ) INTO _res;

  RETURN _res;
END;
$function$
;

-- get_mission_aggregate(_user_id uuid, _exercice smallint)
CREATE OR REPLACE FUNCTION public.get_mission_aggregate(_user_id uuid, _exercice smallint)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _org uuid; _mode text;
  _sum_w numeric := 0; _sum_ws numeric := 0; _n int := 0; _w numeric;
  _min numeric; _max numeric; _sd numeric; _nb_eval int;
  _e RECORD;
BEGIN
  IF auth.uid() IS NULL OR NOT EXISTS (SELECT 1 FROM public.profiles target JOIN public.profiles caller ON caller.organization_id=target.organization_id WHERE target.id=_user_id AND caller.id=auth.uid() AND (target.id=auth.uid() OR COALESCE(caller.grade_level,99)<=2)) THEN RAISE EXCEPTION 'Accès refusé à cette synthèse'; END IF;
  SELECT p.organization_id INTO _org FROM profiles p WHERE p.id = _user_id;
  SELECT eval_mission_aggregation INTO _mode FROM organizations WHERE id = _org;

  FOR _e IN
    SELECT * FROM evaluations
    WHERE evaluatee_id = _user_id AND eval_type = 'mission'
      AND status IN ('validee','cloturee')
      AND exercice = _exercice AND is_significant
  LOOP
    _w := public.evaluation_weight(_mode, _e.weight_basis, _e.period_start, _e.period_end);
    _sum_w  := _sum_w  + _w;
    _sum_ws := _sum_ws + _w * COALESCE(_e.weighted_score, 0);
    _n := _n + 1;
  END LOOP;

  SELECT MIN(weighted_score), MAX(weighted_score),
         STDDEV_SAMP(weighted_score), COUNT(DISTINCT evaluator_id)
    INTO _min, _max, _sd, _nb_eval
  FROM evaluations
  WHERE evaluatee_id = _user_id AND eval_type = 'mission'
    AND status IN ('validee','cloturee')
    AND exercice = _exercice AND is_significant;

  RETURN jsonb_build_object(
    'mode', _mode,
    'nb_missions', _n,
    'score', CASE WHEN _sum_w > 0 THEN ROUND(_sum_ws / _sum_w, 2) END,
    'score_simple', (
      SELECT ROUND(AVG(weighted_score), 2) FROM evaluations
      WHERE evaluatee_id = _user_id AND eval_type = 'mission'
        AND status IN ('validee','cloturee')
        AND exercice = _exercice AND is_significant),
    'nb_evaluateurs', COALESCE(_nb_eval, 0),
    'score_min', ROUND(_min, 2),
    'score_max', ROUND(_max, 2),
    'etendue', CASE WHEN _min IS NOT NULL THEN ROUND(_max - _min, 2) END,
    'ecart_type', ROUND(_sd, 2),
    'dispersion_forte', COALESCE(_max - _min, 0) >= 20,
    'par_evaluateur', COALESCE((
      SELECT jsonb_agg(x ORDER BY (x->>'nb_missions')::int DESC)
      FROM (
        SELECT jsonb_build_object(
          'evaluateur_id', e.evaluator_id,
          'evaluateur', (SELECT full_name FROM profiles WHERE id = e.evaluator_id),
          'grade', (SELECT grade FROM profiles WHERE id = e.evaluator_id),
          'nb_missions', COUNT(*),
          'score_moyen', ROUND(AVG(e.weighted_score), 2)
        ) AS x
        FROM evaluations e
        WHERE e.evaluatee_id = _user_id AND e.eval_type = 'mission'
          AND e.status IN ('validee','cloturee')
          AND e.exercice = _exercice AND e.is_significant
        GROUP BY e.evaluator_id
      ) s
    ), '[]'::jsonb),
    'missions_ecartees', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
        'evaluation_id', id, 'mission_code', mission_code,
        'score', weighted_score) ORDER BY period_end)
      FROM evaluations
      WHERE evaluatee_id = _user_id AND eval_type = 'mission'
        AND status IN ('validee','cloturee')
        AND exercice = _exercice AND NOT is_significant
    ), '[]'::jsonb)
  );
END; $function$
;

-- get_mission_evaluations(_mission_id uuid)
CREATE OR REPLACE FUNCTION public.get_mission_evaluations(_mission_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _org uuid;
BEGIN
 _org:=public.get_user_organization_id(auth.uid());
 IF _org IS NULL OR NOT EXISTS(SELECT 1 FROM missions WHERE id=_mission_id AND organization_id=_org) OR NOT public.can_access_mission(auth.uid(),_mission_id) THEN RAISE EXCEPTION 'Accès refusé à cette mission'; END IF;
 RETURN COALESCE((SELECT jsonb_agg(jsonb_build_object('id',e.id,'status',e.status,'weighted_score',e.weighted_score,'evaluatee',jsonb_build_object('full_name',pe.full_name),'evaluator',jsonb_build_object('full_name',pr.full_name))) FROM evaluations e JOIN profiles pe ON pe.id=e.evaluatee_id JOIN profiles pr ON pr.id=e.evaluator_id WHERE e.mission_id=_mission_id AND e.organization_id=_org AND public.can_read_evaluation(e.id)),'[]'::jsonb);
END $function$
;

-- get_my_evaluations()
CREATE OR REPLACE FUNCTION public.get_my_evaluations()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _me uuid := auth.uid(); _org uuid; _grade int;
BEGIN
  SELECT p.organization_id, p.grade_level INTO _org, _grade
  FROM profiles p WHERE p.id = _me;

  RETURN jsonb_build_object(
    -- Affectations non encore ouvertes
    'a_ouvrir', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
        'assignment_id', a.id, 'mission_id', a.mission_id, 'objet', CASE WHEN a.dossier_id IS NOT NULL THEN 'dossier' ELSE 'mission' END,
        'mission_name', COALESCE(m.name, public.dossier_label(a.dossier_id)), 'mission_code', m.code,
        'eval_type', a.eval_type, 'due_date', a.due_date,
        'evaluatee', jsonb_build_object('id', p.id, 'full_name', p.full_name,
                                        'grade', p.grade, 'echelon', p.grade_echelon,
                                        'practice', p.practice,
                                        'profil_complet', (p.practice IS NOT NULL AND p.grade_echelon IS NOT NULL))
      ) ORDER BY a.due_date NULLS LAST)
      FROM evaluation_assignments a
      JOIN profiles p ON p.id = a.evaluatee_id
      LEFT JOIN missions m ON m.id = a.mission_id
      WHERE a.evaluator_id = _me AND a.status = 'a_faire'
    ), '[]'::jsonb),

    -- Évaluations que je conduis
    'a_conduire', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
        'id', e.id, 'status', e.status, 'objet', CASE WHEN e.dossier_id IS NOT NULL THEN 'dossier' ELSE 'mission' END, 'eval_type', e.eval_type, 'mission_code', e.mission_code,
        'mission_name', COALESCE(m.name, public.dossier_label(e.dossier_id)), 'weighted_score', e.weighted_score,
        'appreciation_label', e.appreciation_label, 'round_count', e.round_count,
        'has_objection', e.has_objection, 'disagreement', e.disagreement,
        'evaluatee', jsonb_build_object('full_name', p.full_name, 'grade', p.grade),
        'updated_at', e.updated_at) ORDER BY e.updated_at DESC)
      FROM evaluations e
      JOIN profiles p ON p.id = e.evaluatee_id
      LEFT JOIN missions m ON m.id = e.mission_id
      WHERE e.evaluator_id = _me AND e.status NOT IN ('cloturee')
    ), '[]'::jsonb),

    -- Mes propres évaluations (jamais les brouillons)
    'mes_evaluations', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
        'id', e.id, 'status', e.status, 'objet', CASE WHEN e.dossier_id IS NOT NULL THEN 'dossier' ELSE 'mission' END, 'eval_type', e.eval_type,
        'mission_code', e.mission_code, 'mission_name', COALESCE(m.name, public.dossier_label(e.dossier_id)),
        'weighted_score', e.weighted_score, 'appreciation_label', e.appreciation_label,
        'round_count', e.round_count, 'disagreement', e.disagreement,
        'evaluator', jsonb_build_object('full_name', p.full_name, 'grade', p.grade),
        'sent_at', e.sent_at, 'validated_at', e.validated_at,
        'action_requise', (e.status = 'envoyee')) ORDER BY e.sent_at DESC NULLS LAST)
      FROM evaluations e
      JOIN profiles p ON p.id = e.evaluator_id
      LEFT JOIN missions m ON m.id = e.mission_id
      WHERE e.evaluatee_id = _me AND e.status <> 'brouillon'
    ), '[]'::jsonb),

    -- Vue direction : évaluations validées de l'organisation
    'direction', CASE WHEN COALESCE(_grade, 99) <= 2 THEN COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
        'id', e.id, 'status', e.status, 'objet', CASE WHEN e.dossier_id IS NOT NULL THEN 'dossier' ELSE 'mission' END, 'eval_type', e.eval_type, 'mission_code', e.mission_code,
        'weighted_score', e.weighted_score, 'appreciation_label', e.appreciation_label,
        'disagreement', e.disagreement, 'validated_at', e.validated_at, 'mission_name', COALESCE(public.dossier_label(e.dossier_id), (SELECT m.name FROM public.missions m WHERE m.id=e.mission_id)),
        'evaluatee', jsonb_build_object('full_name', pe.full_name, 'grade', pe.grade),
        'evaluator', jsonb_build_object('full_name', pr.full_name)) ORDER BY e.validated_at DESC)
      FROM evaluations e
      JOIN profiles pe ON pe.id = e.evaluatee_id
      JOIN profiles pr ON pr.id = e.evaluator_id
      WHERE e.organization_id = _org AND e.status IN ('validee','arbitrage','cloturee')
    ), '[]'::jsonb) ELSE '[]'::jsonb END
  );
END; $function$
;

-- get_obligations_echeancier(_from date, _to date, _status text, _client_id uuid)
CREATE OR REPLACE FUNCTION public.get_obligations_echeancier(_from date DEFAULT CURRENT_DATE, _to date DEFAULT ((CURRENT_DATE + '60 days'::interval))::date, _status text DEFAULT NULL::text, _client_id uuid DEFAULT NULL::uuid)
 RETURNS TABLE(id uuid, client_id uuid, client_name text, obligation_code text, obligation_label text, category text, period_label text, due_date date, days_left integer, is_late boolean, status text, assigned_to uuid, assigned_name text, last_reminder_at timestamp with time zone)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
#variable_conflict use_column
DECLARE
  _org uuid;
  _grade integer;
BEGIN
  SELECT p.organization_id, p.grade_level INTO _org, _grade
  FROM profiles p WHERE p.id = auth.uid();

  RETURN QUERY
  SELECT
    op.id,
    op.client_id,
    c.name,
    ot.code,
    ot.label,
    ot.category,
    op.period_label,
    op.due_date,
    (op.due_date - CURRENT_DATE)::integer,
    (op.due_date < CURRENT_DATE AND op.status NOT IN ('depose', 'na')),
    op.status,
    op.assigned_to,
    pr.full_name,
    (SELECT MAX(ci.interaction_date) FROM client_interactions ci
      WHERE ci.obligation_period_id = op.id AND ci.type = 'relance')
  FROM obligation_periods op
  JOIN clients c ON c.id = op.client_id
  JOIN obligation_types ot ON ot.id = op.obligation_type_id
  LEFT JOIN profiles pr ON pr.id = op.assigned_to
  WHERE op.organization_id = _org
    AND op.due_date BETWEEN _from AND _to
    AND (_status IS NULL OR op.status = _status)
    AND (_client_id IS NULL OR op.client_id = _client_id)
    -- Un collaborateur ne voit que ses dossiers
    AND (_grade <= 3 OR op.assigned_to = auth.uid())
  ORDER BY op.due_date ASC, c.name;
END;
$function$
;

-- get_obligations_kpis()
CREATE OR REPLACE FUNCTION public.get_obligations_kpis()
 RETURNS TABLE(total_en_cours bigint, en_retard bigint, echeance_7j bigint, pieces_attendues bigint, deposees_ce_mois bigint)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
#variable_conflict use_column
DECLARE
  _org uuid;
  _grade integer;
BEGIN
  SELECT p.organization_id, p.grade_level INTO _org, _grade
  FROM profiles p WHERE p.id = auth.uid();

  RETURN QUERY
  SELECT
    COUNT(*) FILTER (WHERE op.status NOT IN ('depose', 'na')),
    COUNT(*) FILTER (WHERE op.due_date < CURRENT_DATE AND op.status NOT IN ('depose', 'na')),
    COUNT(*) FILTER (WHERE op.due_date BETWEEN CURRENT_DATE AND (CURRENT_DATE + 7)
                       AND op.status NOT IN ('depose', 'na')),
    COUNT(*) FILTER (WHERE op.status = 'pieces_attendues'),
    COUNT(*) FILTER (WHERE op.status = 'depose'
                       AND op.deposed_at >= date_trunc('month', CURRENT_DATE))
  FROM obligation_periods op
  WHERE op.organization_id = _org
    AND (_grade <= 3 OR op.assigned_to = auth.uid());
END;
$function$
;

-- get_pending_adjustments()
CREATE OR REPLACE FUNCTION public.get_pending_adjustments()
 RETURNS TABLE(id uuid, user_id uuid, collaborator_name text, collaborator_grade text, mission_id uuid, mission_name text, project_name text, role text, start_date date, end_date date, weekly_hours numeric, collaborator_note text, adjustment_requested_at timestamp with time zone, revision_count smallint, current_total_hours numeric)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
#variable_conflict use_column
DECLARE
  _org uuid;
  _grade integer;
BEGIN
  SELECT p.organization_id, p.grade_level INTO _org, _grade
  FROM profiles p WHERE p.id = auth.uid();

  IF _grade IS NULL OR _grade > 3 THEN
    RAISE EXCEPTION 'Accès refusé : arbitrage réservé aux responsables';
  END IF;

  RETURN QUERY
  SELECT
    sa.id,
    sa.user_id,
    pr.full_name,
    pr.grade,
    sa.mission_id,
    m.name,
    pj.name,
    sa.role,
    sa.start_date,
    sa.end_date,
    sa.weekly_hours,
    sa.collaborator_note,
    sa.adjustment_requested_at,
    sa.revision_count,
    -- Charge totale actuelle du collaborateur (toutes missions actives)
    (SELECT COALESCE(SUM(s2.weekly_hours), 0)
       FROM staffing_assignments s2
      WHERE s2.user_id = sa.user_id
        AND s2.status IN ('proposed', 'accepted')
        AND (s2.end_date IS NULL OR s2.end_date >= CURRENT_DATE))
  FROM staffing_assignments sa
  JOIN profiles pr ON pr.id = sa.user_id
  JOIN missions m ON m.id = sa.mission_id
  LEFT JOIN projects pj ON pj.id = sa.project_id
  WHERE sa.organization_id = _org
    AND sa.status = 'adjustment_requested'
    AND (sa.assigned_by = auth.uid() OR _grade <= 2)  -- le DA voit tout
  ORDER BY sa.adjustment_requested_at ASC;
END;
$function$
;

-- get_pending_evaluation_feedback()
CREATE OR REPLACE FUNCTION public.get_pending_evaluation_feedback()
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
 SELECT COALESCE(jsonb_agg(jsonb_build_object('id',f.id,'requested_at',f.requested_at,'evaluation',jsonb_build_object('evaluatee',jsonb_build_object('full_name',pe.full_name),'mission_name',jsonb_build_object('name',m.name)),'requester',jsonb_build_object('full_name',pr.full_name)) ORDER BY f.requested_at),'[]'::jsonb)
 FROM evaluation_feedback f JOIN evaluations e ON e.id=f.evaluation_id JOIN profiles pe ON pe.id=e.evaluatee_id JOIN profiles pr ON pr.id=f.requested_by JOIN profiles caller ON caller.id=auth.uid() AND caller.organization_id=f.organization_id LEFT JOIN missions m ON m.id=f.mission_id
 WHERE f.contributor_id=auth.uid() AND f.status='sollicite' AND e.evaluatee_id<>auth.uid();
$function$
;

-- get_period_documents(_period_id uuid)
CREATE OR REPLACE FUNCTION public.get_period_documents(_period_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _org uuid;
  _result jsonb;
BEGIN
  SELECT organization_id INTO _org FROM obligation_periods WHERE id = _period_id;
  IF _org <> (SELECT p.organization_id FROM profiles p WHERE p.id = auth.uid()) THEN
    RAISE EXCEPTION 'Accès refusé';
  END IF;

  SELECT jsonb_build_object(
    'documents', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
        'id', od.id, 'label', od.label, 'is_required', od.is_required,
        'status', od.status, 'source', od.source,
        'file_name', od.file_name, 'document_id', od.document_id,
        'deposited_at', od.deposited_at, 'deposited_by_contact', od.deposited_by_contact,
        'validated_at', od.validated_at, 'reject_reason', od.reject_reason
      ) ORDER BY od.is_required DESC, od.label)
      FROM obligation_documents od WHERE od.obligation_period_id = _period_id
    ), '[]'::jsonb),
    'progress', (
      SELECT jsonb_build_object(
        'total_required',    COUNT(*) FILTER (WHERE is_required),
        'received_required', COUNT(*) FILTER (WHERE is_required AND status = 'recue'),
        'pending_validation',COUNT(*) FILTER (WHERE status = 'deposee')
      )
      FROM obligation_documents WHERE obligation_period_id = _period_id
    )
  ) INTO _result;

  RETURN _result;
END;
$function$
;

-- get_plan_execution(_start_date date, _end_date date, _user_id uuid)
CREATE OR REPLACE FUNCTION public.get_plan_execution(_start_date date DEFAULT (date_trunc('week'::text, (CURRENT_DATE)::timestamp with time zone))::date, _end_date date DEFAULT ((date_trunc('week'::text, (CURRENT_DATE)::timestamp with time zone) + '6 days'::interval))::date, _user_id uuid DEFAULT NULL::uuid)
 RETURNS TABLE(user_id uuid, full_name text, mission_id uuid, mission_name text, planned_hours numeric, actual_hours numeric, execution_rate numeric, gap_hours numeric)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
#variable_conflict use_column
DECLARE
  _viewer_org uuid;
  _viewer_grade integer;
BEGIN
  SELECT vp.organization_id, vp.grade_level
    INTO _viewer_org, _viewer_grade
  FROM public.profiles vp WHERE vp.id = auth.uid();

  -- Un collaborateur ne voit que ses propres chiffres
  IF _viewer_grade > 3 AND (_user_id IS NULL OR _user_id <> auth.uid()) THEN
    _user_id := auth.uid();
  END IF;

  RETURN QUERY
  WITH planned AS (
    SELECT pe.user_id AS uid, pe.mission_id AS mid, SUM(pe.planned_hours) AS ph
    FROM public.plan_entries pe
    WHERE pe.organization_id = _viewer_org
      AND pe.plan_date BETWEEN _start_date AND _end_date
      AND pe.status = 'approved'
      AND (_user_id IS NULL OR pe.user_id = _user_id)
    GROUP BY pe.user_id, pe.mission_id
  ),
  actual AS (
    SELECT te.user_id AS uid, te.mission_id AS mid, SUM(te.hours) AS ah
    FROM public.time_entries te
    WHERE te.organization_id = _viewer_org
      AND te.date BETWEEN _start_date AND _end_date
      AND te.status = 'approved'
      AND (_user_id IS NULL OR te.user_id = _user_id)
    GROUP BY te.user_id, te.mission_id
  )
  SELECT
    COALESCE(pl.uid, ac.uid),
    pr.full_name,
    COALESCE(pl.mid, ac.mid),
    m.name,
    COALESCE(pl.ph, 0),
    COALESCE(ac.ah, 0),
    CASE WHEN COALESCE(pl.ph, 0) > 0
      THEN ROUND((COALESCE(ac.ah, 0) / pl.ph) * 100)
      ELSE NULL END,
    COALESCE(ac.ah, 0) - COALESCE(pl.ph, 0)
  FROM planned pl
  FULL OUTER JOIN actual ac ON ac.uid = pl.uid AND ac.mid IS NOT DISTINCT FROM pl.mid
  LEFT JOIN public.profiles pr ON pr.id = COALESCE(pl.uid, ac.uid)
  LEFT JOIN public.missions m ON m.id = COALESCE(pl.mid, ac.mid)
  ORDER BY pr.full_name, m.name;
END;
$function$
;

-- get_rejection_context(_document_id uuid)
CREATE OR REPLACE FUNCTION public.get_rejection_context(_document_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _org uuid;
  _result jsonb;
BEGIN
  SELECT p.organization_id INTO _org FROM profiles p WHERE p.id = auth.uid();

  SELECT jsonb_build_object(
    'document_label', od.label,
    'reject_reason', od.reject_reason,
    'obligation_label', ot.label,
    'period_label', op.period_label,
    'due_date', op.due_date,
    'client_id', op.client_id,
    'client_name', c.name,
    'portal_emails', COALESCE((
      SELECT jsonb_agg(pu.email)
      FROM portal_users pu
      WHERE pu.client_id = op.client_id AND pu.is_active
    ), '[]'::jsonb),
    'contact_emails', COALESCE((
      SELECT jsonb_agg(cc.email)
      FROM client_contacts cc
      WHERE cc.client_id = op.client_id AND cc.email IS NOT NULL
    ), '[]'::jsonb)
  ) INTO _result
  FROM obligation_documents od
  JOIN obligation_periods op ON op.id = od.obligation_period_id
  JOIN obligation_types ot ON ot.id = op.obligation_type_id
  JOIN clients c ON c.id = op.client_id
  WHERE od.id = _document_id AND op.organization_id = _org;

  IF _result IS NULL THEN RAISE EXCEPTION 'Document introuvable'; END IF;
  RETURN _result;
END;
$function$
;

-- get_synthese_pdf_data(_user_id uuid, _exercice smallint)
CREATE OR REPLACE FUNCTION public.get_synthese_pdf_data(_user_id uuid, _exercice smallint)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _org uuid; _grade int; _o RECORD;
BEGIN
  SELECT p.organization_id, p.grade_level INTO _org, _grade
  FROM profiles p WHERE p.id = auth.uid();

  IF _user_id <> auth.uid() AND COALESCE(_grade, 99) > 2 THEN
    RAISE EXCEPTION 'Accès refusé';
  END IF;

  SELECT o.name, o.logo_url INTO _o FROM organizations o WHERE o.id = _org;

  RETURN jsonb_build_object(
    'organisation', jsonb_build_object('nom', _o.name, 'logo', _o.logo_url),
    'synthese', public.get_global_evaluation(_user_id, _exercice),
    'historique', public.get_evaluation_history(_user_id, NULL),
    'lecteur', (SELECT full_name FROM profiles WHERE id = auth.uid())
  );
END; $function$
;

