-- get_workload(_week_start date)
CREATE OR REPLACE FUNCTION public.get_workload(_week_start date DEFAULT (date_trunc('week'::text, (CURRENT_DATE)::timestamp with time zone))::date)
 RETURNS TABLE(user_id uuid, full_name text, grade text, allocated_hours numeric, planned_hours numeric, capacity_hours numeric, load_rate numeric, is_overloaded boolean, has_leave boolean)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
#variable_conflict use_column
DECLARE
  _viewer_org uuid;
  _viewer_grade integer;
  _week_end date := (_week_start + INTERVAL '6 days')::date;
BEGIN
  SELECT vp.organization_id, vp.grade_level INTO _viewer_org, _viewer_grade
  FROM public.profiles vp WHERE vp.id = auth.uid();

  IF _viewer_grade IS NULL OR _viewer_grade > 3 THEN
    RAISE EXCEPTION 'Accès refusé : vue réservée aux responsables';
  END IF;

  RETURN QUERY
  WITH capacite AS (
    SELECT p.id AS uid,
           COALESCE(
             (SELECT SUM(ua.available_hours)
                FROM user_availability ua
               WHERE ua.user_id = p.id
                 AND ua.date BETWEEN _week_start AND _week_end
                 AND ua.status <> 'leave'),
             p.weekly_capacity_hours,
             35
           ) AS cap,
           EXISTS (
             SELECT 1 FROM user_availability ua2
              WHERE ua2.user_id = p.id
                AND ua2.date BETWEEN _week_start AND _week_end
                AND ua2.status = 'leave'
           ) AS conge
    FROM profiles p
    WHERE p.organization_id = _viewer_org
  ),
  alloue AS (
    SELECT sa.user_id AS uid, SUM(sa.weekly_hours) AS ah
    FROM staffing_assignments sa
    WHERE sa.organization_id = _viewer_org
      AND sa.status IN ('proposed', 'accepted')
      AND sa.start_date <= _week_end
      AND (sa.end_date IS NULL OR sa.end_date >= _week_start)
    GROUP BY sa.user_id
  ),
  planifie AS (
    SELECT pe.user_id AS uid, SUM(pe.planned_hours) AS ph
    FROM plan_entries pe
    WHERE pe.organization_id = _viewer_org
      AND pe.week_start = _week_start
      AND pe.status IN ('submitted', 'approved')
      AND pe.entry_type <> 'conge'
    GROUP BY pe.user_id
  ),
  conge_plan AS (
    SELECT DISTINCT pe.user_id AS uid
    FROM plan_entries pe
    WHERE pe.organization_id = _viewer_org
      AND pe.week_start = _week_start
      AND pe.status IN ('submitted', 'approved')
      AND pe.entry_type = 'conge'
  )
  SELECT
    p.id,
    p.full_name,
    p.grade,
    COALESCE(a.ah, 0),
    COALESCE(pl.ph, 0),
    c.cap,
    CASE WHEN c.cap > 0
      THEN ROUND(GREATEST(COALESCE(a.ah, 0), COALESCE(pl.ph, 0)) / c.cap * 100)
      ELSE 0 END,
    GREATEST(COALESCE(a.ah, 0), COALESCE(pl.ph, 0)) > c.cap,
    (c.conge OR cp.uid IS NOT NULL)
  FROM profiles p
  JOIN capacite c ON c.uid = p.id
  LEFT JOIN alloue a ON a.uid = p.id
  LEFT JOIN planifie pl ON pl.uid = p.id
  LEFT JOIN conge_plan cp ON cp.uid = p.id
  WHERE p.organization_id = _viewer_org
  ORDER BY 7 DESC;
END;
$function$
;

-- grille_du_cabinet(_practice text)
CREATE OR REPLACE FUNCTION public.grille_du_cabinet(_practice text DEFAULT NULL::text)
 RETURNS TABLE(echelon_id uuid, practice text, famille text, echelon text, rang smallint, grade text, roles_permis text, actif boolean, occupants bigint, qui text, modifiable boolean)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT eg.id,
         eg.practice::text,
         eg.family,
         eg.echelon,
         eg.rank,
         eg.maps_to_grade,
         (SELECT string_agg(public.mission_role_label(r), ', '
                            ORDER BY public.mission_role_max_rank(r) DESC)
          FROM unnest(ARRAY['associe','directeur_mission','chef_mission',
                            'auditeur_experimente','auditeur','auditeur_junior']) r
          WHERE eg.rank BETWEEN public.mission_role_min_rank(r)
                            AND public.mission_role_max_rank(r)),
         eg.is_active,
         (SELECT count(*) FROM public.profiles p
           WHERE p.organization_id = eg.organization_id
             AND p.practice = eg.practice
             AND lower(btrim(p.grade_echelon)) = lower(btrim(eg.echelon))),
         (SELECT string_agg(p.full_name, ', ' ORDER BY p.full_name) FROM public.profiles p
           WHERE p.organization_id = eg.organization_id
             AND p.practice = eg.practice
             AND lower(btrim(p.grade_echelon)) = lower(btrim(eg.echelon))),
         public.est_directeur_associe(auth.uid())
  FROM public.evaluation_grades eg
  WHERE eg.organization_id = (SELECT p.organization_id FROM public.profiles p WHERE p.id = auth.uid())
    AND (_practice IS NULL OR eg.practice::text = _practice)
  ORDER BY eg.practice::text, eg.rank DESC;
$function$
;

-- handle_new_user()
CREATE OR REPLACE FUNCTION public.handle_new_user()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _token TEXT;
  _grade TEXT := 'AUD';
  _name TEXT;
  _org_id UUID := NULL;
  _inv_id UUID := NULL;
BEGIN
  -- Les comptes clients (espace client) ne reçoivent PAS de profil cabinet.
  -- Leur ligne portal_users est créée séparément par le flux d'invitation.
  IF NEW.raw_user_meta_data->>'account_type' = 'portal_client' THEN
    RETURN NEW;
  END IF;

  _token := NEW.raw_user_meta_data->>'invitation_token';
  IF _token IS NOT NULL AND _token <> '' THEN
    BEGIN
      SELECT i.id, i.organization_id, COALESCE(i.grade, 'AUD')
        INTO _inv_id, _org_id, _grade
      FROM public.invitations i
      WHERE i.token = _token
        -- SCRIPT 50 : l'invitation ne vaut que pour l'adresse invitée...
        AND lower(i.email) = lower(NEW.email)
        AND (i.expires_at IS NULL OR i.expires_at > now())
        -- ... et une seule fois. Une invitation acceptée ne resert que si le
        -- compte qu'elle a ouvert a disparu (renvoi du courriel de confirmation).
        AND (i.status = 'pending'
             OR (i.status = 'accepted'
                 AND NOT EXISTS (SELECT 1 FROM public.profiles p
                                 WHERE lower(p.email) = lower(NEW.email))))
      LIMIT 1;
    EXCEPTION WHEN OTHERS THEN NULL; END;
  END IF;

  _name := COALESCE(NULLIF(trim(NEW.raw_user_meta_data->>'full_name'), ''), split_part(NEW.email, '@', 1));
  IF length(_name) > 255 THEN _name := substring(_name, 1, 255); END IF;

  BEGIN
    INSERT INTO public.profiles (id, email, full_name, organization_id, grade)
    VALUES (NEW.id, NEW.email, _name, _org_id, _grade);
  EXCEPTION WHEN OTHERS THEN
    RAISE WARNING 'handle_new_user profiles insert failed: %', SQLERRM;
  END;

  BEGIN
    INSERT INTO public.user_roles (user_id, role, organization_id)
    VALUES (NEW.id, 'member', _org_id);
  EXCEPTION WHEN OTHERS THEN
    RAISE WARNING 'handle_new_user user_roles insert failed: %', SQLERRM;
  END;

  -- SCRIPT 50 : l'invitation est consommée.
  IF _inv_id IS NOT NULL THEN
    BEGIN
      UPDATE public.invitations SET status = 'accepted' WHERE id = _inv_id;
    EXCEPTION WHEN OTHERS THEN NULL; END;
  END IF;

  RETURN NEW;
END;
$function$
;

-- has_role(_user_id uuid, _role app_role)
CREATE OR REPLACE FUNCTION public.has_role(_user_id uuid, _role app_role)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT EXISTS (
    SELECT 1 FROM public.user_roles
    WHERE user_id = _user_id AND role = _role
  )
$function$
;

-- imputation_sur_tache_permise()
CREATE OR REPLACE FUNCTION public.imputation_sur_tache_permise()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _me uuid := auth.uid();
  _mission_de_la_tache uuid;
  _projet uuid;
BEGIN
  -- week_start est NOT NULL sans valeur par defaut : la base la deduit de la
  -- date plutot que de compter sur le front, qui n'a aucune raison de mieux
  -- savoir quel lundi precede une date. Decouvert a l'essai, sur un refus
  -- « null value in column week_start » qui n'avait rien a voir avec les
  -- droits.
  IF NEW.week_start IS NULL AND NEW.date IS NOT NULL THEN
    NEW.week_start := (date_trunc('week', NEW.date::timestamp))::date;
  END IF;

  IF _me IS NULL THEN RETURN NEW; END IF;
  IF NEW.task_id IS NULL THEN
    -- Imputation sans tache : il faut au moins etre de la mission visee.
    IF NEW.mission_id IS NOT NULL
       AND NOT public.can_access_mission(_me, NEW.mission_id) THEN
      RAISE EXCEPTION 'Vous n''etes pas membre de cette mission : vous ne pouvez pas y imputer du temps.';
    END IF;
    RETURN NEW;
  END IF;

  SELECT t.project_id, p.mission_id INTO _projet, _mission_de_la_tache
  FROM public.tasks t
  LEFT JOIN public.projects p ON p.id = t.project_id
  WHERE t.id = NEW.task_id;

  IF _projet IS NULL THEN
    -- Tache generale : imputable par tout le cabinet, et sans mission.
    IF NEW.mission_id IS NOT NULL THEN
      RAISE EXCEPTION 'Une tache generale ne se rattache a aucune mission : laissez la mission vide.';
    END IF;
    RETURN NEW;
  END IF;

  IF NOT public.can_access_task(_me, NEW.task_id) THEN
    RAISE EXCEPTION 'Vous n''avez pas acces a cette tache : vous ne pouvez pas y imputer du temps.';
  END IF;

  -- La mission de l'imputation doit etre celle de la tache, sans quoi les
  -- temps d'une mission se retrouveraient comptes dans une autre.
  IF NEW.mission_id IS NULL THEN
    NEW.mission_id := _mission_de_la_tache;
  ELSIF _mission_de_la_tache IS NOT NULL AND NEW.mission_id <> _mission_de_la_tache THEN
    RAISE EXCEPTION 'Cette tache appartient a une autre mission : le temps serait compte du mauvais cote.';
  END IF;

  IF NEW.project_id IS NULL THEN
    NEW.project_id := _projet;
  END IF;

  RETURN NEW;
END $function$
;

-- invitation_utilisable(_jeton text, _email text)
CREATE OR REPLACE FUNCTION public.invitation_utilisable(_jeton text, _email text)
 RETURNS TABLE(organization_id uuid, grade text, organization_name text)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT i.organization_id, COALESCE(i.grade, 'AUD'), o.name
  FROM public.invitations i
  JOIN public.organizations o ON o.id = i.organization_id
  WHERE i.token = _jeton
    AND lower(i.email) = lower(trim(_email))
    AND (i.expires_at IS NULL OR i.expires_at > now())
    AND (i.status = 'pending'
         OR (i.status = 'accepted'
             AND NOT EXISTS (SELECT 1 FROM public.profiles p
                             WHERE lower(p.email) = lower(trim(_email)))))
  LIMIT 1;
$function$
;

