-- jours_ouvrables(_debut date, _fin date, _org uuid)
CREATE OR REPLACE FUNCTION public.jours_ouvrables(_debut date, _fin date, _org uuid)
 RETURNS integer
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT count(*)::integer
  FROM generate_series(_debut, _fin, interval '1 day') AS j(d)
  WHERE EXTRACT(ISODOW FROM j.d)::smallint = ANY (
    COALESCE((SELECT o.working_days FROM public.organizations o WHERE o.id = _org),
             '{1,2,3,4,5}'::smallint[]))
$function$
;

-- log_evaluation_export(_kind text, _evaluation_id uuid, _user_id uuid, _exercice smallint, _storage_path text, _file_size integer)
