-- member_role_to_staffing(_role text)
CREATE OR REPLACE FUNCTION public.member_role_to_staffing(_role text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
AS $function$ SELECT _role $function$
;

-- mission_composition_defauts(_mission_id uuid)
CREATE OR REPLACE FUNCTION public.mission_composition_defauts(_mission_id uuid)
 RETURNS TABLE(regle text, defaut text, detail text)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _n_associe int; _n_chef int; _n_dm int; _dir uuid;
BEGIN
  SELECT count(*) FILTER (WHERE role = 'associe'),
         count(*) FILTER (WHERE role = 'chef_mission'),
         count(*) FILTER (WHERE role = 'directeur_mission')
    INTO _n_associe, _n_chef, _n_dm
  FROM mission_members WHERE mission_id = _mission_id;

  SELECT director_id INTO _dir FROM missions WHERE id = _mission_id;

  IF _n_associe = 0 THEN
    RETURN QUERY SELECT '1 · associe'::text, 'aucun associe'::text,
      'personne ne repond de cette mission, et aucun retrait n''y est possible'::text;
  END IF;

  IF _n_chef = 0 THEN
    RETURN QUERY SELECT '2 · chef'::text, 'aucun chef de mission'::text,
      'l''equipe n''a pas de responsable operationnel'::text;
  END IF;

  IF _n_dm >= 2 AND (_dir IS NULL OR NOT EXISTS (
      SELECT 1 FROM mission_members mm
      WHERE mm.mission_id = _mission_id AND mm.user_id = _dir
        AND mm.role = 'directeur_mission')) THEN
    RETURN QUERY SELECT '3 · directeur en chef'::text,
      'plusieurs directeurs de mission, aucun designe en chef'::text,
      _n_dm || ' directeurs de mission ; renseignez missions.director_id sur l''un d''eux';
  END IF;
END; $function$
;

-- mission_du_dossier(_folder_id uuid)
CREATE OR REPLACE FUNCTION public.mission_du_dossier(_folder_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _f RECORD; _garde int := 0;
BEGIN
  IF _folder_id IS NULL THEN RETURN NULL; END IF;
  LOOP
    _garde := _garde + 1;
    IF _garde > 20 THEN RETURN NULL; END IF;
    SELECT mission_id, parent_id INTO _f FROM public.document_folders WHERE id = _folder_id;
    IF _f IS NULL THEN RETURN NULL; END IF;
    IF _f.mission_id IS NOT NULL THEN RETURN _f.mission_id; END IF;
    IF _f.parent_id IS NULL THEN RETURN NULL; END IF;
    _folder_id := _f.parent_id;
  END LOOP;
END $function$
;

-- mission_member_grants_staffing()
CREATE OR REPLACE FUNCTION public.mission_member_grants_staffing()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _m RECORD;
BEGIN
  -- Une affectation vivante existe déjà : c'est elle qui a créé ce membre.
  -- Ce test ferme aussi la boucle entre les deux triggers.
  IF EXISTS (SELECT 1 FROM staffing_assignments s
             WHERE s.mission_id = NEW.mission_id
               AND s.user_id = NEW.user_id
               AND s.project_id IS NULL
               AND s.status <> 'cancelled') THEN
    RETURN NEW;
  END IF;

  SELECT organization_id, start_date, end_date, actual_end_date
    INTO _m FROM missions WHERE id = NEW.mission_id;
  IF _m IS NULL THEN RETURN NEW; END IF;

  INSERT INTO staffing_assignments
    (organization_id, mission_id, user_id, role,
     start_date, end_date, weekly_hours, assigned_by, status)
  VALUES (
     _m.organization_id, NEW.mission_id, NEW.user_id,
     public.member_role_to_staffing(NEW.role),
     COALESCE(_m.start_date, CURRENT_DATE),
     COALESCE(_m.actual_end_date, _m.end_date),
     NULL::numeric,              -- volume horaire à préciser au planning
     auth.uid(),
     'accepted')
  ON CONFLICT DO NOTHING;

  RETURN NEW;
END; $function$
;

