-- mission_role_grid()
CREATE OR REPLACE FUNCTION public.mission_role_grid()
 RETURNS TABLE(role text, libelle text, rang_min smallint, rang_max smallint)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  SELECT r, public.mission_role_label(r),
         public.mission_role_min_rank(r), public.mission_role_max_rank(r)
  FROM unnest(ARRAY['associe','directeur_mission','chef_mission',
                    'auditeur_experimente','auditeur','auditeur_junior']) r
  ORDER BY public.mission_role_max_rank(r) DESC;
$function$
;

-- mission_role_label(_role text)
CREATE OR REPLACE FUNCTION public.mission_role_label(_role text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
AS $function$
  SELECT CASE _role
    WHEN 'associe'              THEN 'Associé de mission'
    WHEN 'directeur_mission'    THEN 'Directeur de mission'
    WHEN 'chef_mission'         THEN 'Chef de mission'
    WHEN 'auditeur_experimente' THEN 'Auditeur expérimenté'
    WHEN 'auditeur'             THEN 'Auditeur'
    WHEN 'auditeur_junior'      THEN 'Auditeur junior'
    ELSE COALESCE(_role, 'membre')
  END;
$function$
;

-- mission_role_max_rank(_role text)
CREATE OR REPLACE FUNCTION public.mission_role_max_rank(_role text)
 RETURNS smallint
 LANGUAGE sql
 IMMUTABLE
AS $function$
  SELECT CASE _role
    WHEN 'associe'              THEN 18::smallint  -- Partner 3
    WHEN 'directeur_mission'    THEN 18::smallint  -- Partner 3
    WHEN 'chef_mission'         THEN 15::smallint  -- DM senior 3 : pas les Partner
    WHEN 'auditeur_experimente' THEN 15::smallint  -- idem
    WHEN 'auditeur'             THEN  4::smallint  -- Auditeur 2
    WHEN 'auditeur_junior'      THEN  2::smallint  -- Auditeur junior
  END;
$function$
;

-- mission_role_min_rank(_role text)
CREATE OR REPLACE FUNCTION public.mission_role_min_rank(_role text)
 RETURNS smallint
 LANGUAGE sql
 IMMUTABLE
AS $function$
  SELECT CASE _role
    WHEN 'associe'              THEN 16::smallint  -- Partner 1
    WHEN 'directeur_mission'    THEN 10::smallint  -- Directeur de mission 1
    WHEN 'chef_mission'         THEN  5::smallint  -- Auditeur senior 1
    WHEN 'auditeur_experimente' THEN  5::smallint  -- Auditeur senior 1
    WHEN 'auditeur'             THEN  3::smallint  -- Auditeur 1
    WHEN 'auditeur_junior'      THEN  1::smallint  -- Stagiaire
  END;
$function$
;

-- mission_roles_for_user(_user_id uuid)
CREATE OR REPLACE FUNCTION public.mission_roles_for_user(_user_id uuid)
 RETURNS TABLE(role text, libelle text, autorise boolean, motif text)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _rank smallint := public.profile_rank(_user_id);
BEGIN
  RETURN QUERY
  SELECT r,
         public.mission_role_label(r),
         _rank IS NOT NULL
           AND _rank BETWEEN public.mission_role_min_rank(r)
                         AND public.mission_role_max_rank(r),
         CASE
           WHEN _rank IS NULL THEN 'grade ou echelon non renseigne'
           WHEN _rank < public.mission_role_min_rank(r) THEN 'grade insuffisant'
           WHEN _rank > public.mission_role_max_rank(r) THEN 'grade trop eleve pour ce role'
           ELSE 'autorise'
         END
  FROM unnest(ARRAY['associe','directeur_mission','chef_mission',
                    'auditeur_experimente','auditeur','auditeur_junior']) r
  ORDER BY public.mission_role_max_rank(r) DESC;
END; $function$
;

-- mon_mot_de_passe_est_provisoire()
CREATE OR REPLACE FUNCTION public.mon_mot_de_passe_est_provisoire()
