-- niveau_du_grade(_grade text)
CREATE OR REPLACE FUNCTION public.niveau_du_grade(_grade text)
 RETURNS integer
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  SELECT CASE _grade
    WHEN 'DA'  THEN 1  WHEN 'DM'  THEN 2  WHEN 'MGR' THEN 3  WHEN 'SUP' THEN 4
    WHEN 'AS'  THEN 5  WHEN 'AUD' THEN 6  WHEN 'AJ'  THEN 7  WHEN 'STG' THEN 8
    ELSE NULL END;
$function$
;

-- niveau_requis_dossier(_folder_id uuid)
CREATE OR REPLACE FUNCTION public.niveau_requis_dossier(_folder_id uuid)
 RETURNS smallint
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _f RECORD;
  _garde int := 0;
BEGIN
  IF _folder_id IS NULL THEN RETURN NULL; END IF;
  LOOP
    _garde := _garde + 1;
    IF _garde > 20 THEN RETURN 3::smallint; END IF;  -- arbre circulaire : on ferme
    SELECT kind, parent_id INTO _f FROM public.document_folders WHERE id = _folder_id;
    IF _f IS NULL THEN RETURN NULL; END IF;
    IF _f.kind IS NOT NULL THEN
      RETURN public.niveau_requis_sorte_dossier(_f.kind);
    END IF;
    IF _f.parent_id IS NULL THEN
      -- Sous-dossier libre sans ancetre type : on ferme au plus strict.
      RETURN 3::smallint;
    END IF;
    _folder_id := _f.parent_id;
  END LOOP;
END $function$
;

-- niveau_requis_sorte_dossier(_kind text)
CREATE OR REPLACE FUNCTION public.niveau_requis_sorte_dossier(_kind text)
 RETURNS smallint
 LANGUAGE sql
 IMMUTABLE
AS $function$
  SELECT CASE _kind
    -- Conteneur : tout membre le voit, mais on n'y depose rien.
    WHEN 'dossier_client'            THEN 6::smallint
    WHEN 'dossier_permanent'         THEN 3::smallint
    WHEN 'dossier_important'         THEN 4::smallint
    WHEN 'dossier_courant'           THEN 6::smallint
    WHEN 'dossier_rapport_synthese'  THEN 3::smallint
    ELSE NULL
  END;
$function$
;

-- niveau_role(_role text)
CREATE OR REPLACE FUNCTION public.niveau_role(_role text)
 RETURNS smallint
 LANGUAGE sql
 IMMUTABLE
AS $function$
  SELECT CASE _role
    WHEN 'associe'              THEN 1::smallint
    WHEN 'directeur_mission'    THEN 2::smallint
    WHEN 'chef_mission'         THEN 3::smallint
    WHEN 'auditeur_experimente' THEN 4::smallint
    WHEN 'auditeur'             THEN 5::smallint
    WHEN 'auditeur_junior'      THEN 6::smallint
  END;
$function$
;

-- normalize_profile_echelon()
CREATE OR REPLACE FUNCTION public.normalize_profile_echelon()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _canon text; _exists boolean;
BEGIN
  IF NEW.grade_echelon IS NULL OR NEW.practice IS NULL
     OR NEW.organization_id IS NULL THEN
    RETURN NEW;
  END IF;

  SELECT EXISTS (SELECT 1 FROM evaluation_grades g
                 WHERE g.organization_id = NEW.organization_id
                   AND g.practice = NEW.practice)
    INTO _exists;

  -- Référentiel pas encore amorcé pour ce cabinet : rien à valider.
  IF NOT _exists THEN RETURN NEW; END IF;

  SELECT g.echelon INTO _canon FROM evaluation_grades g
  WHERE g.organization_id = NEW.organization_id
    AND g.practice = NEW.practice
    AND lower(btrim(g.echelon)) = lower(btrim(NEW.grade_echelon))
  LIMIT 1;

  IF _canon IS NULL THEN
    RAISE EXCEPTION
      'Échelon « % » inconnu pour la practice %. Valeurs admises : %',
      NEW.grade_echelon, NEW.practice,
      (SELECT string_agg(g.echelon, ', ' ORDER BY g.rank)
       FROM evaluation_grades g
       WHERE g.organization_id = NEW.organization_id AND g.practice = NEW.practice);
  END IF;

  NEW.grade_echelon := _canon;
  RETURN NEW;
END; $function$
;

-- notify_document_deposited()
CREATE OR REPLACE FUNCTION public.notify_document_deposited()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _assigned uuid;
  _client text;
BEGIN
  IF NEW.status <> 'deposee' OR OLD.status IS NOT DISTINCT FROM 'deposee' THEN
    RETURN NEW;
  END IF;

  SELECT op.assigned_to, c.name INTO _assigned, _client
  FROM obligation_periods op
  JOIN clients c ON c.id = op.client_id
  WHERE op.id = NEW.obligation_period_id;

  IF _assigned IS NOT NULL THEN
    INSERT INTO notifications (user_id, type, title, content, entity_type, entity_id, priority)
    VALUES (_assigned, 'document_deposited', 'Pièce déposée à valider',
      COALESCE(_client, 'Un client') || ' a déposé « ' || NEW.label || ' ». À vérifier et valider.',
      'obligation', NEW.obligation_period_id, 'normal');
  END IF;
  RETURN NEW;
END; $function$
;

-- notify_obligation_assigned()
CREATE OR REPLACE FUNCTION public.notify_obligation_assigned()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _client TEXT;
  _label TEXT;
BEGIN
  IF NEW.assigned_to IS NULL OR NEW.assigned_to = auth.uid() THEN RETURN NEW; END IF;
  IF TG_OP = 'UPDATE' AND OLD.assigned_to IS NOT DISTINCT FROM NEW.assigned_to THEN RETURN NEW; END IF;

  SELECT c.name INTO _client FROM clients c WHERE c.id = NEW.client_id;
  SELECT ot.label INTO _label FROM obligation_types ot WHERE ot.id = NEW.obligation_type_id;

  INSERT INTO notifications (user_id, type, title, content, entity_type, entity_id, priority)
  VALUES (NEW.assigned_to, 'obligation_assigned', 'Dossier à traiter',
    COALESCE(_label,'') || ' — ' || COALESCE(_client,'') || ' (' || NEW.period_label ||
    ') — échéance le ' || to_char(NEW.due_date, 'DD/MM/YYYY'),
    'obligation', NEW.id, 'normal');
  RETURN NEW;
END; $function$
;

-- notify_plan_submitted()
CREATE OR REPLACE FUNCTION public.notify_plan_submitted()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _author TEXT;
  _chief UUID;
BEGIN
  IF NEW.status <> 'submitted' OR OLD.status = 'submitted' THEN RETURN NEW; END IF;

  SELECT p.full_name INTO _author FROM profiles p WHERE p.id = NEW.user_id;
  SELECT sa.assigned_by INTO _chief
  FROM staffing_assignments sa
  WHERE sa.user_id = NEW.user_id AND sa.mission_id = NEW.mission_id
  LIMIT 1;

  IF _chief IS NOT NULL AND _chief <> NEW.user_id THEN
    INSERT INTO notifications (user_id, type, title, content, entity_type, entity_id, priority)
    VALUES (_chief, 'plan_submitted', 'Planning à valider',
      COALESCE(_author, '') || ' a soumis son planning de la semaine du ' || NEW.week_start,
      'plan', NEW.id, 'normal');
  END IF;
  RETURN NEW;
END; $function$
;

-- notify_portal_document_shared()
