-- notify_portal_document_uploaded()
CREATE OR REPLACE FUNCTION public.notify_portal_document_uploaded()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _responsable uuid;
  _client_name text;
BEGIN
  IF NEW.direction <> 'from_client' THEN RETURN NEW; END IF;

  SELECT c.name INTO _client_name FROM clients c WHERE c.id = NEW.client_id;

  -- Responsable du dossier comptable, sinon les responsables de l'organisation
  SELECT cfp.collaborateur_id INTO _responsable
  FROM client_fiscal_profile cfp WHERE cfp.client_id = NEW.client_id;

  IF _responsable IS NOT NULL THEN
    INSERT INTO notifications (user_id, type, title, content, entity_type, entity_id, priority)
    VALUES (_responsable, 'portal_document_received', 'Document déposé par un client',
      COALESCE(_client_name, 'Un client') || ' a déposé « ' || NEW.title || ' ».',
      'client', NEW.client_id, 'normal');
  ELSE
    INSERT INTO notifications (user_id, type, title, content, entity_type, entity_id, priority)
    SELECT p.id, 'portal_document_received', 'Document déposé par un client',
      COALESCE(_client_name, 'Un client') || ' a déposé « ' || NEW.title || ' ».',
      'client', NEW.client_id, 'normal'
    FROM profiles p
    WHERE p.organization_id = NEW.organization_id AND p.grade_level <= 3;
  END IF;

  INSERT INTO portal_access_log
    (portal_user_id, client_id, organization_id, action, entity_type, entity_id, details)
  VALUES (auth.uid(), NEW.client_id, NEW.organization_id, 'document_uploaded_by_client',
          'portal_document', NEW.id, jsonb_build_object('title', NEW.title));

  RETURN NEW;
END; $function$
;

-- notify_staffing()
CREATE OR REPLACE FUNCTION public.notify_staffing()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _mission_name text; _assigner text;
BEGIN
  IF NEW.status = 'cancelled' THEN RETURN NEW; END IF;
  IF NEW.user_id = NEW.assigned_by THEN RETURN NEW; END IF;

  SELECT m.name        INTO _mission_name FROM missions m WHERE m.id = NEW.mission_id;
  SELECT p.full_name   INTO _assigner     FROM profiles p WHERE p.id = NEW.assigned_by;

  INSERT INTO notifications
    (user_id, type, title, content, entity_type, entity_id, priority)
  VALUES (
    NEW.user_id, 'staffing_assigned', 'Vous êtes intégré à une mission',
    COALESCE(_assigner, 'La direction') || ' vous a intégré à la mission « ' ||
    COALESCE(_mission_name, '') || ' » en tant que ' ||
    public.mission_role_label(NEW.role) || '.',
    'mission', NEW.mission_id, 'high');

  RETURN NEW;
END; $function$
;

-- notify_staffing_adjustment()
CREATE OR REPLACE FUNCTION public.notify_staffing_adjustment()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _mission_name TEXT;
  _collaborator TEXT;
BEGIN
  IF NEW.status <> 'adjustment_requested'
     OR OLD.status IS NOT DISTINCT FROM 'adjustment_requested' THEN
    RETURN NEW;
  END IF;

  IF NEW.assigned_by IS NULL OR NEW.assigned_by = NEW.user_id THEN
    RETURN NEW;
  END IF;

  SELECT m.name INTO _mission_name FROM missions m WHERE m.id = NEW.mission_id;
  SELECT p.full_name INTO _collaborator FROM profiles p WHERE p.id = NEW.user_id;

  INSERT INTO notifications (user_id, type, title, content, entity_type, entity_id, priority)
  VALUES (
    NEW.assigned_by,
    'staffing_adjustment_requested',
    'Ajustement d''affectation demandé',
    COALESCE(_collaborator, 'Un collaborateur') || ' demande un ajustement sur la mission ""' ||
    COALESCE(_mission_name, '') || '"" : ' || left(COALESCE(NEW.collaborator_note, ''), 120),
    'staffing', NEW.id, 'high'
  );
  RETURN NEW;
END;
$function$
;

-- notify_staffing_response()
CREATE OR REPLACE FUNCTION public.notify_staffing_response()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _mission_name TEXT;
  _chef TEXT;
  _title TEXT;
  _body TEXT;
BEGIN
  -- Se déclenche quand le responsable répond à une demande d'ajustement
  IF OLD.status IS DISTINCT FROM 'adjustment_requested' THEN RETURN NEW; END IF;
  IF NEW.status = 'adjustment_requested' THEN RETURN NEW; END IF;
  IF auth.uid() = NEW.user_id THEN RETURN NEW; END IF;

  SELECT m.name INTO _mission_name FROM missions m WHERE m.id = NEW.mission_id;
  SELECT p.full_name INTO _chef FROM profiles p WHERE p.id = auth.uid();

  IF NEW.status = 'cancelled' THEN
    _title := 'Affectation annulée';
    _body  := 'Votre affectation sur ""' || COALESCE(_mission_name, '') || '"" a été annulée.';
  ELSE
    -- Retour en 'proposed' : le responsable a arbitré
    _title := 'Réponse à votre demande d''ajustement';
    _body  := COALESCE(_chef, 'Votre responsable') || ' a répondu concernant ""' ||
              COALESCE(_mission_name, '') || '"" — nouveau volume : ' ||
              COALESCE(NEW.weekly_hours::text, '?') || 'h/semaine. ' ||
              left(COALESCE(NEW.chef_response, ''), 120);
  END IF;

  INSERT INTO notifications (user_id, type, title, content, entity_type, entity_id, priority)
  VALUES (NEW.user_id, 'staffing_response', _title, _body, 'staffing', NEW.id, 'high');

  RETURN NEW;
END;
$function$
;

-- notify_task_assignment()
CREATE OR REPLACE FUNCTION public.notify_task_assignment()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _task_title TEXT;
  _assigner_name TEXT;
  _project_id UUID;
BEGIN
  IF NEW.user_id = NEW.assigned_by THEN RETURN NEW; END IF;

  SELECT title, project_id INTO _task_title, _project_id FROM tasks WHERE id = NEW.task_id;
  SELECT full_name INTO _assigner_name FROM profiles WHERE id = NEW.assigned_by;

  INSERT INTO notifications (user_id, type, title, content, entity_type, entity_id, priority)
  VALUES (
    NEW.user_id, 'task_assigned', 'Nouvelle tâche assignée',
    COALESCE(_assigner_name, 'Un responsable') || ' vous a assigné : ""' || COALESCE(_task_title, '') || '""',
    'task', _project_id, 'high'
  );
  RETURN NEW;
END; $function$
;

-- notify_task_submission()
CREATE OR REPLACE FUNCTION public.notify_task_submission()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _task_title TEXT;
  _project_id UUID;
  _project_lead UUID;
  _submitter_name TEXT;
BEGIN
  SELECT t.title, t.project_id, p.lead_id INTO _task_title, _project_id, _project_lead
  FROM tasks t JOIN projects p ON p.id = t.project_id WHERE t.id = NEW.task_id;

  SELECT full_name INTO _submitter_name FROM profiles WHERE id = NEW.submitted_by;

  IF NEW.type = 'submission' THEN
    -- Notifier le chef de projet
    IF _project_lead IS NOT NULL AND _project_lead != NEW.submitted_by THEN
      INSERT INTO notifications (user_id, type, title, content, entity_type, entity_id, priority)
      VALUES (_project_lead, 'submission_received', 'Travail soumis',
        COALESCE(_submitter_name, '') || ' a soumis la tâche : ""' || COALESCE(_task_title, '') || '""',
        'task', _project_id, 'high');
    END IF;

  ELSIF NEW.type = 'validation' THEN
    -- Notifier tous les assignés de la tâche
    INSERT INTO notifications (user_id, type, title, content, entity_type, entity_id, priority)
    SELECT ta.user_id, 'task_validated', 'Tâche validée',
      'Votre tâche ""' || COALESCE(_task_title, '') || '"" a été validée' ||
      CASE WHEN NEW.rating IS NOT NULL THEN ' (note : ' || NEW.rating || '/4)' ELSE '' END,
      'task', _project_id, 'normal'
    FROM task_assignments ta WHERE ta.task_id = NEW.task_id AND ta.user_id != NEW.reviewed_by;

  ELSIF NEW.type = 'rejection' THEN
    -- Notifier les assignés qu'une correction est demandée
    INSERT INTO notifications (user_id, type, title, content, entity_type, entity_id, priority)
    SELECT ta.user_id, 'correction_needed', 'Correction demandée',
      'La tâche ""' || COALESCE(_task_title, '') || '"" nécessite des corrections',
      'task', _project_id, 'high'
    FROM task_assignments ta WHERE ta.task_id = NEW.task_id AND ta.user_id != NEW.reviewed_by;
  END IF;

  RETURN NEW;
END; $function$
;

-- occupation_du_jour(_user_id uuid, _jour date)
CREATE OR REPLACE FUNCTION public.occupation_du_jour(_user_id uuid, _jour date)
 RETURNS TABLE(tache text, mission text, heures numeric, action text, quantite text, etat text)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT
    -- Le titre d'une tache et le nom d'une mission appartiennent a la
    -- mission : masques pour qui n'en fait pas partie. Les heures et les
    -- actions declarees restent lisibles, elles relevent de la personne.
    CASE WHEN te.mission_id IS NULL
              OR te.user_id = auth.uid()
              OR public.can_access_mission(auth.uid(), te.mission_id)
         THEN COALESCE(t.title, '(sans tache)')
         ELSE '(tache d''une mission hors de votre portee)' END,
    CASE WHEN te.mission_id IS NULL THEN '(hors mission)'
         WHEN te.user_id = auth.uid()
              OR public.can_access_mission(auth.uid(), te.mission_id)
         THEN COALESCE(m.name, '(hors mission)')
         ELSE '(mission hors de votre portee)' END,
    COALESCE(ae.heures, te.hours),
    ae.intitule,
    CASE WHEN ae.quantite IS NULL THEN NULL
         ELSE ae.quantite::text||' '||COALESCE(ae.unite,'') END,
    ae.etat
  FROM public.time_entries te
  LEFT JOIN public.tasks t ON t.id = te.task_id
  LEFT JOIN public.missions m ON m.id = te.mission_id
  LEFT JOIN public.actions_elementaires ae ON ae.time_entry_id = te.id
  WHERE te.user_id = _user_id
    AND te.date = _jour
    AND public.peut_voir_donnee_personnelle(auth.uid(), te.mission_id, te.user_id)
  ORDER BY m.name NULLS LAST, t.title NULLS LAST, ae.ordre NULLS LAST, ae.intitule;
$function$
;

-- open_annual_campaign(_exercice smallint, _due_date date)
CREATE OR REPLACE FUNCTION public.open_annual_campaign(_exercice smallint DEFAULT NULL::smallint, _due_date date DEFAULT NULL::date)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _org uuid; _grade int; _ex smallint;
  _created int := 0; _incomplets int := 0; _sans_evaluateur int := 0; _deja int := 0;
  _r RECORD; _evaluator uuid;
BEGIN
  SELECT p.organization_id, p.grade_level INTO _org, _grade FROM profiles p WHERE p.id = auth.uid();
  IF COALESCE(_grade, 99) > 2 THEN
    RAISE EXCEPTION 'Accès refusé : l''ouverture de la campagne annuelle relève du Directeur Associé ou du Directeur de Mission';
  END IF;
  _ex := COALESCE(_exercice, public.fiscal_exercice(CURRENT_DATE, _org));

  FOR _r IN
    SELECT p.id, p.grade_level, p.practice, p.grade_echelon FROM profiles p
    WHERE p.organization_id = _org AND COALESCE(p.is_active, true)
    ORDER BY p.grade_level, p.full_name
  LOOP
    IF EXISTS (SELECT 1 FROM evaluation_assignments a WHERE a.evaluatee_id=_r.id AND a.eval_type='annuelle' AND a.exercice=_ex AND a.mission_id IS NULL AND a.status<>'annulee') THEN
      _deja := _deja + 1; CONTINUE;
    END IF;
    IF _r.practice IS NULL OR _r.grade_echelon IS NULL THEN
      _incomplets := _incomplets + 1; CONTINUE;
    END IF;
    _evaluator := NULL;
    SELECT e.evaluator_id INTO _evaluator FROM evaluations e
    WHERE e.evaluatee_id = _r.id AND e.eval_type = 'mission' AND e.exercice = _ex
      AND e.status IN ('validee','cloturee') AND e.evaluator_id <> _r.id
    GROUP BY e.evaluator_id ORDER BY COUNT(*) DESC, MAX(e.validated_at) DESC LIMIT 1;
    IF _evaluator IS NULL THEN
      SELECT p2.id INTO _evaluator FROM profiles p2
      WHERE p2.organization_id = _org AND p2.grade_level < _r.grade_level
        AND COALESCE(p2.is_active, true) AND p2.id <> _r.id
      ORDER BY p2.grade_level DESC LIMIT 1;
    END IF;
    IF _evaluator IS NULL THEN _sans_evaluateur := _sans_evaluateur + 1; CONTINUE; END IF;
    INSERT INTO evaluation_assignments (organization_id, mission_id, eval_type, exercice, evaluator_id, evaluatee_id, assigned_by, due_date)
    VALUES (_org, NULL, 'annuelle', _ex, _evaluator, _r.id, auth.uid(), _due_date)
    ON CONFLICT DO NOTHING;
    IF FOUND THEN _created := _created + 1; END IF;
  END LOOP;

  RETURN jsonb_build_object('exercice', _ex, 'affectations_creees', _created, 'profils_incomplets', _incomplets, 'sans_evaluateur', _sans_evaluateur, 'deja_ouvertes', _deja);
END; $function$
;

-- open_dossier_evaluations(_dossier_id uuid, _exercice smallint, _due_date date)
CREATE OR REPLACE FUNCTION public.open_dossier_evaluations(_dossier_id uuid, _exercice smallint DEFAULT NULL::smallint, _due_date date DEFAULT NULL::date)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _org uuid; _grade int; _me uuid := auth.uid();
  _f RECORD; _ex smallint; _created int := 0; _skipped int := 0;
BEGIN
  SELECT p.organization_id, p.grade_level INTO _org, _grade
  FROM profiles p WHERE p.id = _me;

  SELECT * INTO _f FROM client_fiscal_profile
   WHERE id = _dossier_id AND organization_id = _org;
  IF _f IS NULL THEN
    RAISE EXCEPTION 'Dossier comptable introuvable. Le profil fiscal du client doit exister avant toute évaluation de dossier.';
  END IF;

  IF NOT (
    _f.collaborateur_id = _me
    OR COALESCE(_grade, 99) <= 2
    OR EXISTS (SELECT 1 FROM client_obligations o
               WHERE o.client_id = _f.client_id AND o.responsible_id = _me
                 AND COALESCE(o.is_active, true))
  ) THEN
    RAISE EXCEPTION 'Seul le responsable du dossier, le responsable d''une obligation du client, ou la direction, peut ouvrir les évaluations';
  END IF;

  _ex := COALESCE(_exercice, fiscal_exercice(CURRENT_DATE, _org));

  INSERT INTO evaluation_assignments
    (organization_id, dossier_id, eval_type, exercice,
     evaluator_id, evaluatee_id, assigned_by, due_date)
  SELECT _org, _dossier_id, 'mission', _ex, _me, d.user_id, _me, _due_date
  FROM public.dossier_participants(_dossier_id, _ex) d
  JOIN profiles p ON p.id = d.user_id
  WHERE d.user_id <> _me
    AND p.organization_id = _org
    AND p.grade_level > COALESCE(_grade, 0)
  ON CONFLICT DO NOTHING;

  GET DIAGNOSTICS _created = ROW_COUNT;

  SELECT COUNT(*) INTO _skipped
  FROM public.dossier_participants(_dossier_id, _ex) d
  JOIN profiles p ON p.id = d.user_id
  WHERE p.practice IS NULL OR p.grade_echelon IS NULL;

  RETURN jsonb_build_object(
    'success', true,
    'created', _created,
    'exercice', _ex,
    'dossier', public.dossier_label(_dossier_id),
    'periode', public.exercice_label_dossier(_dossier_id, _ex),
    'practice', public.resolve_dossier_practice(_dossier_id),
    'profils_incomplets', _skipped);
END; $function$
;

-- open_evaluation(_assignment_id uuid)
CREATE OR REPLACE FUNCTION public.open_evaluation(_assignment_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _a RECORD; _prac public.eval_practice; _ech text; _tpl uuid; _eval uuid;
  _start date; _end date; _ex smallint; _home public.eval_practice; _home_ech text;
BEGIN
  SELECT * INTO _a FROM evaluation_assignments WHERE id = _assignment_id;
  IF _a IS NULL THEN RAISE EXCEPTION 'Affectation introuvable'; END IF;
  IF _a.evaluator_id <> auth.uid() THEN
    RAISE EXCEPTION 'Seul l''évaluateur désigné peut ouvrir cette évaluation';
  END IF;

  -- Ouverture idempotente : un double clic ne crée pas une seconde
  -- évaluation, sinon la synthèse compterait deux fois le même objet.
  SELECT id INTO _eval FROM evaluations WHERE assignment_id = _assignment_id;
  IF _eval IS NOT NULL THEN RETURN _eval; END IF;

  SELECT p.practice, p.grade_echelon INTO _home, _home_ech
  FROM profiles p WHERE p.id = _a.evaluatee_id;

  IF _home IS NULL OR _home_ech IS NULL THEN
    RAISE EXCEPTION 'La practice de rattachement et l''échelon du collaborateur doivent être renseignés avant toute évaluation';
  END IF;

  -- La practice de l'évaluation, puis l'échelon équivalent dans cette
  -- practice : un Consultant Senior 1 devient Senior Auditor 1 sur un
  -- dossier comptable, même rang, même grade.
  _prac := public.resolve_evaluation_practice(
             _a.practice, _a.mission_id, _a.evaluatee_id, _a.eval_type,
             _a.dossier_id);
  IF _prac IS NULL THEN
    RAISE EXCEPTION 'Aucune practice déterminable pour cette évaluation';
  END IF;

  _ech := public.resolve_echelon(_a.evaluatee_id, _prac);
  IF _ech IS NULL THEN
    RAISE EXCEPTION 'Aucun échelon équivalent à « % » dans la practice %', _home_ech, _prac;
  END IF;

  SELECT id INTO _tpl FROM evaluation_templates
  WHERE organization_id = _a.organization_id AND eval_type = _a.eval_type
    AND practice = _prac AND lower(btrim(echelon)) = lower(btrim(_ech)) AND is_active
  ORDER BY version DESC LIMIT 1;

  IF _tpl IS NULL THEN
    RAISE EXCEPTION
      'Aucune grille % pour la practice % à l''échelon « % ». Échelons attendus : %',
      _a.eval_type, _prac, _ech,
      COALESCE((SELECT string_agg(DISTINCT t.echelon, ', ' ORDER BY t.echelon)
                FROM evaluation_templates t
                WHERE t.organization_id = _a.organization_id
                  AND t.eval_type = _a.eval_type AND t.practice = _prac),
               'aucune grille installée pour cette practice');
  END IF;

  IF _a.dossier_id IS NOT NULL THEN
    -- Dossier comptable : la période évaluée est l'exercice comptable du
    -- client, pas celui du cabinet.
    _ex := COALESCE(_a.exercice, fiscal_exercice(CURRENT_DATE, _a.organization_id));
    SELECT w.period_start, w.period_end INTO _start, _end
    FROM public.dossier_exercice_window(_a.dossier_id, _ex) w;

  ELSIF _a.mission_id IS NOT NULL THEN
    SELECT start_date, COALESCE(actual_end_date, end_date)
      INTO _start, _end FROM missions WHERE id = _a.mission_id;
    _ex := COALESCE(_a.exercice, fiscal_exercice(COALESCE(_end, CURRENT_DATE), _a.organization_id));

  ELSE
    _ex := COALESCE(_a.exercice, fiscal_exercice(CURRENT_DATE, _a.organization_id));
    SELECT make_date(_ex, fiscal_year_start_month, 1)
      INTO _start FROM organizations WHERE id = _a.organization_id;
    _end := (_start + INTERVAL '1 year - 1 day')::date;
  END IF;

  INSERT INTO evaluations
    (organization_id, assignment_id, template_id, eval_type, practice, echelon,
     mission_id, dossier_id, mission_code, evaluatee_id, evaluator_id, exercice,
     period_start, period_end)
  VALUES (_a.organization_id, _a.id, _tpl, _a.eval_type, _prac, _ech,
     _a.mission_id, _a.dossier_id,
     (SELECT code FROM missions WHERE id = _a.mission_id),
     _a.evaluatee_id, _a.evaluator_id, _ex, _start, _end)
  RETURNING id INTO _eval;

  UPDATE evaluation_assignments SET status = 'en_cours' WHERE id = _a.id;
  RETURN _eval;
END; $function$
;

-- open_mission_evaluations(_mission_id uuid)
CREATE OR REPLACE FUNCTION public.open_mission_evaluations(_mission_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _org uuid; _grade int; _me uuid := auth.uid();
  _created int := 0; _skipped int := 0; _m RECORD;
BEGIN
  SELECT p.organization_id, p.grade_level INTO _org, _grade
  FROM profiles p WHERE p.id = _me;

  SELECT * INTO _m FROM missions WHERE id = _mission_id AND organization_id = _org;
  IF _m IS NULL THEN RAISE EXCEPTION 'Mission introuvable'; END IF;

  -- Le chef de mission, le directeur de mission ou la direction ouvre
  -- la campagne. Un membre inscrit avec un rôle de responsable y donne
  -- également droit, pour les missions où l'encadrement passe par
  -- l'équipe plutôt que par les colonnes de la mission.
  IF NOT (
    _m.chief_id = _me
    OR _m.director_id = _me
    OR COALESCE(_grade, 99) <= 2
    OR EXISTS (SELECT 1 FROM mission_members mm
               WHERE mm.mission_id = _mission_id AND mm.user_id = _me
                 AND mm.role IN ('chef_mission', 'directeur_mission', 'associe'))
  ) THEN
    RAISE EXCEPTION 'Seul le chef ou le directeur de la mission, ou la direction, peut ouvrir les évaluations';
  END IF;

  INSERT INTO evaluation_assignments
    (organization_id, mission_id, eval_type, evaluator_id, evaluatee_id, assigned_by)
  SELECT _org, _mission_id, 'mission', _me, mm.user_id, _me
  FROM mission_members mm
  JOIN profiles p ON p.id = mm.user_id
  WHERE mm.mission_id = _mission_id
    AND mm.user_id <> _me
    AND p.grade_level > COALESCE(_grade, 0)   -- uniquement les grades inférieurs
  ON CONFLICT DO NOTHING;

  GET DIAGNOSTICS _created = ROW_COUNT;

  SELECT COUNT(*) INTO _skipped FROM mission_members mm
  JOIN profiles p ON p.id = mm.user_id
  WHERE mm.mission_id = _mission_id AND (p.practice IS NULL OR p.grade_echelon IS NULL);

  RETURN jsonb_build_object('success', true, 'created', _created,
    'profils_incomplets', _skipped);
END; $function$
;

-- pas_d_affectation_sur_mission_annulee()
CREATE OR REPLACE FUNCTION public.pas_d_affectation_sur_mission_annulee()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _statut text;
BEGIN
  SELECT m.status INTO _statut FROM public.missions m WHERE m.id = NEW.mission_id;
  IF _statut <> 'cancelled' THEN RETURN NEW; END IF;

  -- « On n'y inscrit plus PERSONNE » veut dire personne de NOUVEAU. Une
  -- reaffirmation du meme membre n'inscrit personne, et il faut la laisser
  -- passer : vos declencheurs forment une boucle — mission_members nourrit
  -- staffing_assignments, qui reecrit dans mission_members. Mon premier jet
  -- refusait ce second passage, et une mission creee en « annulee » ne
  -- pouvait alors pas naitre du tout. Vu a l'essai.
  IF EXISTS (SELECT 1 FROM public.mission_members mm
              WHERE mm.mission_id = NEW.mission_id AND mm.user_id = NEW.user_id) THEN
    RETURN NEW;
  END IF;

  -- La fenetre de la creation : une equipe encore vide accepte son premier
  -- membre, qui est le createur. Elle ne se reouvre jamais ensuite.
  IF NOT EXISTS (SELECT 1 FROM public.mission_members mm
                  WHERE mm.mission_id = NEW.mission_id) THEN
    RETURN NEW;
  END IF;

  RAISE EXCEPTION 'Cette mission est annulee : on n''y inscrit plus personne. Les membres deja en place y restent.';
END $function$
;

-- peut_ajouter_directement(_organization_id uuid, _grade text)
CREATE OR REPLACE FUNCTION public.peut_ajouter_directement(_organization_id uuid, _grade text)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _org    uuid;
  _niveau integer;
BEGIN
  IF auth.uid() IS NULL OR _organization_id IS NULL
     OR public.niveau_du_grade(_grade) IS NULL THEN
    RETURN false;
  END IF;

  IF public.is_platform_admin('admin') THEN
    RETURN EXISTS (SELECT 1 FROM public.organizations WHERE id = _organization_id);
  END IF;

  SELECT organization_id, grade_level INTO _org, _niveau
  FROM public.profiles WHERE id = auth.uid();

  RETURN _org = _organization_id AND _niveau = 1;   -- le DA, dans son cabinet
END;
$function$
;

-- peut_deposer_dans_dossier(_user_id uuid, _folder_id uuid)
CREATE OR REPLACE FUNCTION public.peut_deposer_dans_dossier(_user_id uuid, _folder_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _kind text;
BEGIN
  IF NOT public.peut_voir_dossier(_user_id, _folder_id) THEN RETURN false; END IF;
  SELECT kind INTO _kind FROM public.document_folders WHERE id = _folder_id;
  -- « Dossier client » est un conteneur : les pieces vont dans ses trois
  -- niveaux, pas dans le conteneur lui-meme.
  IF _kind = 'dossier_client' THEN RETURN false; END IF;
  RETURN true;
END $function$
;

-- peut_fixer_le_budget(_user_id uuid, _mission_id uuid)
CREATE OR REPLACE FUNCTION public.peut_fixer_le_budget(_user_id uuid, _mission_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT EXISTS (
    SELECT 1 FROM public.mission_members mm
    WHERE mm.mission_id = _mission_id
      AND mm.user_id = _user_id
      AND mm.role = 'associe'
  );
$function$
;

-- peut_inviter(_organization_id uuid, _grade text)
CREATE OR REPLACE FUNCTION public.peut_inviter(_organization_id uuid, _grade text)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _cible  integer := public.niveau_du_grade(_grade);
  _org    uuid;
  _niveau integer;
BEGIN
  IF auth.uid() IS NULL OR _cible IS NULL OR _organization_id IS NULL THEN
    RETURN false;
  END IF;

  -- L'administrateur de la plateforme crée le premier DA d'un cabinet.
  IF public.is_platform_admin('admin') THEN
    RETURN true;
  END IF;

  SELECT organization_id, grade_level INTO _org, _niveau
  FROM public.profiles WHERE id = auth.uid();

  IF _org IS DISTINCT FROM _organization_id THEN
    RETURN false;                                  -- jamais dans un autre cabinet
  END IF;

  RETURN _niveau = 1                               -- le DA : tout grade
      OR (_niveau = 2 AND _cible > 2);             -- le DM : sous son grade
END;
$function$
;

-- peut_piloter_la_tache(_user_id uuid, _task_id uuid)
CREATE OR REPLACE FUNCTION public.peut_piloter_la_tache(_user_id uuid, _task_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT EXISTS (
    SELECT 1
    FROM public.tasks t
    JOIN public.profiles pr ON pr.id = _user_id
    WHERE t.id = _task_id
      AND t.organization_id = pr.organization_id
      AND (
        (t.project_id IS NOT NULL AND public.peut_piloter_le_projet(_user_id, t.project_id))
        -- Tache sans projet : tache de cabinet, le grade decide.
        OR (t.project_id IS NULL AND COALESCE(pr.grade_level, 8) <= 3)
      )
  );
$function$
;

-- peut_piloter_le_projet(_user_id uuid, _project_id uuid)
CREATE OR REPLACE FUNCTION public.peut_piloter_le_projet(_user_id uuid, _project_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT EXISTS (
    SELECT 1
    FROM public.projects p
    JOIN public.profiles pr ON pr.id = _user_id
    WHERE p.id = _project_id
      AND p.organization_id = pr.organization_id
      AND (
        -- Projet d'une mission : la direction de cette mission pilote.
        (p.mission_id IS NOT NULL AND EXISTS (
            SELECT 1 FROM public.mission_members mm
            WHERE mm.mission_id = p.mission_id
              AND mm.user_id = _user_id
              AND public.niveau_role(mm.role) <= 3))
        -- Chef du projet designe sur la fiche.
        OR p.lead_id = _user_id
        -- Projet de cabinet, sans mission : le grade decide.
        OR (p.mission_id IS NULL AND COALESCE(pr.grade_level, 8) <= 3)
      )
  );
$function$
;

-- peut_supprimer_compte(_cible uuid)
CREATE OR REPLACE FUNCTION public.peut_supprimer_compte(_cible uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT COALESCE(public.peut_supprimer_compte_par(auth.uid(), _cible), false);
$function$
;

-- peut_supprimer_compte_par(_par uuid, _cible uuid)
CREATE OR REPLACE FUNCTION public.peut_supprimer_compte_par(_par uuid, _cible uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _a public.profiles;
  _c public.profiles;
  _rang_a integer := public.rang_plateforme(_par);
  _rang_c integer := public.rang_plateforme(_cible);
BEGIN
  IF _par IS NULL OR _cible IS NULL OR _par = _cible THEN RETURN false; END IF;

  SELECT * INTO _c FROM public.profiles WHERE id = _cible;
  IF _c.id IS NULL OR _c.supprime_le IS NOT NULL THEN RETURN false; END IF;

  -- Le compte d'un administrateur de la plateforme : seul un owner le retire.
  IF _rang_c IS NOT NULL THEN
    RETURN COALESCE(_rang_a = 1, false);
  END IF;

  -- L'administrateur de la plateforme : partout, DA compris.
  IF _rang_a IS NOT NULL THEN RETURN true; END IF;

  -- Le DA : dans son cabinet, un grade inférieur au sien.
  SELECT * INTO _a FROM public.profiles WHERE id = _par;
  RETURN COALESCE(_a.supprime_le IS NULL
                  AND _a.grade_level = 1
                  AND _a.organization_id = _c.organization_id
                  AND _c.grade_level > 1, false);
END;
$function$
;

-- peut_supprimer_document(_user_id uuid, _doc_id uuid)
CREATE OR REPLACE FUNCTION public.peut_supprimer_document(_user_id uuid, _doc_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT EXISTS (
    SELECT 1 FROM public.documents d
    JOIN public.profiles p ON p.id = _user_id
    WHERE d.id = _doc_id
      AND d.organization_id = p.organization_id
      AND (
        -- Dans une mission : la direction. HYPOTHESE, voir l'en-tete.
        (d.folder_id IS NOT NULL AND public.dirige_la_mission_du_dossier(_user_id, d.folder_id))
        OR (d.folder_id IS NULL AND d.mission_id IS NOT NULL AND EXISTS (
              SELECT 1 FROM public.mission_members mm
              WHERE mm.mission_id = d.mission_id AND mm.user_id = _user_id
                AND public.niveau_role(mm.role) <= 3))
        -- Hors mission : le grade, comme pour la lecture.
        OR (d.mission_id IS NULL AND d.folder_id IS NULL
            AND COALESCE(p.grade_level, 8) <= 3)
      )
  );
$function$
;

-- peut_voir_donnee_personnelle(_observateur uuid, _mission uuid, _personne uuid)
CREATE OR REPLACE FUNCTION public.peut_voir_donnee_personnelle(_observateur uuid, _mission uuid, _personne uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _n_obs smallint; _n_pers smallint;
BEGIN
  IF _observateur IS NULL OR _personne IS NULL THEN RETURN false; END IF;

  -- Ses propres donnees, toujours.
  IF _observateur = _personne THEN RETURN true; END IF;

  -- Hors mission : le grade decide.
  IF _mission IS NULL THEN
    RETURN public.can_see_user_info(_observateur, _personne);
  END IF;

  SELECT public.niveau_role(mm.role) INTO _n_obs
  FROM mission_members mm
  WHERE mm.mission_id = _mission AND mm.user_id = _observateur;

  SELECT public.niveau_role(mm.role) INTO _n_pers
  FROM mission_members mm
  WHERE mm.mission_id = _mission AND mm.user_id = _personne;

  -- L'un des deux n'est pas membre de cette mission : le role ne peut pas
  -- trancher, on retombe sur le grade.
  IF _n_obs IS NULL OR _n_pers IS NULL THEN
    RETURN public.can_see_user_info(_observateur, _personne);
  END IF;

  -- Strictement superieur. A role egal, les pairs ne se voient pas.
  RETURN _n_obs < _n_pers;
END; $function$
;

-- peut_voir_dossier(_user_id uuid, _folder_id uuid)
CREATE OR REPLACE FUNCTION public.peut_voir_dossier(_user_id uuid, _folder_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _mission uuid;
  _requis smallint;
  _mien smallint;
  _org uuid;
BEGIN
  IF _folder_id IS NULL THEN RETURN false; END IF;

  _mission := public.mission_du_dossier(_folder_id);

  -- Dossier hors mission (un dossier de projet, par exemple) : la regle de
  -- la mission ne s'applique pas, on retombe sur le cabinet.
  IF _mission IS NULL THEN
    SELECT f.organization_id INTO _org FROM public.document_folders f WHERE f.id = _folder_id;
    RETURN _org IS NOT NULL
       AND _org = (SELECT p.organization_id FROM public.profiles p WHERE p.id = _user_id);
  END IF;

  -- Dans une mission : il faut y etre, et au niveau de role exige.
  SELECT min(public.niveau_role(mm.role)) INTO _mien
  FROM public.mission_members mm
  WHERE mm.mission_id = _mission AND mm.user_id = _user_id;

  IF _mien IS NULL THEN RETURN false; END IF;

  _requis := public.niveau_requis_dossier(_folder_id);
  IF _requis IS NULL THEN RETURN false; END IF;

  RETURN _mien <= _requis;
END $function$
;

-- peut_voir_le_budget(_user_id uuid, _mission_id uuid)
CREATE OR REPLACE FUNCTION public.peut_voir_le_budget(_user_id uuid, _mission_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  -- Par l'appartenance a la mission, et par elle seule : l'associe de mission
  -- et le directeur de mission. Le chef de mission s'arrete ici, comme vous
  -- l'avez pose — et aucun role de cabinet ne passe par-dessus.
  SELECT EXISTS (
    SELECT 1 FROM public.mission_members mm
    WHERE mm.mission_id = _mission_id
      AND mm.user_id = _user_id
      AND public.niveau_role(mm.role) <= 2
  );
$function$
;

-- piece_rangee_dans_son_dossier()
CREATE OR REPLACE FUNCTION public.piece_rangee_dans_son_dossier()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _m uuid;
BEGIN
  IF NEW.folder_id IS NULL THEN RETURN NEW; END IF;
  _m := public.mission_du_dossier(NEW.folder_id);
  IF _m IS NULL THEN RETURN NEW; END IF;
  IF NEW.mission_id IS NULL THEN
    -- On rattache la piece a la mission de son dossier, plutot que de refuser.
    NEW.mission_id := _m;
  ELSIF NEW.mission_id <> _m THEN
    RAISE EXCEPTION 'Ce dossier appartient a une autre mission : une piece ne peut pas etre rangee ailleurs que dans les dossiers de sa mission.';
  END IF;
  RETURN NEW;
END $function$
;

-- portal_accept_invitation(_token text, _auth_user_id uuid)
CREATE OR REPLACE FUNCTION public.portal_accept_invitation(_token text, _auth_user_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _inv RECORD;
BEGIN
  SELECT * INTO _inv FROM portal_invitations
  WHERE token = _token AND status = 'pending' AND expires_at > now()
  FOR UPDATE;

  IF _inv IS NULL THEN
    RAISE EXCEPTION 'Invitation invalide ou expirée';
  END IF;

  -- Étanchéité : refuser si ce compte est un membre du cabinet
  IF EXISTS (SELECT 1 FROM profiles p WHERE p.id = _auth_user_id) THEN
    RAISE EXCEPTION 'Ce compte est un membre du cabinet';
  END IF;

  INSERT INTO portal_users
    (id, client_id, organization_id, email, full_name, invited_by, invited_at, activated_at)
  VALUES (_auth_user_id, _inv.client_id, _inv.organization_id, _inv.email,
          _inv.full_name, _inv.invited_by, _inv.invited_at, now());

  UPDATE portal_invitations
     SET status = 'accepted', accepted_at = now()
   WHERE id = _inv.id;

  -- Traçabilité
  INSERT INTO portal_access_log
    (portal_user_id, client_id, organization_id, action, entity_type, entity_id)
  VALUES (_auth_user_id, _inv.client_id, _inv.organization_id,
          'account_activated', 'portal_invitation', _inv.id);

  -- Prévenir le cabinet
  INSERT INTO notifications (user_id, type, title, content, entity_type, entity_id, priority)
  SELECT _inv.invited_by, 'portal_activated', 'Accès client activé',
    COALESCE(_inv.full_name, _inv.email) || ' a activé son accès à l''espace client.',
    'client', _inv.client_id, 'normal'
  WHERE _inv.invited_by IS NOT NULL;

  RETURN jsonb_build_object('success', true, 'client_id', _inv.client_id);
END;
$function$
;

-- portal_dashboard()
CREATE OR REPLACE FUNCTION public.portal_dashboard()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _client uuid;
  _client_name text;
  _org_name text;
  _org_logo text;
BEGIN
  _client := public.current_portal_client();
  IF _client IS NULL THEN
    RAISE EXCEPTION 'Réservé aux comptes clients';
  END IF;

  SELECT c.name INTO _client_name FROM clients c WHERE c.id = _client;
  SELECT o.name, o.logo_url INTO _org_name, _org_logo
  FROM organizations o
  JOIN portal_users pu ON pu.organization_id = o.id
  WHERE pu.id = auth.uid();

  RETURN jsonb_build_object(
    'client_name', _client_name,
    'organization_name', _org_name,
    'organization_logo', _org_logo,
    'pending_documents', (
      SELECT COUNT(*)
      FROM obligation_documents od
      JOIN obligation_periods op ON op.id = od.obligation_period_id
      WHERE op.client_id = _client
        AND od.status IN ('attendue','rejetee')
        AND op.status NOT IN ('depose','na')
    ),
    'next_deadline', (
      SELECT jsonb_build_object(
        'obligation', ot.label,
        'period_label', op.period_label,
        'due_date', op.due_date,
        'days_left', (op.due_date - CURRENT_DATE)
      )
      FROM obligation_periods op
      JOIN obligation_types ot ON ot.id = op.obligation_type_id
      WHERE op.client_id = _client AND op.status NOT IN ('depose','na')
        AND op.due_date >= CURRENT_DATE
      ORDER BY op.due_date LIMIT 1
    ),
    'new_documents', (
      SELECT COUNT(*) FROM portal_documents pd
      WHERE pd.client_id = _client AND pd.direction = 'to_client'
        AND pd.is_available AND pd.first_downloaded_at IS NULL
    ),
    'unpaid_invoices', (
      SELECT COUNT(*) FROM invoices i
      WHERE i.client_id = _client AND i.status NOT IN ('paid','draft')
    ),
    'next_meeting', (
      SELECT jsonb_build_object(
        'title', m.title, 'scheduled_at', m.scheduled_at, 'meeting_link', m.meeting_link
      )
      FROM meetings m
      JOIN missions mi ON mi.id = m.mission_id
      WHERE mi.client_id = _client AND m.shared_with_client
        AND m.scheduled_at >= now()
      ORDER BY m.scheduled_at LIMIT 1
    )
  );
END;
$function$
;

-- portal_deposit_document(_obligation_document_id uuid, _file_path text, _file_name text)
CREATE OR REPLACE FUNCTION public.portal_deposit_document(_obligation_document_id uuid, _file_path text, _file_name text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _client uuid;
  _period_client uuid;
  _org uuid;
BEGIN
  _client := public.current_portal_client();
  IF _client IS NULL THEN
    RAISE EXCEPTION 'Réservé aux comptes clients';
  END IF;

  SELECT op.client_id, op.organization_id INTO _period_client, _org
  FROM obligation_documents od
  JOIN obligation_periods op ON op.id = od.obligation_period_id
  WHERE od.id = _obligation_document_id;

  IF _period_client IS DISTINCT FROM _client THEN
    RAISE EXCEPTION 'Cette pièce ne correspond pas à votre dossier';
  END IF;

  UPDATE obligation_documents
     SET status = 'deposee',
         source = 'portail',
         file_path = _file_path,
         file_name = _file_name,
         deposited_at = now(),
         deposited_by_contact = (SELECT pu.email FROM portal_users pu WHERE pu.id = auth.uid()),
         reject_reason = NULL
   WHERE id = _obligation_document_id;

  INSERT INTO portal_access_log
    (portal_user_id, client_id, organization_id, action, entity_type, entity_id, details)
  VALUES (auth.uid(), _client, _org, 'obligation_document_deposited',
          'obligation_document', _obligation_document_id,
          jsonb_build_object('file_name', _file_name));

  RETURN jsonb_build_object('success', true);
END;
$function$
;

-- portal_mark_downloaded(_document_id uuid)
CREATE OR REPLACE FUNCTION public.portal_mark_downloaded(_document_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _doc RECORD;
  _client uuid;
BEGIN
  _client := public.current_portal_client();
  IF _client IS NULL THEN
    RAISE EXCEPTION 'Réservé aux comptes clients';
  END IF;

  SELECT * INTO _doc FROM portal_documents
  WHERE id = _document_id AND client_id = _client AND is_available;

  IF _doc IS NULL THEN
    RAISE EXCEPTION 'Document introuvable';
  END IF;

  UPDATE portal_documents
     SET download_count = COALESCE(download_count, 0) + 1,
         first_downloaded_at = COALESCE(first_downloaded_at, now())
   WHERE id = _document_id;

  INSERT INTO portal_access_log
    (portal_user_id, client_id, organization_id, action, entity_type, entity_id, details)
  VALUES (auth.uid(), _client, _doc.organization_id, 'document_downloaded',
          'portal_document', _document_id, jsonb_build_object('title', _doc.title));

  RETURN jsonb_build_object('success', true);
END;
$function$
;

-- portal_my_documents()
CREATE OR REPLACE FUNCTION public.portal_my_documents()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _client uuid;
BEGIN
  _client := public.current_portal_client();
  IF _client IS NULL THEN
    RAISE EXCEPTION 'Réservé aux comptes clients';
  END IF;

  RETURN jsonb_build_object(
    'received', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
        'id', pd.id, 'title', pd.title, 'description', pd.description,
        'category', pd.category, 'file_name', pd.file_name,
        'file_size', pd.file_size, 'uploaded_at', pd.uploaded_at,
        'first_downloaded_at', pd.first_downloaded_at
      ) ORDER BY pd.uploaded_at DESC)
      FROM portal_documents pd
      WHERE pd.client_id = _client AND pd.direction = 'to_client' AND pd.is_available
    ), '[]'::jsonb),
    'sent', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
        'id', pd.id, 'title', pd.title, 'category', pd.category,
        'file_name', pd.file_name, 'uploaded_at', pd.uploaded_at
      ) ORDER BY pd.uploaded_at DESC)
      FROM portal_documents pd
      WHERE pd.client_id = _client AND pd.direction = 'from_client'
    ), '[]'::jsonb)
  );
END;
$function$
;

-- portal_my_invoices()
CREATE OR REPLACE FUNCTION public.portal_my_invoices()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _client uuid;
BEGIN
  _client := public.current_portal_client();
  IF _client IS NULL THEN
    RAISE EXCEPTION 'Réservé aux comptes clients';
  END IF;

  RETURN jsonb_build_object(
    'invoices', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
        'id', i.id,
        'invoice_number', i.invoice_number,
        'type', i.type,
        'amount', i.amount,
        'tax_amount', i.tax_amount,
        'total_amount', i.total_amount,
        'currency', i.currency,
        'status', i.status,
        'due_date', i.due_date,
        'paid_at', i.paid_at,
        'line_items', i.line_items,
        'created_at', i.created_at,
        'is_overdue', (i.due_date < CURRENT_DATE AND i.status <> 'paid')
        -- i.notes VOLONTAIREMENT EXCLU : champ de travail interne
      ) ORDER BY i.created_at DESC)
      FROM invoices i
      WHERE i.client_id = _client
        AND i.status <> 'draft'    -- une facture en brouillon n'est pas émise
    ), '[]'::jsonb),
    'summary', (
      SELECT jsonb_build_object(
        'total_due', COALESCE(SUM(i.total_amount) FILTER (WHERE i.status <> 'paid'), 0),
        'overdue_count', COUNT(*) FILTER (WHERE i.due_date < CURRENT_DATE AND i.status <> 'paid')
      )
      FROM invoices i WHERE i.client_id = _client AND i.status <> 'draft'
    )
  );
END;
$function$
;

-- portal_my_meetings()
CREATE OR REPLACE FUNCTION public.portal_my_meetings()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _client uuid;
BEGIN
  _client := public.current_portal_client();
  IF _client IS NULL THEN
    RAISE EXCEPTION 'Réservé aux comptes clients';
  END IF;

  RETURN COALESCE((
    SELECT jsonb_agg(jsonb_build_object(
      'id', m.id,
      'title', m.title,
      'description', m.description,
      'scheduled_at', m.scheduled_at,
      'duration_minutes', m.duration_minutes,
      'meeting_link', m.meeting_link,
      'type', m.type,
      'status', m.status,
      'client_summary', m.client_summary,
      'is_past', (m.scheduled_at < now())
      -- m.summary et m.recording_url VOLONTAIREMENT EXCLUS
    ) ORDER BY m.scheduled_at DESC)
    FROM meetings m
    JOIN missions mi ON mi.id = m.mission_id
    WHERE mi.client_id = _client
      AND m.shared_with_client = true
  ), '[]'::jsonb);
END;
$function$
;

-- portal_my_obligations()
CREATE OR REPLACE FUNCTION public.portal_my_obligations()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _client uuid;
BEGIN
  _client := public.current_portal_client();
  IF _client IS NULL THEN
    RAISE EXCEPTION 'Réservé aux comptes clients';
  END IF;

  RETURN jsonb_build_object(
    'upcoming', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
        'id', op.id,
        'obligation', ot.label,
        'category', ot.category,
        'period_label', op.period_label,
        'due_date', op.due_date,
        'days_left', (op.due_date - CURRENT_DATE),
        'is_late', (op.due_date < CURRENT_DATE AND op.status NOT IN ('depose','na')),
        -- Statut simplifié : le client n'a pas à connaître nos étapes internes
        'client_status', CASE
          WHEN op.status IN ('a_faire','pieces_attendues') THEN 'pieces_a_fournir'
          WHEN op.status IN ('pieces_recues','saisie','revision','pret') THEN 'en_cours'
          WHEN op.status = 'depose' THEN 'depose'
          ELSE 'na' END,
        'documents_pending', (
          SELECT COUNT(*) FROM obligation_documents od
          WHERE od.obligation_period_id = op.id
            AND od.status IN ('attendue','rejetee')
        )
      ) ORDER BY op.due_date)
      FROM obligation_periods op
      JOIN obligation_types ot ON ot.id = op.obligation_type_id
      WHERE op.client_id = _client
        AND op.status <> 'na'
        AND op.due_date >= CURRENT_DATE - INTERVAL '60 days'
    ), '[]'::jsonb),
    'completed_count', (
      SELECT COUNT(*) FROM obligation_periods op
      WHERE op.client_id = _client AND op.status = 'depose'
    )
  );
END;
$function$
;

-- portal_obligation_documents(_period_id uuid)
CREATE OR REPLACE FUNCTION public.portal_obligation_documents(_period_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _client uuid;
  _period_client uuid;
BEGIN
  _client := public.current_portal_client();
  IF _client IS NULL THEN
    RAISE EXCEPTION 'Réservé aux comptes clients';
  END IF;

  SELECT op.client_id INTO _period_client
  FROM obligation_periods op WHERE op.id = _period_id;

  IF _period_client IS DISTINCT FROM _client THEN
    RAISE EXCEPTION 'Échéance introuvable';
  END IF;

  RETURN COALESCE((
    SELECT jsonb_agg(jsonb_build_object(
      'id', od.id,
      'label', od.label,
      'is_required', od.is_required,
      -- Statut simplifié côté client
      'client_status', CASE
        WHEN od.status = 'attendue' THEN 'a_fournir'
        WHEN od.status = 'deposee'  THEN 'en_verification'
        WHEN od.status = 'recue'    THEN 'valide'
        WHEN od.status = 'rejetee'  THEN 'a_renvoyer'
        ELSE 'non_applicable' END,
      'reject_reason', od.reject_reason,
      'file_name', od.file_name,
      'deposited_at', od.deposited_at
    ) ORDER BY od.is_required DESC, od.label)
    FROM obligation_documents od
    WHERE od.obligation_period_id = _period_id
      AND od.status <> 'non_applicable'
  ), '[]'::jsonb);
END;
$function$
;

-- portal_toggle_access(_portal_user_id uuid, _activate boolean, _reason text)
CREATE OR REPLACE FUNCTION public.portal_toggle_access(_portal_user_id uuid, _activate boolean, _reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _org uuid;
  _grade integer;
  _pu RECORD;
BEGIN
  SELECT p.organization_id, p.grade_level INTO _org, _grade
  FROM profiles p WHERE p.id = auth.uid();

  IF _grade IS NULL OR _grade > 3 THEN
    RAISE EXCEPTION 'Accès refusé : action réservée aux responsables';
  END IF;

  SELECT * INTO _pu FROM portal_users WHERE id = _portal_user_id;
  IF _pu IS NULL THEN RAISE EXCEPTION 'Compte client introuvable'; END IF;
  IF _pu.organization_id <> _org THEN
    RAISE EXCEPTION 'Ce compte n''appartient pas à votre organisation';
  END IF;

  IF NOT _activate AND (_reason IS NULL OR length(trim(_reason)) < 5) THEN
    RAISE EXCEPTION 'Le motif de révocation est obligatoire';
  END IF;

  UPDATE portal_users SET is_active = _activate, updated_at = now()
   WHERE id = _portal_user_id;

  INSERT INTO portal_access_log
    (portal_user_id, client_id, organization_id, action, details)
  VALUES (_portal_user_id, _pu.client_id, _org,
          CASE WHEN _activate THEN 'access_restored' ELSE 'access_revoked' END,
          jsonb_build_object('reason', _reason, 'by', auth.uid()));

  RETURN jsonb_build_object('success', true, 'is_active', _activate);
END;
$function$
;

-- portal_validate_invitation(_token text)
CREATE OR REPLACE FUNCTION public.portal_validate_invitation(_token text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _inv RECORD;
  _client_name text;
  _org_name text;
BEGIN
  SELECT * INTO _inv FROM portal_invitations WHERE token = _token;

  IF _inv IS NULL THEN
    RETURN jsonb_build_object('valid', false, 'reason', 'Lien d''invitation invalide');
  END IF;
  IF _inv.status = 'accepted' THEN
    RETURN jsonb_build_object('valid', false, 'reason', 'Cette invitation a déjà été utilisée');
  END IF;
  IF _inv.status = 'revoked' THEN
    RETURN jsonb_build_object('valid', false, 'reason', 'Cette invitation a été annulée');
  END IF;
  IF _inv.expires_at < now() THEN
    RETURN jsonb_build_object('valid', false, 'reason', 'Ce lien d''invitation a expiré');
  END IF;

  SELECT c.name INTO _client_name FROM clients c WHERE c.id = _inv.client_id;
  SELECT o.name INTO _org_name FROM organizations o WHERE o.id = _inv.organization_id;

  RETURN jsonb_build_object(
    'valid', true,
    'invitation_id', _inv.id,
    'client_id', _inv.client_id,
    'organization_id', _inv.organization_id,
    'email', _inv.email,
    'full_name', _inv.full_name,
    'client_name', _client_name,
    'organization_name', _org_name
  );
END;
$function$
;

-- portal_withdraw_document(_document_id uuid, _restore boolean)
CREATE OR REPLACE FUNCTION public.portal_withdraw_document(_document_id uuid, _restore boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _org uuid;
  _grade integer;
  _doc RECORD;
BEGIN
  SELECT p.organization_id, p.grade_level INTO _org, _grade
  FROM profiles p WHERE p.id = auth.uid();

  IF _grade IS NULL OR _grade > 3 THEN
    RAISE EXCEPTION 'Accès refusé : action réservée aux responsables';
  END IF;

  SELECT * INTO _doc FROM portal_documents WHERE id = _document_id;
  IF _doc IS NULL OR _doc.organization_id <> _org THEN
    RAISE EXCEPTION 'Document introuvable';
  END IF;
  IF _doc.direction <> 'to_client' THEN
    RAISE EXCEPTION 'Seuls les documents partagés par le cabinet peuvent être retirés';
  END IF;

  UPDATE portal_documents
     SET is_available = _restore,
         withdrawn_at = CASE WHEN _restore THEN NULL ELSE now() END,
         withdrawn_by = CASE WHEN _restore THEN NULL ELSE auth.uid() END,
         updated_at = now()
   WHERE id = _document_id;

  RETURN jsonb_build_object('success', true, 'is_available', _restore);
END;
$function$
;

-- prepare_mission_before_insert()
CREATE OR REPLACE FUNCTION public.prepare_mission_before_insert()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _user_id uuid := auth.uid();
  _org_id uuid;
  _year text := to_char(now(), 'YYYY');
BEGIN
  IF _user_id IS NULL THEN
    RETURN NEW;
  END IF;

  SELECT p.organization_id
    INTO _org_id
  FROM public.profiles p
  WHERE p.id = _user_id;

  IF NEW.organization_id IS NULL THEN
    NEW.organization_id := _org_id;
  END IF;

  IF NEW.priority = 'urgent' THEN
    NEW.priority := 'critical';
  END IF;

  IF NEW.priority IS NULL OR NEW.priority NOT IN ('low', 'medium', 'high', 'critical') THEN
    NEW.priority := 'medium';
  END IF;

  IF NEW.budget_currency IS NULL OR NEW.budget_currency NOT IN ('XOF', 'XAF', 'EUR', 'USD') THEN
    NEW.budget_currency := 'XOF';
  END IF;

  IF NEW.status IS NULL OR NEW.status NOT IN ('draft', 'planning', 'active', 'on_hold', 'completed', 'archived', 'cancelled') THEN
    NEW.status := 'draft';
  END IF;

  IF NEW.code IS NULL OR trim(NEW.code) = '' THEN
    SELECT 'MIS-' || _year || '-' || lpad((COUNT(*) + 1)::text, 3, '0')
      INTO NEW.code
    FROM public.missions m
    WHERE m.organization_id = NEW.organization_id
      AND m.code LIKE 'MIS-' || _year || '-%';
  END IF;

  RETURN NEW;
END;
$function$
;

-- prepare_project_before_insert()
CREATE OR REPLACE FUNCTION public.prepare_project_before_insert()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _user_id uuid := auth.uid();
  _org_id uuid;
  _mission_org_id uuid;
  _year text := to_char(now(), 'YYYY');
BEGIN
  IF _user_id IS NOT NULL THEN
    SELECT p.organization_id INTO _org_id
    FROM public.profiles p
    WHERE p.id = _user_id;
  END IF;

  IF NEW.mission_id IS NOT NULL THEN
    SELECT m.organization_id INTO _mission_org_id
    FROM public.missions m
    WHERE m.id = NEW.mission_id;
  END IF;

  IF NEW.organization_id IS NULL THEN
    NEW.organization_id := COALESCE(_mission_org_id, _org_id);
  END IF;

  IF NEW.status IS NULL OR NEW.status NOT IN ('planning', 'active', 'on_hold', 'review', 'completed', 'archived') THEN
    NEW.status := 'planning';
  END IF;

  IF NEW.budget_allocated IS NULL THEN
    NEW.budget_allocated := 0;
  END IF;

  IF NEW.code IS NULL OR trim(NEW.code) = '' THEN
    SELECT 'PRJ-' || _year || '-' || lpad((COUNT(*) + 1)::text, 3, '0')
      INTO NEW.code
    FROM public.projects p
    WHERE p.mission_id = NEW.mission_id
      AND p.code LIKE 'PRJ-' || _year || '-%';
  END IF;

  RETURN NEW;
END;
$function$
;

