-- profile_grade_at(_user_id uuid, _date date)
CREATE OR REPLACE FUNCTION public.profile_grade_at(_user_id uuid, _date date)
 RETURNS TABLE(grade text, grade_echelon text, rank smallint, exercice smallint, source text)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  -- L'historique d'abord : la derniere ligne prenant effet avant la date.
  -- decided_at departage deux changements portant la meme date d'effet.
  RETURN QUERY
  SELECT h.grade, h.grade_echelon, h.rank, h.exercice, 'historique'::text
  FROM grade_history h
  WHERE h.user_id = _user_id AND h.effective_from <= _date
  ORDER BY h.effective_from DESC, h.decided_at DESC
  LIMIT 1;
  IF FOUND THEN RETURN; END IF;

  -- Date anterieure a tout l'historique. Le plus ancien etat CONNU vaut
  -- infiniment mieux que la fiche d'aujourd'hui : interroger 2025 et recevoir
  -- le grade de 2026 est exactement l'erreur que cet historique evite.
  RETURN QUERY
  SELECT h.grade, h.grade_echelon, h.rank, h.exercice,
         'plus ancien etat connu, du ' || h.effective_from::text
           || ' (anterieur a l''historique)'
  FROM grade_history h
  WHERE h.user_id = _user_id
  ORDER BY h.effective_from, h.decided_at
  LIMIT 1;
  IF FOUND THEN RETURN; END IF;

  -- Aucun historique du tout : la fiche courante, dite comme telle.
  RETURN QUERY
  SELECT p.grade, p.grade_echelon, public.profile_rank(p.id),
         public.fiscal_exercice(_date, p.organization_id),
         'fiche courante (aucun historique)'::text
  FROM profiles p WHERE p.id = _user_id;
END; $function$
;

-- profile_rank(_user_id uuid)
CREATE OR REPLACE FUNCTION public.profile_rank(_user_id uuid)
 RETURNS smallint
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _p RECORD; _rank smallint;
BEGIN
  SELECT organization_id, practice, grade_echelon, grade
    INTO _p FROM profiles WHERE id = _user_id;
  IF _p IS NULL THEN RETURN NULL; END IF;

  -- Par l'échelon, qui est l'information la plus précise.
  SELECT g.rank INTO _rank
  FROM evaluation_grades g
  WHERE g.organization_id = _p.organization_id
    AND g.practice = _p.practice
    AND lower(btrim(g.echelon)) = lower(btrim(COALESCE(_p.grade_echelon, '')))
  LIMIT 1;
  IF _rank IS NOT NULL THEN RETURN _rank; END IF;

  -- À défaut d'échelon exploitable, le bas du grade DANS SA PRACTICE : un
  -- profil incomplet n'ouvre jamais plus de droits qu'il n'en a, et son rang
  -- ne vient pas de l'échelle d'un autre métier.
  SELECT min(g.rank) INTO _rank
  FROM evaluation_grades g
  WHERE g.organization_id = _p.organization_id
    AND g.practice = _p.practice
    AND g.maps_to_grade = _p.grade;
  RETURN _rank;
END $function$
;

-- profile_rank_at(_user_id uuid, _date date)
CREATE OR REPLACE FUNCTION public.profile_rank_at(_user_id uuid, _date date)
 RETURNS smallint
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT rank FROM public.profile_grade_at(_user_id, _date);
$function$
;

-- promouvoir_collaborateur(_user_id uuid, _grade_echelon text, _effective_from date, _motif text)
CREATE OR REPLACE FUNCTION public.promouvoir_collaborateur(_user_id uuid, _grade_echelon text, _effective_from date DEFAULT CURRENT_DATE, _motif text DEFAULT NULL::text)
 RETURNS TABLE(collaborateur text, echelon_avant text, rang_avant smallint, echelon_apres text, rang_apres smallint, exercice text, sens text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _moi uuid := auth.uid();
  _p RECORD; _g RECORD; _av RECORD; _ex smallint;
BEGIN
  IF _moi IS NULL THEN
    RAISE EXCEPTION 'Authentification requise';
  END IF;

  SELECT id, organization_id, practice, full_name, grade, grade_echelon
    INTO _p FROM profiles WHERE id = _user_id;
  IF _p.id IS NULL THEN
    RAISE EXCEPTION 'Collaborateur introuvable';
  END IF;

  -- Seul un associe promeut, et seulement dans son cabinet.
  IF NOT EXISTS (
    SELECT 1 FROM profiles me
    WHERE me.id = _moi
      AND me.organization_id = _p.organization_id
      AND COALESCE(public.profile_rank(me.id), 0) >= 16
  ) THEN
    RAISE EXCEPTION
      'Seul un Directeur Associe de ce cabinet peut promouvoir un collaborateur';
  END IF;

  IF _p.practice IS NULL THEN
    RAISE EXCEPTION
      'La practice de ce collaborateur n''est pas renseignee : impossible de situer son echelon';
  END IF;

  -- L'echelon est la seule donnee demandee ; le grade et le rang en decoulent.
  -- C'est ce qui rend l'incoherence grade/echelon impossible.
  SELECT g.maps_to_grade AS grade, g.echelon, g.rank
    INTO _g
  FROM evaluation_grades g
  WHERE g.organization_id = _p.organization_id
    AND g.practice = _p.practice
    AND lower(btrim(g.echelon)) = lower(btrim(_grade_echelon))
  LIMIT 1;

  IF _g.echelon IS NULL THEN
    RAISE EXCEPTION
      'L''echelon « % » n''existe pas dans l''echelle % de ce cabinet. Consultez la grille avant de promouvoir.',
      _grade_echelon, _p.practice;
  END IF;

  -- L'etat au moment ou la promotion prend effet.
  SELECT * INTO _av FROM public.profile_grade_at(_user_id, _effective_from);

  IF _av.grade_echelon IS NOT NULL
     AND lower(btrim(_av.grade_echelon)) = lower(btrim(_g.echelon)) THEN
    RAISE EXCEPTION
      'Ce collaborateur est deja « % » a cette date : rien a changer.', _g.echelon;
  END IF;

  -- Une promotion ne peut pas prendre effet avant que le systeme ait trace du
  -- collaborateur : la ligne de reprise serait alors posterieure et dirait le
  -- contraire. La chronologie doit rester lisible.
  IF EXISTS (
    SELECT 1 FROM grade_history h
    WHERE h.user_id = _user_id AND h.origine = 'reprise'
      AND h.effective_from > _effective_from
  ) THEN
    RAISE EXCEPTION
      'Date d''effet trop ancienne : l''historique de ce collaborateur commence le %. Choisissez une date a partir de ce jour.',
      (SELECT min(h.effective_from) FROM grade_history h
        WHERE h.user_id = _user_id AND h.origine = 'reprise');
  END IF;

  _ex := public.fiscal_exercice(_effective_from, _p.organization_id);

  INSERT INTO grade_history (organization_id, user_id, practice, grade,
                             grade_echelon, rank, effective_from, exercice,
                             motif, decided_by, origine)
  VALUES (_p.organization_id, _user_id, _p.practice, _g.grade,
          _g.echelon, _g.rank, _effective_from, _ex,
          _motif, _moi, 'promotion');

  -- La fiche ne suit que si la promotion est deja effective.
  IF _effective_from <= CURRENT_DATE THEN
    UPDATE profiles
       SET grade = _g.grade, grade_echelon = _g.echelon
     WHERE id = _user_id;
  END IF;

  RETURN QUERY SELECT
    _p.full_name::text,
    _av.grade_echelon, _av.rank,
    _g.echelon::text, _g.rank,
    public.exercice_label(_ex, _p.organization_id),
    CASE WHEN _av.rank IS NULL           THEN 'premiere affectation de grade'
         WHEN _g.rank > _av.rank         THEN 'promotion'
         WHEN _g.rank < _av.rank         THEN 'RETROGRADATION'
         ELSE 'changement a rang egal' END;
END; $function$
;

-- protect_evaluation_fields()
CREATE OR REPLACE FUNCTION public.protect_evaluation_fields()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  -- Le collaborateur évalué ne touche ni à sa note, ni au commentaire
  -- de son évaluateur, ni à la validation. Les RPC du circuit ne
  -- modifient aucun de ces champs lorsqu'il en est l'auteur, donc une
  -- divergence ici est une écriture illégitime : on la refuse plutôt
  -- que de la neutraliser en silence, pour que la tentative laisse
  -- une trace et que le client ne croie pas avoir écrit.
  IF auth.uid() = OLD.evaluatee_id AND auth.uid() <> OLD.evaluator_id THEN
    IF NEW.weighted_score     IS DISTINCT FROM OLD.weighted_score
    OR NEW.appreciation       IS DISTINCT FROM OLD.appreciation
    OR NEW.appreciation_label IS DISTINCT FROM OLD.appreciation_label
    OR NEW.evaluator_comment  IS DISTINCT FROM OLD.evaluator_comment
    OR NEW.evaluator_id       IS DISTINCT FROM OLD.evaluator_id
    OR NEW.evaluatee_id       IS DISTINCT FROM OLD.evaluatee_id
    OR NEW.template_id        IS DISTINCT FROM OLD.template_id
    OR NEW.validated_at       IS DISTINCT FROM OLD.validated_at
    OR NEW.validated_by       IS DISTINCT FROM OLD.validated_by
    OR NEW.round_count        IS DISTINCT FROM OLD.round_count
    THEN
      RAISE EXCEPTION 'La notation et sa validation relèvent de votre évaluateur. Formulez vos observations.';
    END IF;

    IF NEW.status IS DISTINCT FROM OLD.status
       AND NEW.status NOT IN ('envoyee', 'observations_recues') THEN
      RAISE EXCEPTION 'Vous ne pouvez pas faire évoluer l''évaluation vers cet état.';
    END IF;
  END IF;

  NEW.updated_at := now();
  RETURN NEW;
END; $function$
;

-- protect_plan_status()
CREATE OR REPLACE FUNCTION public.protect_plan_status()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _grade integer;
BEGIN
  IF auth.uid() = OLD.user_id THEN
    SELECT p.grade_level INTO _grade FROM profiles p WHERE p.id = auth.uid();

    -- Sur SA propre ligne, personne ne pose approved/rejected
    IF NEW.status IN ('approved', 'rejected')
       AND OLD.status IS DISTINCT FROM NEW.status THEN
      RAISE EXCEPTION 'Vous ne pouvez pas valider votre propre planning';
    END IF;

    -- Les champs de revue restent la main du responsable
    NEW.reviewer_id     := OLD.reviewer_id;
    NEW.reviewed_at     := OLD.reviewed_at;
    NEW.review_comment  := OLD.review_comment;
  ELSE
    -- Responsable : horodatage automatique de la décision
    IF NEW.status IN ('approved', 'rejected')
       AND OLD.status IS DISTINCT FROM NEW.status THEN
      NEW.reviewer_id := auth.uid();
      NEW.reviewed_at := now();
    END IF;
  END IF;

  NEW.updated_at := now();
  RETURN NEW;
END; $function$
;

-- protect_staffing_fields()
CREATE OR REPLACE FUNCTION public.protect_staffing_fields()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _grade integer;
  _is_assignee boolean;
BEGIN
  SELECT p.grade_level INTO _grade FROM profiles p WHERE p.id = auth.uid();

  -- L'utilisateur agit en tant qu'affecté s'il est le destinataire
  -- ET n'est pas celui qui a créé l'affectation.
  _is_assignee := (auth.uid() = OLD.user_id AND auth.uid() IS DISTINCT FROM OLD.assigned_by);

  IF _is_assignee THEN
    -- Champs verrouillés : seul le responsable les décide
    NEW.mission_id   := OLD.mission_id;
    NEW.project_id   := OLD.project_id;
    NEW.user_id      := OLD.user_id;
    NEW.role         := OLD.role;
    NEW.start_date   := OLD.start_date;
    NEW.end_date     := OLD.end_date;
    NEW.weekly_hours := OLD.weekly_hours;
    NEW.assigned_by  := OLD.assigned_by;
    NEW.chef_response := OLD.chef_response;
    NEW.responded_at  := OLD.responded_at;
    NEW.responded_by  := OLD.responded_by;
    NEW.revision_count := OLD.revision_count;

    -- Transitions autorisées pour l'affecté
    NEW.status := OLD.status;   -- l'affecte ne decide pas de son affectation

  ELSE
    -- Responsable : horodatage automatique de sa réponse
    IF NEW.chef_response IS DISTINCT FROM OLD.chef_response
       AND NEW.chef_response IS NOT NULL THEN
      NEW.responded_at := now();
      NEW.responded_by := auth.uid();
    END IF;

    -- Repasser en 'proposed' après arbitrage = un aller-retour de plus
    IF false /* arbitrage supprime le 2 novembre 2026 */ THEN
      NEW.revision_count := COALESCE(OLD.revision_count, 0) + 1;
    END IF;
  END IF;

  NEW.updated_at := now();
  RETURN NEW;
END;
$function$
;

-- protect_time_entry_status()
CREATE OR REPLACE FUNCTION public.protect_time_entry_status()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF auth.uid() = OLD.user_id THEN
    -- Sur sa propre saisie : personne ne pose approved/rejected
    IF NEW.status IN ('approved', 'rejected')
       AND OLD.status IS DISTINCT FROM NEW.status THEN
      RAISE EXCEPTION 'Vous ne pouvez pas valider votre propre feuille de temps';
    END IF;
    -- Les champs de revue restent la main du responsable
    NEW.reviewer_id     := OLD.reviewer_id;
    NEW.reviewed_at     := OLD.reviewed_at;
    NEW.review_comment  := OLD.review_comment;
  ELSE
    -- Responsable : horodatage automatique de la décision
    IF NEW.status IN ('approved', 'rejected')
       AND OLD.status IS DISTINCT FROM NEW.status THEN
      NEW.reviewer_id := auth.uid();
      NEW.reviewed_at := now();
    END IF;
    -- Un rejet doit être motivé
    IF NEW.status = 'rejected'
       AND (NEW.review_comment IS NULL OR length(trim(NEW.review_comment)) < 5) THEN
      RAISE EXCEPTION 'Un rejet doit être motivé';
    END IF;
  END IF;

  NEW.updated_at := now();
  RETURN NEW;
END; $function$
;

-- purge_old_activity_data()
CREATE OR REPLACE FUNCTION public.purge_old_activity_data()
 RETURNS void
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  DELETE FROM activity_reports WHERE report_date < (CURRENT_DATE - INTERVAL '90 days');
  DELETE FROM activity_sessions WHERE started_at < (now() - INTERVAL '90 days');
$function$
;

-- purge_old_attendance()
CREATE OR REPLACE FUNCTION public.purge_old_attendance()
 RETURNS void
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  DELETE FROM public.attendance_events WHERE event_date < CURRENT_DATE - INTERVAL '2 years';
$function$
;

-- purger_fiches_sans_cabinet()
CREATE OR REPLACE FUNCTION public.purger_fiches_sans_cabinet()
 RETURNS TABLE(email text, nom text, action_ text, raison text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _p RECORD; _fk RECORD; _n bigint; _d bigint;
BEGIN
  FOR _p IN
    SELECT pr.id, pr.email AS mail, pr.full_name
    FROM profiles pr WHERE pr.organization_id IS NULL ORDER BY pr.email
  LOOP
    _d := 0;
    FOR _fk IN
      SELECT c.conrelid::regclass::text AS tbl, a.attname AS col
      FROM pg_constraint c
      JOIN unnest(c.conkey) WITH ORDINALITY AS k(attnum, ord) ON true
      JOIN pg_attribute a ON a.attrelid = c.conrelid AND a.attnum = k.attnum
      WHERE c.contype = 'f'
        AND c.confrelid IN ('public.profiles'::regclass, 'auth.users'::regclass)
    LOOP
      CONTINUE WHEN public.est_plomberie_de_compte(_fk.tbl);
      EXECUTE format('SELECT count(*) FROM %s WHERE %I = $1', _fk.tbl, _fk.col)
        INTO _n USING _p.id;
      _d := _d + _n;
    END LOOP;

    IF _d > 0 THEN
      RETURN QUERY SELECT _p.mail::text, _p.full_name::text,
        'gardee'::text, format('%s donnee(s) de travail', _d)::text;
      CONTINUE;
    END IF;

    -- Le compte entier, cascade comprise.
    BEGIN
      DELETE FROM auth.users WHERE id = _p.id;
      RETURN QUERY SELECT _p.mail::text, _p.full_name::text,
        'SUPPRIMEE'::text, 'compte et fiche supprimes (cascade)'::text;
    EXCEPTION WHEN insufficient_privilege OR undefined_table THEN
      -- Pas le droit d'ecrire dans auth : on retire ce qu'on peut.
      DELETE FROM public.user_roles WHERE user_id = _p.id;
      DELETE FROM public.profiles   WHERE id = _p.id;
      RETURN QUERY SELECT _p.mail::text, _p.full_name::text,
        'FICHE SUPPRIMEE'::text,
        'compte auth conserve (droits insuffisants) : supprimez-le depuis Authentication > Users'::text;
    END;
  END LOOP;
END; $function$
;

-- rang_plateforme(_user uuid)
CREATE OR REPLACE FUNCTION public.rang_plateforme(_user uuid)
 RETURNS integer
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT CASE role WHEN 'owner' THEN 1 WHEN 'admin' THEN 2 ELSE NULL END
  FROM public.platform_admins WHERE user_id = _user AND is_active LIMIT 1;
$function$
;

-- rank_to_mission_role(_rank smallint)
CREATE OR REPLACE FUNCTION public.rank_to_mission_role(_rank smallint)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
AS $function$
  SELECT CASE
    WHEN _rank IS NULL THEN 'auditeur_junior'
    WHEN _rank >= 16   THEN 'directeur_mission'   -- un Partner ne peut etre moins
    WHEN _rank >= 5    THEN 'auditeur_experimente'
    WHEN _rank >= 3    THEN 'auditeur'
    ELSE 'auditeur_junior'
  END;
$function$
;

-- rapport_fiches_sans_cabinet()
CREATE OR REPLACE FUNCTION public.rapport_fiches_sans_cabinet()
 RETURNS TABLE(email text, nom text, grade text, donnees_travail bigint, plomberie_compte bigint, ou text, verdict text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _p RECORD; _fk RECORD; _n bigint; _d bigint; _pl bigint; _ou text; _pldet text;
BEGIN
  FOR _p IN
    SELECT pr.id, pr.email AS mail, pr.full_name, pr.grade AS gr
    FROM profiles pr WHERE pr.organization_id IS NULL ORDER BY pr.email
  LOOP
    _d := 0; _pl := 0; _ou := ''; _pldet := '';

    FOR _fk IN
      SELECT c.conrelid::regclass::text AS tbl, a.attname AS col,
             CASE c.confdeltype WHEN 'c' THEN 'CASCADE'
                                WHEN 'n' THEN 'SET NULL'
                                ELSE 'NO ACTION' END AS effet
      FROM pg_constraint c
      JOIN unnest(c.conkey) WITH ORDINALITY AS k(attnum, ord) ON true
      JOIN pg_attribute a ON a.attrelid = c.conrelid AND a.attnum = k.attnum
      WHERE c.contype = 'f'
        AND c.confrelid IN ('public.profiles'::regclass, 'auth.users'::regclass)
      ORDER BY 1, 2
    LOOP
      EXECUTE format('SELECT count(*) FROM %s WHERE %I = $1', _fk.tbl, _fk.col)
        INTO _n USING _p.id;
      CONTINUE WHEN _n = 0;

      IF public.est_plomberie_de_compte(_fk.tbl) THEN
        _pl := _pl + _n;
        _pldet := _pldet || CASE WHEN _pldet = '' THEN '' ELSE ' · ' END
                         || format('%s=%s', _fk.tbl, _n);
      ELSE
        _d  := _d + _n;
        _ou := _ou || CASE WHEN _ou = '' THEN '' ELSE ' · ' END
                   || format('%s.%s=%s[%s]', _fk.tbl, _fk.col, _n, _fk.effet);
      END IF;
    END LOOP;

    RETURN QUERY SELECT
      _p.mail::text, _p.full_name::text, _p.gr::text, _d, _pl,
      CASE WHEN _d = 0 THEN 'plomberie seule : ' || COALESCE(NULLIF(_pldet,''), 'rien')
           ELSE _ou END,
      CASE WHEN _d = 0 THEN 'SUPPRIMABLE sans perte'
           ELSE 'A GARDER : porte des donnees de travail' END;
  END LOOP;
END; $function$
;

-- rate_evaluation_objective(_objective_id uuid, _achievement_rate smallint, _comment text)
CREATE OR REPLACE FUNCTION public.rate_evaluation_objective(_objective_id uuid, _achievement_rate smallint, _comment text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _org uuid; _grade int; _o RECORD; _target int;
BEGIN
  SELECT p.organization_id, p.grade_level INTO _org, _grade
  FROM profiles p WHERE p.id = auth.uid();

  SELECT * INTO _o FROM evaluation_objectives WHERE id = _objective_id;
  IF _o IS NULL OR _o.organization_id <> _org THEN
    RAISE EXCEPTION 'Objectif introuvable';
  END IF;
  IF _achievement_rate IS NULL OR _achievement_rate < 0 OR _achievement_rate > 100 THEN
    RAISE EXCEPTION 'Le taux de réalisation doit être compris entre 0 et 100';
  END IF;

  SELECT grade_level INTO _target FROM profiles WHERE id = _o.user_id;
  IF COALESCE(_grade, 99) >= _target THEN
    RAISE EXCEPTION 'Seul un supérieur hiérarchique peut noter cet objectif';
  END IF;

  UPDATE evaluation_objectives
  SET achievement_rate = _achievement_rate,
      achievement_comment = _comment,
      evaluated_at = now(),
      status = CASE
        WHEN _achievement_rate >= 100 THEN 'atteint'
        WHEN _achievement_rate >= 50  THEN 'partiellement_atteint'
        ELSE 'non_atteint' END,
      updated_at = now()
  WHERE id = _objective_id;
END; $function$
;

-- refresh_evaluation_score()
CREATE OR REPLACE FUNCTION public.refresh_evaluation_score()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _eval uuid := COALESCE(NEW.evaluation_id, OLD.evaluation_id);
  _res jsonb;
BEGIN
  _res := public.compute_evaluation_score(_eval);
  UPDATE evaluations
     SET weighted_score     = (_res->>'weighted_score')::numeric,
         appreciation       = _res->>'appreciation',
         appreciation_label = _res->>'appreciation_label',
         updated_at         = now()
   WHERE id = _eval;
  RETURN NULL;
END; $function$
;

-- remove_mission_member(_mission_id uuid, _user_id uuid, _reason text)
CREATE OR REPLACE FUNCTION public.remove_mission_member(_mission_id uuid, _user_id uuid, _reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _mission missions%ROWTYPE;
  _caller uuid := auth.uid();
  _caller_org uuid;
  _caller_level int;
  _removed_projects int := 0;
  _removed_tasks int := 0;
  _cancelled_staffing int := 0;
BEGIN
  IF _caller IS NULL THEN
    RAISE EXCEPTION 'Authentification requise';
  END IF;
  IF _reason IS NULL OR length(btrim(_reason)) < 5 THEN
    RAISE EXCEPTION 'Le motif est obligatoire (5 caractères minimum)';
  END IF;

  SELECT * INTO _mission FROM missions WHERE id = _mission_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Mission introuvable';
  END IF;

  SELECT organization_id, grade_level INTO _caller_org, _caller_level FROM profiles WHERE id = _caller;
  IF _caller_org IS DISTINCT FROM _mission.organization_id THEN
    RAISE EXCEPTION 'Accès refusé à cette mission';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.mission_members mm WHERE mm.mission_id = _mission_id AND mm.user_id = auth.uid() AND mm.role = 'associe') THEN
    RAISE EXCEPTION 'Seul l''associe de la mission peut retirer un collaborateur de l''equipe';
  END IF;
  IF _user_id = _caller THEN
    RAISE EXCEPTION 'Vous ne pouvez pas vous retirer vous-même de la mission';
  END IF;
  IF _mission.director_id = _user_id THEN
    RAISE EXCEPTION 'Impossible de retirer le directeur de mission';
  END IF;
  IF _mission.chief_id = _user_id THEN
    RAISE EXCEPTION 'Impossible de retirer le chef de mission';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM mission_members WHERE mission_id = _mission_id AND user_id = _user_id) THEN
    RAISE EXCEPTION 'Ce collaborateur n''est pas membre de la mission';
  END IF;

  WITH del AS (
    DELETE FROM task_assignments ta
    USING tasks t, projects p
    WHERE ta.task_id = t.id AND t.project_id = p.id
      AND p.mission_id = _mission_id AND ta.user_id = _user_id
      AND t.status NOT IN ('done', 'validated')
    RETURNING 1
  ) SELECT count(*) INTO _removed_tasks FROM del;

  WITH del AS (
    DELETE FROM project_members pm
    USING projects p
    WHERE pm.project_id = p.id AND p.mission_id = _mission_id AND pm.user_id = _user_id
    RETURNING 1
  ) SELECT count(*) INTO _removed_projects FROM del;

  WITH upd AS (
    UPDATE staffing_assignments
    SET status = 'cancelled', updated_at = now()
    WHERE mission_id = _mission_id AND user_id = _user_id AND status <> 'cancelled'
    RETURNING 1
  ) SELECT count(*) INTO _cancelled_staffing FROM upd;

  DELETE FROM mission_members WHERE mission_id = _mission_id AND user_id = _user_id;

  INSERT INTO activity_logs (user_id, organization_id, action, entity_type, entity_id, metadata)
  VALUES (_caller, _mission.organization_id, 'mission_member_removed', 'mission', _mission_id,
          jsonb_build_object('removed_user', _user_id, 'reason', btrim(_reason),
                             'projects', _removed_projects, 'tasks', _removed_tasks,
                             'staffing', _cancelled_staffing));

  INSERT INTO notifications (user_id, type, title, content, entity_type, entity_id, priority)
  VALUES (_user_id, 'mission_member_removed', 'Retrait d''une mission',
          'Vous avez été retiré de la mission « ' || _mission.name || ' ». Motif : ' || btrim(_reason),
          'mission', _mission_id, 'high');

  RETURN jsonb_build_object('projects', _removed_projects, 'tasks', _removed_tasks, 'staffing', _cancelled_staffing);
END;
$function$
;

-- renommer_echelon(_echelon_id uuid, _nouveau_nom text)
CREATE OR REPLACE FUNCTION public.renommer_echelon(_echelon_id uuid, _nouveau_nom text)
 RETURNS TABLE(echelon text, profils_mis_a_jour integer, lignes_d_historique_mises_a_jour integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _e RECORD; _np int; _nh int;
BEGIN
  SELECT eg.* INTO _e FROM public.evaluation_grades eg WHERE eg.id = _echelon_id;
  IF _e.id IS NULL THEN
    RAISE EXCEPTION 'Echelon introuvable.';
  END IF;

  IF NOT public.est_directeur_associe(auth.uid())
     OR _e.organization_id IS DISTINCT FROM
        (SELECT p.organization_id FROM public.profiles p WHERE p.id = auth.uid()) THEN
    RAISE EXCEPTION 'Renommer un echelon de la grille revient au directeur associe de ce cabinet.';
  END IF;

  _nouveau_nom := btrim(_nouveau_nom);
  IF _nouveau_nom = '' THEN
    RAISE EXCEPTION 'Le nouveau nom ne peut pas etre vide.';
  END IF;

  IF EXISTS (SELECT 1 FROM public.evaluation_grades x
              WHERE x.organization_id = _e.organization_id
                AND x.practice = _e.practice
                AND x.id <> _e.id
                AND lower(btrim(x.echelon)) = lower(_nouveau_nom)) THEN
    RAISE EXCEPTION 'Un autre echelon de cette practice porte deja le nom « % ».', _nouveau_nom;
  END IF;

  PERFORM set_config('dgc.renommage_echelon', 'oui', true);

  UPDATE public.evaluation_grades SET echelon = _nouveau_nom WHERE id = _e.id;

  UPDATE public.grade_history gh SET grade_echelon = _nouveau_nom
  WHERE gh.organization_id = _e.organization_id
    AND gh.practice = _e.practice
    AND lower(btrim(gh.grade_echelon)) = lower(btrim(_e.echelon));
  GET DIAGNOSTICS _nh = ROW_COUNT;

  UPDATE public.profiles p SET grade_echelon = _nouveau_nom
  WHERE p.organization_id = _e.organization_id
    AND p.practice = _e.practice
    AND lower(btrim(p.grade_echelon)) = lower(btrim(_e.echelon));
  GET DIAGNOSTICS _np = ROW_COUNT;

  PERFORM set_config('dgc.renommage_echelon', '', true);

  RETURN QUERY SELECT _nouveau_nom, _np, _nh;
END $function$
;

-- request_evaluation_arbitration(_evaluation_id uuid, _reason text)
CREATE OR REPLACE FUNCTION public.request_evaluation_arbitration(_evaluation_id uuid, _reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _e RECORD; _grade int; _org uuid;
BEGIN
  SELECT p.organization_id, p.grade_level INTO _org, _grade
  FROM profiles p WHERE p.id = auth.uid();
  IF COALESCE(_grade, 99) > 2 THEN
    RAISE EXCEPTION 'Accès refusé : l''arbitrage relève du Directeur Associé ou du Directeur de Mission';
  END IF;
  IF _reason IS NULL OR length(trim(_reason)) < 10 THEN
    RAISE EXCEPTION 'Le motif de l''arbitrage est obligatoire';
  END IF;

  SELECT * INTO _e FROM evaluations WHERE id = _evaluation_id AND organization_id = _org;
  IF _e IS NULL THEN RAISE EXCEPTION 'Évaluation introuvable'; END IF;
  IF _e.status <> 'validee' THEN
    RAISE EXCEPTION 'Seule une évaluation validée peut faire l''objet d''un arbitrage';
  END IF;

  INSERT INTO evaluation_arbitrations (evaluation_id, requested_by, reason)
  VALUES (_evaluation_id, auth.uid(), _reason);

  UPDATE evaluations SET status = 'arbitrage', updated_at = now() WHERE id = _evaluation_id;

  INSERT INTO evaluation_exchanges (evaluation_id, round, actor_id, action, message)
  VALUES (_evaluation_id, _e.round_count, auth.uid(), 'arbitrage_demande', _reason);

  INSERT INTO notifications (user_id, type, title, content, entity_type, entity_id, priority)
  SELECT unnest(ARRAY[_e.evaluator_id, _e.evaluatee_id]), 'evaluation_arbitration',
    'Arbitrage ouvert', 'Un arbitrage a été ouvert sur l''évaluation concernée.',
    'evaluation', _evaluation_id, 'high';

  RETURN jsonb_build_object('success', true);
END; $function$
;

-- request_evaluation_feedback(_evaluation_id uuid, _contributor_ids uuid[])
CREATE OR REPLACE FUNCTION public.request_evaluation_feedback(_evaluation_id uuid, _contributor_ids uuid[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _e RECORD; _ee_grade int; _c uuid; _n int := 0;
BEGIN
  SELECT * INTO _e FROM evaluations WHERE id = _evaluation_id;
  IF _e IS NULL THEN RAISE EXCEPTION 'Évaluation introuvable'; END IF;
  IF _e.evaluator_id <> auth.uid() THEN
    RAISE EXCEPTION 'Seul l''évaluateur peut solliciter des avis consultatifs';
  END IF;
  IF _e.status NOT IN ('brouillon', 'observations_recues', 'revisee') THEN
    RAISE EXCEPTION 'Les avis consultatifs se recueillent avant la validation';
  END IF;

  -- §5.5 : réservé aux grades Manager et au-delà. Dans la hiérarchie
  -- du cabinet, Chef de mission et Superviseur et au-dessus.
  SELECT grade_level INTO _ee_grade FROM profiles WHERE id = _e.evaluatee_id;
  IF COALESCE(_ee_grade, 99) > 4 THEN
    RAISE EXCEPTION 'L''évaluation multi-source est réservée aux grades Manager et au-delà (§5.5)';
  END IF;

  FOREACH _c IN ARRAY _contributor_ids LOOP
    IF _c = _e.evaluatee_id THEN
      RAISE EXCEPTION 'Le collaborateur évalué ne peut pas être sollicité sur sa propre évaluation';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM profiles
                   WHERE id = _c AND organization_id = _e.organization_id) THEN
      CONTINUE;
    END IF;

    INSERT INTO evaluation_feedback
      (organization_id, evaluation_id, requested_by, contributor_id, mission_id)
    VALUES (_e.organization_id, _evaluation_id, auth.uid(), _c, _e.mission_id)
    ON CONFLICT (evaluation_id, contributor_id) DO NOTHING;

    IF FOUND THEN _n := _n + 1; END IF;
  END LOOP;

  RETURN jsonb_build_object('avis_sollicites', _n);
END; $function$
;

-- resolve_dossier_practice(_dossier_id uuid)
CREATE OR REPLACE FUNCTION public.resolve_dossier_practice(_dossier_id uuid)
 RETURNS eval_practice
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  -- Un dossier comptable est comptable. Une obligation juridique qu'il
  -- porte — une AGO, par exemple — ne le fait pas basculer dans la
  -- practice juridique : elle fait partie du travail comptable du dossier.
  SELECT 'comptable'::public.eval_practice
  WHERE EXISTS (SELECT 1 FROM client_fiscal_profile WHERE id = _dossier_id);
$function$
;

-- resolve_echelon(_user_id uuid, _practice eval_practice)
CREATE OR REPLACE FUNCTION public.resolve_echelon(_user_id uuid, _practice eval_practice)
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _org uuid; _home public.eval_practice; _home_ech text; _grade text;
  _rank smallint; _ech text;
BEGIN
  SELECT p.organization_id, p.practice, p.grade_echelon, p.grade
    INTO _org, _home, _home_ech, _grade
  FROM profiles p WHERE p.id = _user_id;

  IF _org IS NULL THEN RETURN NULL; END IF;

  -- Même practice que le rattachement : rien à traduire.
  IF _practice IS NULL OR _practice = _home THEN
    RETURN _home_ech;
  END IF;

  -- Rang du collaborateur dans sa practice de rattachement
  SELECT g.rank INTO _rank FROM evaluation_grades g
  WHERE g.organization_id = _org AND g.practice = _home
    AND lower(btrim(g.echelon)) = lower(btrim(_home_ech))
  LIMIT 1;

  -- À défaut d'échelon exploitable, on se rabat sur le grade de
  -- l'application : son échelon le plus bas dans la practice visée.
  IF _rank IS NULL THEN
    SELECT g.echelon INTO _ech FROM evaluation_grades g
    WHERE g.organization_id = _org AND g.practice = _practice
      AND g.maps_to_grade = _grade
    ORDER BY g.rank LIMIT 1;
    RETURN _ech;
  END IF;

  SELECT g.echelon INTO _ech FROM evaluation_grades g
  WHERE g.organization_id = _org AND g.practice = _practice AND g.rank = _rank
  LIMIT 1;

  RETURN _ech;
END; $function$
;

-- resolve_evaluation_departement(_mission_id uuid, _dossier_id uuid, _org uuid)
CREATE OR REPLACE FUNCTION public.resolve_evaluation_departement(_mission_id uuid, _dossier_id uuid, _org uuid)
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _lab text;
BEGIN
  IF _dossier_id IS NOT NULL THEN
    SELECT d.label INTO _lab
    FROM client_fiscal_profile f
    JOIN departments d ON d.id = f.department_id
    WHERE f.id = _dossier_id;
    IF _lab IS NOT NULL THEN RETURN _lab; END IF;
    -- un dossier sans département explicite prend celui des dossiers
    SELECT label INTO _lab FROM departments
     WHERE organization_id = _org AND is_default_dossier;
    RETURN _lab;
  END IF;

  IF _mission_id IS NOT NULL THEN
    SELECT d.label INTO _lab
    FROM missions m JOIN departments d ON d.id = m.department_id
    WHERE m.id = _mission_id;
    RETURN _lab;   -- NULL si la mission n'a pas de département : c'est exact
  END IF;

  -- Évaluation annuelle ou de fin de stage : elle ne porte sur aucun
  -- travail en particulier, donc sur aucun département.
  RETURN NULL;
END; $function$
;

-- resolve_evaluation_practice(_assignment_practice eval_practice, _mission_id uuid, _user_id uuid, _eval_type eval_type, _dossier_id uuid)
CREATE OR REPLACE FUNCTION public.resolve_evaluation_practice(_assignment_practice eval_practice, _mission_id uuid, _user_id uuid, _eval_type eval_type, _dossier_id uuid DEFAULT NULL::uuid)
 RETURNS eval_practice
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _p public.eval_practice; _src text; _org uuid;
BEGIN
  -- 1. Le choix explicite de l'affectation prime toujours.
  IF _assignment_practice IS NOT NULL THEN RETURN _assignment_practice; END IF;

  SELECT organization_id INTO _org FROM profiles WHERE id = _user_id;
  SELECT eval_mission_practice_source INTO _src FROM organizations WHERE id = _org;

  IF _eval_type <> 'mission' THEN
    -- 2. Évaluation annuelle ou de fin de stage : la practice de
    --    rattachement du collaborateur.
    SELECT practice INTO _p FROM profiles WHERE id = _user_id;

  ELSIF _dossier_id IS NOT NULL THEN
    -- 3. Évaluation de dossier comptable : la nature des obligations
    --    portées par le dossier.
    _p := public.resolve_dossier_practice(_dossier_id);

  ELSIF COALESCE(_src, 'mission') = 'mission' AND _mission_id IS NOT NULL THEN
    -- 4. Évaluation de mission : la nature du travail effectué.
    SELECT m.practice INTO _p FROM missions m WHERE m.id = _mission_id;
  END IF;

  IF _p IS NULL THEN
    SELECT practice INTO _p FROM profiles WHERE id = _user_id;
  END IF;
  IF _p IS NULL THEN
    SELECT eval_default_practice INTO _p FROM organizations WHERE id = _org;
  END IF;
  RETURN _p;
END; $function$
;

-- retirer_designation(_assignment_id uuid)
CREATE OR REPLACE FUNCTION public.retirer_designation(_assignment_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NOT public.est_directeur_associe(auth.uid()) THEN
    RAISE EXCEPTION 'La désignation des évaluateurs revient au directeur associé.'; END IF;
  IF EXISTS (SELECT 1 FROM evaluations e WHERE e.assignment_id = _assignment_id) THEN
    RAISE EXCEPTION 'L''évaluation est déjà ouverte : cette désignation ne peut plus être retirée.'; END IF;
  UPDATE evaluation_assignments SET status = 'annulee'
   WHERE id = _assignment_id AND status = 'a_faire'
     AND organization_id = (SELECT organization_id FROM profiles WHERE id = auth.uid());
  IF NOT FOUND THEN RAISE EXCEPTION 'Désignation introuvable ou déjà engagée.'; END IF;
  RETURN jsonb_build_object('success', true);
END; $function$
;

-- review_deposited_documents(_document_ids uuid[], _action text, _reason text)
CREATE OR REPLACE FUNCTION public.review_deposited_documents(_document_ids uuid[], _action text, _reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _org uuid;
  _count integer := 0;
  _rec RECORD;
BEGIN
  SELECT p.organization_id INTO _org FROM profiles p WHERE p.id = auth.uid();
  IF _org IS NULL THEN RAISE EXCEPTION 'Accès refusé'; END IF;

  IF _action NOT IN ('validate', 'reject') THEN
    RAISE EXCEPTION 'Action invalide';
  END IF;

  IF _action = 'reject' AND (_reason IS NULL OR length(trim(_reason)) < 5) THEN
    RAISE EXCEPTION 'Le motif de rejet est obligatoire : le client doit savoir quoi corriger';
  END IF;

  FOR _rec IN
    SELECT od.id, od.label, op.client_id, op.organization_id
    FROM obligation_documents od
    JOIN obligation_periods op ON op.id = od.obligation_period_id
    WHERE od.id = ANY(_document_ids)
      AND op.organization_id = _org
      AND od.status = 'deposee'
  LOOP
    IF _action = 'validate' THEN
      UPDATE obligation_documents
         SET status = 'recue', validated_at = now(), validated_by = auth.uid(),
             reject_reason = NULL
       WHERE id = _rec.id;
    ELSE
      UPDATE obligation_documents
         SET status = 'rejetee', reject_reason = _reason,
             validated_at = NULL, validated_by = NULL
       WHERE id = _rec.id;
    END IF;

    INSERT INTO portal_access_log
      (portal_user_id, client_id, organization_id, action, entity_type, entity_id, details)
    VALUES (NULL, _rec.client_id, _rec.organization_id,
            CASE WHEN _action = 'validate' THEN 'document_validated' ELSE 'document_rejected' END,
            'obligation_document', _rec.id,
            jsonb_build_object('label', _rec.label, 'reason', _reason, 'by', auth.uid()));

    _count := _count + 1;
  END LOOP;

  RETURN jsonb_build_object('success', true, 'processed', _count, 'action', _action);
END;
$function$
;

