    ('annuelle','juridique','Partner 3','D','Pilotage stratégique ultime de la rentabilité et de la pérennité du cabinet',1),
    ('annuelle','juridique','Partner 3','D','Arbitrage ultime des priorités stratégiques du cabinet',2),
    ('annuelle','juridique','Partner 3','E','Relation de confiance au plus haut niveau avec l''ensemble des parties prenantes du cabinet',1),
    ('annuelle','juridique','Partner 3','E','Leadership et influence déterminants au sein du collège des associés',2),
    ('annuelle','juridique','Partner 3','F','Garant ultime de la culture, de la performance et de la pérennité du cabinet',1),
    ('annuelle','juridique','Partner 3','F','Décisions stratégiques ultimes de gouvernance du cabinet',2),
    ('annuelle','juridique','Partner 3','G','Responsabilité ultime du développement commercial et de la rentabilité du cabinet',1),
    ('annuelle','juridique','Partner 3','G','Apporteur d''affaires de référence et développement des comptes les plus stratégiques',2),
    ('annuelle','juridique','Partner 3','H','Décisions ultimes de développement des compétences à l''échelle du cabinet',1),
    ('annuelle','juridique','Partner 3','H','Pilotage de la gouvernance RH et de la politique de formation du cabinet',2)
  ) AS v(etype, prac, ech, ccode, label, ord)
  JOIN evaluation_templates t
    ON t.organization_id = _org
   AND t.eval_type = v.etype::eval_type
   AND t.practice  = v.prac::eval_practice
   AND t.echelon   = v.ech
  JOIN evaluation_categories c ON c.template_id = t.id AND c.code = v.ccode
  WHERE NOT EXISTS (
    SELECT 1 FROM evaluation_subcriteria s
    WHERE s.category_id = c.id AND s.label = v.label);
  GET DIAGNOSTICS _s = ROW_COUNT;

  RETURN jsonb_build_object('grilles', _t, 'categories', _c, 'sous_criteres', _s);
END $function$
;

-- seed_evaluation_scale(_org_id uuid)
CREATE OR REPLACE FUNCTION public.seed_evaluation_scale(_org_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  INSERT INTO evaluation_scale (organization_id, code, label, min_score, max_score, color, hr_consequence, sort_order)
  VALUES
    (_org_id, 'tres_en_dessous', 'Très en dessous des attentes', 0,  29.99, '#C0392B',
     'Plan d''amélioration obligatoire. Deux appréciations consécutives peuvent conduire à une rupture du contrat ; pour un stagiaire, fait obstacle à l''embauche.', 1),
    (_org_id, 'en_dessous', 'En dessous des attentes', 30, 49.99, '#E67E22',
     'Maintien de grade et de rémunération ; plan de développement ciblé et suivi renforcé.', 2),
    (_org_id, 'rencontre', 'Rencontre les attentes', 50, 69.99, '#B7791F',
     'Maintien de grade ; éligibilité à l''avancement selon l''ancienneté et les besoins du cabinet.', 3),
    (_org_id, 'depasse', 'Dépasse les attentes', 70, 89.99, '#1E7A4B',
     'Éligibilité prioritaire à l''avancement et à la revalorisation.', 4),
    (_org_id, 'excellent', 'Excellent / Dépasse largement les attentes', 90, 100, '#16519C',
     'Éligibilité prioritaire à l''avancement, à la revalorisation et aux missions à plus forte responsabilité ; profil à orienter vers les plans de succession.', 5)
  ON CONFLICT (organization_id, code) DO NOTHING;
END; $function$
;

-- seed_obligation_documents(_org_id uuid)
CREATE OR REPLACE FUNCTION public.seed_obligation_documents(_org_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _tva uuid; _its uuid; _cnps uuid; _etats uuid; _liasse uuid;
BEGIN
  SELECT id INTO _tva    FROM obligation_types WHERE organization_id = _org_id AND code = 'TVA';
  SELECT id INTO _its    FROM obligation_types WHERE organization_id = _org_id AND code = 'ITS';
  SELECT id INTO _cnps   FROM obligation_types WHERE organization_id = _org_id AND code = 'CNPS';
  SELECT id INTO _etats  FROM obligation_types WHERE organization_id = _org_id AND code = 'ETATS_FIN';
  SELECT id INTO _liasse FROM obligation_types WHERE organization_id = _org_id AND code = 'LIASSE';

  -- TVA
  IF _tva IS NOT NULL THEN
    INSERT INTO obligation_document_types (obligation_type_id, label, is_required, sort_order) VALUES
      (_tva, 'Factures de vente du mois', true, 1),
      (_tva, 'Factures d''achat du mois', true, 2),
      (_tva, 'Relevés bancaires', true, 3),
      (_tva, 'Journal de caisse', false, 4)
    ON CONFLICT (obligation_type_id, label) DO NOTHING;
  END IF;

  -- ITS
  IF _its IS NOT NULL THEN
    INSERT INTO obligation_document_types (obligation_type_id, label, is_required, sort_order) VALUES
      (_its, 'État de paie du mois', true, 1),
      (_its, 'Liste du personnel', true, 2),
      (_its, 'Contrats des nouveaux embauchés', false, 3)
    ON CONFLICT (obligation_type_id, label) DO NOTHING;
  END IF;

  -- CNPS
  IF _cnps IS NOT NULL THEN
    INSERT INTO obligation_document_types (obligation_type_id, label, is_required, sort_order) VALUES
      (_cnps, 'État de paie du mois', true, 1),
      (_cnps, 'Déclaration des mouvements de personnel', true, 2)
    ON CONFLICT (obligation_type_id, label) DO NOTHING;
  END IF;

  -- États financiers
  IF _etats IS NOT NULL THEN
    INSERT INTO obligation_document_types (obligation_type_id, label, is_required, sort_order) VALUES
      (_etats, 'Balance générale au 31/12', true, 1),
      (_etats, 'Inventaire physique des stocks', true, 2),
      (_etats, 'Relevés bancaires au 31/12', true, 3),
      (_etats, 'État des immobilisations', true, 4),
      (_etats, 'Contrats de prêt en cours', false, 5),
      (_etats, 'États de rapprochement bancaire', true, 6)
    ON CONFLICT (obligation_type_id, label) DO NOTHING;
  END IF;

  -- Liasse fiscale
  IF _liasse IS NOT NULL THEN
    INSERT INTO obligation_document_types (obligation_type_id, label, is_required, sort_order) VALUES
      (_liasse, 'États financiers validés', true, 1),
      (_liasse, 'Grand livre de l''exercice', true, 2),
      (_liasse, 'Détail des charges non déductibles', false, 3)
    ON CONFLICT (obligation_type_id, label) DO NOTHING;
  END IF;
END;
$function$
;

