-- seed_platform_owner(_email text)
CREATE OR REPLACE FUNCTION public.seed_platform_owner(_email text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _uid uuid;
BEGIN
  -- Ne fonctionne que si aucun owner n'existe encore (amorçage unique)
  IF EXISTS (SELECT 1 FROM platform_admins WHERE role = 'owner' AND is_active) THEN
    RAISE EXCEPTION 'Un owner existe déjà. Utilisez l''interface pour en ajouter.';
  END IF;

  SELECT p.id INTO _uid FROM profiles p WHERE lower(p.email) = lower(_email);
  IF _uid IS NULL THEN
    RAISE EXCEPTION 'Aucun profil trouvé pour %', _email;
  END IF;

  INSERT INTO platform_admins (user_id, email, role, granted_by)
  VALUES (_uid, lower(_email), 'owner', _uid);

  RETURN 'Owner plateforme créé : ' || _email;
END;
$function$
;

-- send_evaluation(_evaluation_id uuid)
CREATE OR REPLACE FUNCTION public.send_evaluation(_evaluation_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _e RECORD; _res jsonb;
BEGIN
  SELECT * INTO _e FROM evaluations WHERE id = _evaluation_id;
  IF _e IS NULL THEN RAISE EXCEPTION 'Évaluation introuvable'; END IF;
  IF _e.evaluator_id <> auth.uid() THEN
    RAISE EXCEPTION 'Seul l''évaluateur peut transmettre cette évaluation';
  END IF;
  IF _e.status NOT IN ('brouillon', 'observations_recues', 'revisee') THEN
    RAISE EXCEPTION 'Cette évaluation ne peut plus être transmise';
  END IF;

  _res := public.compute_evaluation_score(_evaluation_id);
  IF NOT (_res->>'is_complete')::boolean THEN
    RAISE EXCEPTION 'Tous les sous-critères doivent être notés avant transmission';
  END IF;

  UPDATE evaluations
     SET status = 'envoyee', sent_at = now(),
         round_count = round_count + 1, updated_at = now()
   WHERE id = _evaluation_id;

  INSERT INTO evaluation_exchanges (evaluation_id, round, actor_id, action, score_after)
  VALUES (_evaluation_id, _e.round_count + 1, auth.uid(), 'envoi',
          (_res->>'weighted_score')::numeric);

  INSERT INTO notifications (user_id, type, title, content, entity_type, entity_id, priority)
  VALUES (_e.evaluatee_id, 'evaluation_received', 'Votre évaluation est disponible',
    'Votre évaluation' || COALESCE(' de la mission ' || _e.mission_code, '') ||
    ' vous a été transmise. Consultez-la et formulez vos observations.',
    'evaluation', _evaluation_id, 'high');

  RETURN jsonb_build_object('success', true, 'round', _e.round_count + 1);
END; $function$
;

-- set_activity_org_id()
CREATE OR REPLACE FUNCTION public.set_activity_org_id()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.organization_id IS NULL THEN
    NEW.organization_id := (SELECT organization_id FROM profiles WHERE id = NEW.user_id);
  END IF;
  RETURN NEW;
END;
$function$
;

-- set_attendance_org_id()
CREATE OR REPLACE FUNCTION public.set_attendance_org_id()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.organization_id IS NULL THEN
    NEW.organization_id := (SELECT organization_id FROM profiles WHERE id = auth.uid());
  END IF;
  IF NEW.event_date IS NULL THEN
    NEW.event_date := (NEW.event_at AT TIME ZONE 'UTC')::date;
  END IF;
  RETURN NEW;
END; $function$
;

