-- set_default_dossier_department(_department_id uuid)
CREATE OR REPLACE FUNCTION public.set_default_dossier_department(_department_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _org uuid; _level integer;
BEGIN
 SELECT organization_id,grade_level INTO _org,_level FROM public.profiles WHERE id=auth.uid();
 IF _org IS NULL OR COALESCE(_level,99)>2 THEN RAISE EXCEPTION 'Accès réservé à la direction'; END IF;
 PERFORM 1 FROM public.organizations WHERE id=_org FOR UPDATE;
 IF NOT EXISTS (SELECT 1 FROM public.departments WHERE id=_department_id AND organization_id=_org AND is_active) THEN RAISE EXCEPTION 'Choisissez un département actif de votre cabinet'; END IF;
 UPDATE public.departments SET is_default_dossier=false,updated_at=now() WHERE organization_id=_org AND is_default_dossier AND id<>_department_id;
 UPDATE public.departments SET is_default_dossier=true,updated_at=now() WHERE id=_department_id AND organization_id=_org;
END;
$function$
;

-- set_evaluation_mission_code(_evaluation_id uuid, _code text)
CREATE OR REPLACE FUNCTION public.set_evaluation_mission_code(_evaluation_id uuid, _code text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _e RECORD; _grade int; _org uuid;
BEGIN
  SELECT * INTO _e FROM evaluations WHERE id = _evaluation_id;
  IF _e IS NULL THEN RAISE EXCEPTION 'Évaluation introuvable'; END IF;

  SELECT p.organization_id, p.grade_level INTO _org, _grade
  FROM profiles p WHERE p.id = auth.uid();

  -- L'évaluateur désigné, ou la direction.
  IF _e.evaluator_id <> auth.uid()
     AND NOT (_e.organization_id = _org AND COALESCE(_grade, 99) <= 2) THEN
    RAISE EXCEPTION 'Seul l''évaluateur désigné ou la direction peut renseigner le code de mission';
  END IF;

  IF _e.status IN ('validee', 'cloturee') THEN
    RAISE EXCEPTION 'Le code de mission ne se modifie plus après validation';
  END IF;

  UPDATE evaluations
     SET mission_code = NULLIF(btrim(_code), ''), updated_at = now()
   WHERE id = _evaluation_id;

  RETURN jsonb_build_object('success', true, 'code_mission', NULLIF(btrim(_code), ''));
END; $function$
;

-- set_evaluation_objectives(_user_id uuid, _exercice smallint, _objectives jsonb)
CREATE OR REPLACE FUNCTION public.set_evaluation_objectives(_user_id uuid, _exercice smallint, _objectives jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _org uuid; _grade int; _target_grade int; _n int := 0; _o jsonb; _i smallint := 0;
BEGIN
  SELECT p.organization_id, p.grade_level INTO _org, _grade
  FROM profiles p WHERE p.id = auth.uid();

  SELECT grade_level INTO _target_grade
  FROM profiles WHERE id = _user_id AND organization_id = _org;

  IF _target_grade IS NULL THEN
    RAISE EXCEPTION 'Collaborateur introuvable dans votre organisation';
  END IF;
  IF COALESCE(_grade, 99) >= _target_grade THEN
    RAISE EXCEPTION 'Seul un supérieur hiérarchique peut fixer les objectifs d''un collaborateur';
  END IF;
  IF jsonb_typeof(_objectives) <> 'array' THEN
    RAISE EXCEPTION 'Format d''objectifs invalide';
  END IF;

  -- Les objectifs déjà notés ne sont pas écrasés
  DELETE FROM evaluation_objectives
  WHERE user_id = _user_id AND exercice = _exercice AND evaluated_at IS NULL;

  FOR _o IN SELECT * FROM jsonb_array_elements(_objectives)
  LOOP
    _i := _i + 1;
    IF COALESCE(trim(_o->>'title'), '') = '' THEN
      RAISE EXCEPTION 'L''objectif n° % doit porter un intitulé', _i;
    END IF;

    INSERT INTO evaluation_objectives
      (organization_id, user_id, evaluator_id, exercice, sort_order,
       title, specific, measurable, achievable, realistic, deadline)
    VALUES (_org, _user_id, auth.uid(), _exercice, _i,
       trim(_o->>'title'), _o->>'specific', _o->>'measurable',
       _o->>'achievable', _o->>'realistic', (_o->>'deadline')::date);
    _n := _n + 1;
  END LOOP;

  RETURN jsonb_build_object('objectifs_enregistres', _n, 'exercice', _exercice);
END; $function$
;

-- set_evaluation_practice_settings(_source text, _default eval_practice)
CREATE OR REPLACE FUNCTION public.set_evaluation_practice_settings(_source text, _default eval_practice)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _org uuid; _lvl int;
BEGIN
  SELECT organization_id, grade_level INTO _org, _lvl FROM public.profiles WHERE id = auth.uid();
  IF _org IS NULL OR COALESCE(_lvl, 8) > 2 THEN RAISE EXCEPTION 'Réservé à la direction du cabinet.'; END IF;
  IF _source NOT IN ('mission','collaborateur') THEN RAISE EXCEPTION 'Source de practice invalide.'; END IF;
  UPDATE public.organizations SET eval_mission_practice_source = _source, eval_default_practice = _default WHERE id = _org;
END $function$
;

-- set_evaluation_scale_thresholds(_thresholds jsonb)
CREATE OR REPLACE FUNCTION public.set_evaluation_scale_thresholds(_thresholds jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _org uuid; _grade integer; _r jsonb; _prev numeric:=-1;
BEGIN
 SELECT organization_id,grade_level INTO _org,_grade FROM profiles WHERE id=auth.uid();
 IF _org IS NULL OR COALESCE(_grade,99)>2 THEN RAISE EXCEPTION 'Accès refusé : seuils réservés à la direction'; END IF;
 IF jsonb_typeof(_thresholds)<>'array' OR jsonb_array_length(_thresholds)<>(SELECT COUNT(*) FROM evaluation_scale WHERE organization_id=_org) THEN RAISE EXCEPTION 'Renseignez tous les niveaux de l''échelle'; END IF;
 IF (SELECT COUNT(DISTINCT x->>'id') FROM jsonb_array_elements(_thresholds) x)<>jsonb_array_length(_thresholds) THEN RAISE EXCEPTION 'Un niveau ne peut apparaître deux fois'; END IF;
 FOR _r IN SELECT x FROM jsonb_array_elements(_thresholds) x ORDER BY (x->>'min_score')::numeric LOOP
  IF NOT EXISTS(SELECT 1 FROM evaluation_scale WHERE id=(_r->>'id')::uuid AND organization_id=_org) THEN RAISE EXCEPTION 'Niveau introuvable dans votre cabinet'; END IF;
  IF (_r->>'min_score') IS NULL OR (_r->>'max_score') IS NULL OR (_r->>'min_score')::numeric<0 OR (_r->>'max_score')::numeric>100 OR (_r->>'min_score')::numeric>(_r->>'max_score')::numeric OR (_r->>'min_score')::numeric<=_prev THEN RAISE EXCEPTION 'Seuils invalides ou chevauchants'; END IF;
  _prev:=(_r->>'max_score')::numeric;
  UPDATE evaluation_scale SET min_score=(_r->>'min_score')::numeric,max_score=(_r->>'max_score')::numeric WHERE id=(_r->>'id')::uuid AND organization_id=_org;
 END LOOP;
END $function$
;

-- set_evaluation_settings(_missions numeric, _annuelle numeric, _aggregation text, _cycles smallint)
CREATE OR REPLACE FUNCTION public.set_evaluation_settings(_missions numeric, _annuelle numeric, _aggregation text, _cycles smallint)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _org uuid; _grade integer;
BEGIN
 SELECT organization_id,grade_level INTO _org,_grade FROM profiles WHERE id=auth.uid();
 IF _org IS NULL OR COALESCE(_grade,99)>2 THEN RAISE EXCEPTION 'Accès refusé : paramètres réservés à la direction'; END IF;
 IF _missions IS NULL OR _annuelle IS NULL OR _missions<0 OR _annuelle<0 OR abs(_missions+_annuelle-1)>0.00001 THEN RAISE EXCEPTION 'La somme des pondérations doit être égale à 100 %%'; END IF;
 IF _aggregation IS NULL OR _aggregation NOT IN ('simple','duree','charge') THEN RAISE EXCEPTION 'Mode d''agrégation invalide'; END IF;
 IF _cycles IS NULL OR _cycles<1 OR _cycles>5 THEN RAISE EXCEPTION 'Le nombre de cycles doit être compris entre 1 et 5'; END IF;
 UPDATE organizations SET eval_weight_missions=_missions,eval_weight_annuelle=_annuelle,eval_mission_aggregation=_aggregation,eval_history_cycles=_cycles WHERE id=_org;
END $function$
;

-- set_evaluation_significance(_evaluation_id uuid, _is_significant boolean, _weight_basis numeric)
CREATE OR REPLACE FUNCTION public.set_evaluation_significance(_evaluation_id uuid, _is_significant boolean, _weight_basis numeric DEFAULT NULL::numeric)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _org uuid; _grade int;
BEGIN
  SELECT p.organization_id, p.grade_level INTO _org, _grade
  FROM profiles p WHERE p.id = auth.uid();

  IF COALESCE(_grade, 99) > 2 THEN
    RAISE EXCEPTION 'Accès refusé : le caractère significatif d''une mission relève de la direction';
  END IF;

  UPDATE evaluations
  SET is_significant = _is_significant,
      weight_basis = COALESCE(_weight_basis, weight_basis)
  WHERE id = _evaluation_id AND organization_id = _org;

  IF NOT FOUND THEN RAISE EXCEPTION 'Évaluation introuvable'; END IF;
END; $function$
;

-- set_fiscal_year_start_month(_month smallint, _dry_run boolean)
CREATE OR REPLACE FUNCTION public.set_fiscal_year_start_month(_month smallint, _dry_run boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _org uuid; _grade int; _actuel smallint;
  _impactees int; _verrouillees int; _n int;
BEGIN
  SELECT p.organization_id, p.grade_level INTO _org, _grade
  FROM profiles p WHERE p.id = auth.uid();

  IF COALESCE(_grade, 99) > 2 THEN
    RAISE EXCEPTION 'Accès refusé : le calendrier d''évaluation relève de la direction';
  END IF;
  IF _month IS NULL OR _month < 1 OR _month > 12 THEN
    RAISE EXCEPTION 'Le mois d''ouverture doit être compris entre 1 et 12';
  END IF;

  SELECT fiscal_year_start_month INTO _actuel FROM organizations WHERE id = _org;

  -- Combien d'évaluations changeraient d'exercice
  SELECT count(*) INTO _impactees
  FROM evaluations e
  WHERE e.organization_id = _org
    AND e.eval_type = 'mission'
    AND e.exercice IS DISTINCT FROM (CASE
      WHEN EXTRACT(MONTH FROM COALESCE(e.period_end, e.created_at::date))::int >= _month
        THEN EXTRACT(YEAR FROM COALESCE(e.period_end, e.created_at::date))::smallint
      ELSE (EXTRACT(YEAR FROM COALESCE(e.period_end, e.created_at::date))::int - 1)::smallint
    END);

  -- Une évaluation annuelle porte l'exercice de sa campagne : on ne la
  -- redate pas, elle a été ouverte pour un exercice nommé.
  SELECT count(*) INTO _verrouillees
  FROM evaluations e
  WHERE e.organization_id = _org AND e.eval_type <> 'mission';

  IF _dry_run THEN
    RETURN jsonb_build_object(
      'simulation', true,
      'mois_actuel', _actuel,
      'mois_demande', _month,
      'evaluations_redatees', _impactees,
      'evaluations_annuelles_inchangees', _verrouillees);
  END IF;

  UPDATE organizations SET fiscal_year_start_month = _month WHERE id = _org;

  UPDATE evaluations e
     SET exercice = public.fiscal_exercice(
           COALESCE(e.period_end, e.validated_at::date, e.created_at::date), _org)
   WHERE e.organization_id = _org AND e.eval_type = 'mission';
  GET DIAGNOSTICS _n = ROW_COUNT;

  RETURN jsonb_build_object(
    'simulation', false,
    'mois_precedent', _actuel,
    'mois_applique', _month,
    'evaluations_redatees', _impactees,
    'evaluations_parcourues', _n,
    'evaluations_annuelles_inchangees', _verrouillees);
END; $function$
;

-- set_obldoc_defaults()
CREATE OR REPLACE FUNCTION public.set_obldoc_defaults()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.organization_id IS NULL THEN
    NEW.organization_id := (SELECT op.organization_id FROM obligation_periods op WHERE op.id = NEW.obligation_period_id);
  END IF;
  -- Horodatage de validation
  IF NEW.status = 'recue' AND OLD.status IS DISTINCT FROM 'recue' THEN
    NEW.validated_at := COALESCE(NEW.validated_at, now());
    NEW.validated_by := COALESCE(NEW.validated_by, auth.uid());
  END IF;
  NEW.updated_at := now();
  RETURN NEW;
END; $function$
;

-- set_oblper_defaults()
CREATE OR REPLACE FUNCTION public.set_oblper_defaults()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.organization_id IS NULL THEN
    NEW.organization_id := (SELECT c.organization_id FROM clients c WHERE c.id = NEW.client_id);
  END IF;
  -- Horodatage automatique du dépôt
  IF NEW.status = 'depose' AND OLD.status IS DISTINCT FROM 'depose' THEN
    NEW.deposed_at := COALESCE(NEW.deposed_at, now());
    NEW.deposed_by := COALESCE(NEW.deposed_by, auth.uid());
  END IF;
  NEW.updated_at := now();
  RETURN NEW;
END; $function$
;

