-- set_portal_document_defaults()
CREATE OR REPLACE FUNCTION public.set_portal_document_defaults()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _client_org uuid;
  _portal_client uuid;
BEGIN
  -- Le client_id doit appartenir à l'organisation déclarée
  SELECT c.organization_id INTO _client_org FROM clients c WHERE c.id = NEW.client_id;
  IF _client_org IS NULL THEN
    RAISE EXCEPTION 'Client introuvable';
  END IF;

  IF NEW.organization_id IS NULL THEN
    NEW.organization_id := _client_org;
  ELSIF NEW.organization_id <> _client_org THEN
    RAISE EXCEPTION 'Incohérence entre le client et l''organisation';
  END IF;

  -- Dépôt par un client : il ne peut déposer QUE pour son propre dossier
  _portal_client := public.current_portal_client();
  IF _portal_client IS NOT NULL THEN
    IF NEW.direction <> 'from_client' THEN
      RAISE EXCEPTION 'Un client ne peut déposer que dans le sens from_client';
    END IF;
    IF NEW.client_id <> _portal_client THEN
      RAISE EXCEPTION 'Vous ne pouvez déposer que dans votre propre dossier';
    END IF;
    NEW.uploaded_by_client := auth.uid();
    NEW.uploaded_by_staff := NULL;
  ELSE
    -- Dépôt par le cabinet
    IF NEW.direction = 'to_client' THEN
      NEW.uploaded_by_staff := COALESCE(NEW.uploaded_by_staff, auth.uid());
    END IF;
  END IF;

  NEW.updated_at := now();
  RETURN NEW;
END; $function$
;

-- set_project_org_id()
CREATE OR REPLACE FUNCTION public.set_project_org_id()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
