-- signal_evaluation_disagreement(_evaluation_id uuid, _reason text)
CREATE OR REPLACE FUNCTION public.signal_evaluation_disagreement(_evaluation_id uuid, _reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _e RECORD;
BEGIN
  SELECT * INTO _e FROM evaluations WHERE id = _evaluation_id;
  IF _e.evaluatee_id <> auth.uid() THEN
    RAISE EXCEPTION 'Réservé au collaborateur évalué';
  END IF;
  IF _e.round_count < 2 THEN
    RAISE EXCEPTION 'Le désaccord ne peut être signalé qu''après deux échanges avec votre évaluateur';
  END IF;
  IF _reason IS NULL OR length(trim(_reason)) < 10 THEN
    RAISE EXCEPTION 'Le motif du désaccord est obligatoire';
  END IF;

  UPDATE evaluations
     SET disagreement = true, disagreement_reason = _reason,
         status = 'observations_recues', observed_at = now(), updated_at = now()
   WHERE id = _evaluation_id;

  INSERT INTO evaluation_exchanges (evaluation_id, round, actor_id, action, message)
  VALUES (_evaluation_id, _e.round_count, auth.uid(), 'desaccord', _reason);

  -- L'évaluateur et la direction sont informés
  INSERT INTO notifications (user_id, type, title, content, entity_type, entity_id, priority)
  SELECT p.id, 'evaluation_disagreement', 'Désaccord signalé sur une évaluation',
    COALESCE((SELECT full_name FROM profiles WHERE id = _e.evaluatee_id), 'Un collaborateur') ||
    ' maintient son désaccord après deux échanges.',
    'evaluation', _evaluation_id, 'high'
  FROM profiles p
  WHERE p.id = _e.evaluator_id
     OR (p.organization_id = _e.organization_id AND p.grade_level <= 2);

  RETURN jsonb_build_object('success', true);
END; $function$
;

-- staffing_grants_access()
CREATE OR REPLACE FUNCTION public.staffing_grants_access()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  -- L'affectation prend effet dès sa création. Seule une annulation la
  -- défait, et c'est staffing_revokes_access() qui s'en charge.
  IF NEW.status = 'cancelled' THEN
    RETURN NEW;
  END IF;

  INSERT INTO public.mission_members (mission_id, user_id, role)
  VALUES (NEW.mission_id, NEW.user_id, public.staffing_role_to_member(NEW.role))
  ON CONFLICT (mission_id, user_id) DO UPDATE
    SET role = EXCLUDED.role          -- le changement de rôle se répercute
    WHERE mission_members.role IS DISTINCT FROM EXCLUDED.role;

  -- project_members garde son propre vocabulaire : 'lead' ou 'member'.
  IF NEW.project_id IS NOT NULL THEN
    INSERT INTO public.project_members (project_id, user_id, role)
    VALUES (NEW.project_id, NEW.user_id,
            CASE WHEN NEW.role IN ('associe','directeur_mission','chef_mission')
                 THEN 'lead' ELSE 'member' END)
    ON CONFLICT (project_id, user_id) DO NOTHING;
  END IF;

  RETURN NEW;
END; $function$
;

-- staffing_revokes_access()
CREATE OR REPLACE FUNCTION public.staffing_revokes_access()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _m RECORD;
BEGIN
  IF NEW.status <> 'cancelled' OR OLD.status = 'cancelled' THEN
    RETURN NEW;
  END IF;

  -- Une autre affectation vivante sur la même mission : on ne touche à rien.
  IF EXISTS (SELECT 1 FROM staffing_assignments s
             WHERE s.mission_id = NEW.mission_id AND s.user_id = NEW.user_id
               AND s.id <> NEW.id
               AND s.status <> 'cancelled') THEN
    RETURN NEW;
  END IF;

  -- La personne encadre la mission : elle n'en sort pas par une annulation
  -- de planning.
  SELECT chief_id, director_id INTO _m FROM missions WHERE id = NEW.mission_id;
  IF NEW.user_id IN (_m.chief_id, _m.director_id) THEN
    RETURN NEW;
  END IF;

  -- Du temps a déjà été imputé : le travail a eu lieu, il doit rester
  -- évaluable.
  IF EXISTS (SELECT 1 FROM time_entries t
             WHERE t.mission_id = NEW.mission_id AND t.user_id = NEW.user_id) THEN
    RETURN NEW;
  END IF;

  -- Une évaluation est déjà ouverte : la retirer laisserait une évaluation
  -- orpheline.
  IF EXISTS (SELECT 1 FROM evaluations e
             WHERE e.mission_id = NEW.mission_id AND e.evaluatee_id = NEW.user_id) THEN
    RETURN NEW;
  END IF;

  DELETE FROM mission_members
   WHERE mission_id = NEW.mission_id AND user_id = NEW.user_id;

  DELETE FROM evaluation_assignments
   WHERE mission_id = NEW.mission_id AND evaluatee_id = NEW.user_id
     AND status = 'a_faire'
     AND NOT EXISTS (SELECT 1 FROM evaluations e2
                     WHERE e2.assignment_id = evaluation_assignments.id);

  RETURN NEW;
END; $function$
;

-- staffing_role_to_member(_role text)
CREATE OR REPLACE FUNCTION public.staffing_role_to_member(_role text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
AS $function$ SELECT _role $function$
;

