-- submit_evaluation_feedback(_feedback_id uuid, _overall smallint, _strengths text, _improvements text)
CREATE OR REPLACE FUNCTION public.submit_evaluation_feedback(_feedback_id uuid, _overall smallint, _strengths text DEFAULT NULL::text, _improvements text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _f RECORD;
BEGIN
  SELECT * INTO _f FROM evaluation_feedback WHERE id = _feedback_id;
  IF _f IS NULL THEN RAISE EXCEPTION 'Sollicitation introuvable'; END IF;
  IF _f.contributor_id <> auth.uid() THEN
    RAISE EXCEPTION 'Cette sollicitation ne vous est pas adressée';
  END IF;
  IF _f.status = 'rendu' THEN
    RAISE EXCEPTION 'Avis déjà rendu';
  END IF;
  IF _overall IS NULL OR _overall < 1 OR _overall > 5 THEN
    RAISE EXCEPTION 'L''appréciation doit être comprise entre 1 et 5';
  END IF;

  UPDATE evaluation_feedback
  SET overall = _overall, strengths = _strengths, improvements = _improvements,
      status = 'rendu', submitted_at = now()
  WHERE id = _feedback_id;
END; $function$
;

-- submit_evaluation_observations(_evaluation_id uuid, _comment text, _has_objection boolean)
CREATE OR REPLACE FUNCTION public.submit_evaluation_observations(_evaluation_id uuid, _comment text, _has_objection boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _e RECORD;
BEGIN
  SELECT * INTO _e FROM evaluations WHERE id = _evaluation_id;
  IF _e IS NULL THEN RAISE EXCEPTION 'Évaluation introuvable'; END IF;
  IF _e.evaluatee_id <> auth.uid() THEN
    RAISE EXCEPTION 'Seul le collaborateur évalué peut formuler des observations';
  END IF;
  IF _e.status <> 'envoyee' THEN
    RAISE EXCEPTION 'Cette évaluation n''attend pas vos observations';
  END IF;
  IF _has_objection AND (_comment IS NULL OR length(trim(_comment)) < 10) THEN
    RAISE EXCEPTION 'Une objection doit être motivée (10 caractères minimum)';
  END IF;

  UPDATE evaluations
     SET status = 'observations_recues',
         collaborator_comment = _comment,
         has_objection = _has_objection,
         observed_at = now(), acknowledged_at = COALESCE(acknowledged_at, now()),
         updated_at = now()
   WHERE id = _evaluation_id;

  INSERT INTO evaluation_exchanges (evaluation_id, round, actor_id, action, message)
  VALUES (_evaluation_id, _e.round_count, auth.uid(), 'observations', _comment);

  INSERT INTO notifications (user_id, type, title, content, entity_type, entity_id, priority)
  VALUES (_e.evaluator_id, 'evaluation_observed',
    CASE WHEN _has_objection THEN 'Objection sur une évaluation' ELSE 'Observations reçues' END,
    COALESCE((SELECT full_name FROM profiles WHERE id = _e.evaluatee_id), 'Le collaborateur') ||
    CASE WHEN _has_objection
         THEN ' conteste son évaluation. Examinez ses observations et révisez si nécessaire.'
         ELSE ' a pris connaissance de son évaluation et formulé ses observations.' END,
    'evaluation', _evaluation_id, CASE WHEN _has_objection THEN 'high' ELSE 'normal' END);

  RETURN jsonb_build_object('success', true, 'has_objection', _has_objection);
END; $function$
;

-- suggest_feedback_contributors(_evaluation_id uuid)
CREATE OR REPLACE FUNCTION public.suggest_feedback_contributors(_evaluation_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _e RECORD; _ee_grade int;
BEGIN
  SELECT * INTO _e FROM evaluations WHERE id = _evaluation_id;
  IF _e IS NULL OR _e.evaluator_id <> auth.uid() THEN
    RAISE EXCEPTION 'Accès refusé';
  END IF;

  -- Même règle que request_evaluation_feedback : proposer des
  -- contributeurs pour une évaluation qui les refusera ensuite
  -- enverrait l'évaluateur dans un mur.
  SELECT grade_level INTO _ee_grade FROM profiles WHERE id = _e.evaluatee_id;
  IF COALESCE(_ee_grade, 99) > 4 THEN
    RETURN '[]'::jsonb;
  END IF;

  RETURN COALESCE((
    SELECT jsonb_agg(jsonb_build_object(
      'user_id', s.evaluator_id,
      'nom', p.full_name, 'grade', p.grade,
      'nb_missions', s.nb, 'score_moyen', ROUND(s.moy, 2),
      'deja_sollicite', EXISTS (
        SELECT 1 FROM evaluation_feedback f
        WHERE f.evaluation_id = _evaluation_id AND f.contributor_id = s.evaluator_id)
    ) ORDER BY s.nb DESC)
    FROM (
      SELECT ev.evaluator_id, COUNT(*) AS nb, AVG(ev.weighted_score) AS moy
      FROM evaluations ev
      WHERE ev.evaluatee_id = _e.evaluatee_id AND ev.eval_type = 'mission'
        AND ev.status IN ('validee','cloturee') AND ev.exercice = _e.exercice
        AND ev.evaluator_id <> auth.uid()
      GROUP BY ev.evaluator_id
    ) s
    JOIN profiles p ON p.id = s.evaluator_id
  ), '[]'::jsonb);
END; $function$
;

-- super_admin_change_plan(_org_id uuid, _new_plan text, _max_users integer, _max_storage_gb integer, _new_price numeric, _reason text)
CREATE OR REPLACE FUNCTION public.super_admin_change_plan(_org_id uuid, _new_plan text, _max_users integer, _max_storage_gb integer, _new_price numeric DEFAULT NULL::numeric, _reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _old RECORD;
BEGIN
  IF NOT public.is_platform_admin('admin') THEN
    RAISE EXCEPTION 'Accès refusé : action réservée aux administrateurs';
  END IF;

  SELECT o.subscription_plan, o.name, o.max_users, o.max_storage_gb INTO _old
  FROM organizations o WHERE o.id = _org_id;

  IF _old IS NULL THEN RAISE EXCEPTION 'Organisation introuvable'; END IF;

  -- Garde-fou : ne pas descendre sous l'usage réel
  IF (SELECT COUNT(*) FROM profiles p WHERE p.organization_id = _org_id) > _max_users THEN
    RAISE EXCEPTION 'Impossible : le cabinet compte % utilisateurs, supérieur à la limite du plan (%)',
      (SELECT COUNT(*) FROM profiles p WHERE p.organization_id = _org_id), _max_users;
  END IF;

  UPDATE organizations
     SET subscription_plan = _new_plan,
         max_users = _max_users,
         max_storage_gb = _max_storage_gb,
         updated_at = now()
   WHERE id = _org_id;

  INSERT INTO plan_changes_log
    (organization_id, old_plan, new_plan, new_price, changed_by, changed_by_email, reason)
  VALUES (_org_id, _old.subscription_plan, _new_plan, _new_price, auth.uid(),
          (SELECT p.email FROM profiles p WHERE p.id = auth.uid()), _reason);

  PERFORM public.log_super_admin_action('plan_changed', 'organization', _org_id, _old.name,
    jsonb_build_object('from', _old.subscription_plan, 'to', _new_plan, 'reason', _reason));

  -- Informer les administrateurs du cabinet
  INSERT INTO notifications (user_id, type, title, content, entity_type, entity_id, priority)
  SELECT p.id, 'plan_changed', 'Votre abonnement a été mis à jour',
    'Votre organisation est passée au plan ' || _new_plan ||
    ' (' || _max_users || ' utilisateurs, ' || _max_storage_gb || ' Go).',
    'organization', _org_id, 'normal'
  FROM profiles p WHERE p.organization_id = _org_id AND p.grade_level <= 2;

  RETURN jsonb_build_object('success', true, 'old_plan', _old.subscription_plan, 'new_plan', _new_plan);
END;
$function$
;

-- super_admin_creer_cabinet(_nom text, _offre text, _email_da text, _nom_da text, _reglages jsonb)
CREATE OR REPLACE FUNCTION public.super_admin_creer_cabinet(_nom text, _offre text, _email_da text, _nom_da text DEFAULT NULL::text, _reglages jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _plan   public.subscription_plans;
  _nom_p  text := NULLIF(trim(_nom), '');
  _email  text := lower(trim(_email_da));
  _base   text;
  _slug   text;
  _essai  int := 0;
  _org    public.organizations;
  _jeton  text := replace(gen_random_uuid()::text, '-', '')
               || replace(gen_random_uuid()::text, '-', '');   -- 64 caractères tirés par le serveur
BEGIN
  IF NOT public.is_platform_admin('admin') THEN
    RAISE EXCEPTION 'Accès refusé : seul un administrateur de la plateforme crée un cabinet.';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.profiles WHERE id = auth.uid()) THEN
    RAISE EXCEPTION 'Votre compte d''administrateur n''a pas de profil : impossible de signer l''invitation.';
  END IF;
  IF _nom_p IS NULL OR length(_nom_p) < 2 THEN
    RAISE EXCEPTION 'Le nom du cabinet est obligatoire.';
  END IF;
  IF _email IS NULL OR _email !~ '^[^@\s]+@[^@\s]+\.[^@\s]+$' THEN
    RAISE EXCEPTION 'Adresse du directeur associé invalide.';
  END IF;
  IF EXISTS (SELECT 1 FROM public.profiles WHERE lower(email) = _email) THEN
    RAISE EXCEPTION 'Cette adresse a déjà un compte Mission-DGC : choisissez-en une autre.';
  END IF;

  SELECT * INTO _plan FROM public.subscription_plans
  WHERE code = _offre AND is_active;
  IF _plan.id IS NULL THEN
    RAISE EXCEPTION 'Offre inconnue ou inactive : %', _offre;
  END IF;

  _base := trim(both '-' from lower(regexp_replace(_nom_p, '[^a-zA-Z0-9]+', '-', 'g')));
  IF length(_base) < 2 THEN _base := 'cabinet'; END IF;
  _slug := _base;
  WHILE EXISTS (SELECT 1 FROM public.organizations WHERE slug = _slug) LOOP
    _essai := _essai + 1;
    _slug  := _base || '-' || (_essai + 1);
  END LOOP;

  INSERT INTO public.organizations (name, slug, subscription_plan, max_users, max_storage_gb, settings)
  VALUES (_nom_p, _slug, _plan.code, _plan.max_users, _plan.max_storage_gb, COALESCE(_reglages, '{}'::jsonb))
  RETURNING * INTO _org;

  INSERT INTO public.invitations (organization_id, email, invited_by, grade, token)
  VALUES (_org.id, _email, auth.uid(), 'DA', _jeton);

  PERFORM public.log_super_admin_action('organization_created', 'organization', _org.id, _org.name,
    jsonb_build_object('offre', _plan.code, 'directeur_associe', _email, 'nom', _nom_da));

  RETURN jsonb_build_object(
    'organization_id', _org.id,
    'slug',            _org.slug,
    'nom',             _org.name,
    'offre',           _plan.code,
    'email_da',        _email,
    'jeton',           _jeton
  );
END;
$function$
;

-- super_admin_fix_org(_org_id uuid, _action text, _params jsonb)
CREATE OR REPLACE FUNCTION public.super_admin_fix_org(_org_id uuid, _action text, _params jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _fixed integer := 0;
  _detail jsonb := '{}'::jsonb;
BEGIN
  IF NOT public.is_platform_admin('admin') THEN
    RAISE EXCEPTION 'Accès refusé : action réservée aux administrateurs';
  END IF;

  IF _action = 'backfill_org_ids' THEN
    -- Répare les enregistrements orphelins (cause fréquente d'écrans vides)
    UPDATE missions m SET organization_id = _org_id
     WHERE m.organization_id IS NULL
       AND EXISTS (SELECT 1 FROM mission_members mm
                   JOIN profiles p ON p.id = mm.user_id
                   WHERE mm.mission_id = m.id AND p.organization_id = _org_id);
    GET DIAGNOSTICS _fixed = ROW_COUNT;
    _detail := jsonb_build_object('missions_fixed', _fixed);

  ELSIF _action = 'reset_grade' THEN
    -- Redonne un grade à un utilisateur bloqué
    UPDATE profiles
       SET grade = COALESCE(_params->>'grade', 'AUD'),
           grade_level = COALESCE((_params->>'grade_level')::integer, 6)
     WHERE id = (_params->>'user_id')::uuid AND organization_id = _org_id;
    GET DIAGNOSTICS _fixed = ROW_COUNT;
    _detail := jsonb_build_object('users_fixed', _fixed);

  ELSIF _action = 'seed_referentials' THEN
    PERFORM public.seed_obligation_types(_org_id);
    PERFORM public.seed_obligation_documents(_org_id);
    _detail := jsonb_build_object('referentials', 'seeded');

  ELSE
    RAISE EXCEPTION 'Action inconnue : %', _action;
  END IF;

  PERFORM public.log_super_admin_action('org_fix', 'organization', _org_id, _action, _detail);
  RETURN jsonb_build_object('success', true, 'action', _action, 'detail', _detail);
END; $function$
;

-- super_admin_get_all_orgs()
CREATE OR REPLACE FUNCTION public.super_admin_get_all_orgs()
 RETURNS TABLE(id uuid, name text, slug text, subscription_plan text, max_users integer, max_storage_gb integer, is_active boolean, suspended_at timestamp with time zone, trial_ends_at date, country text, city text, billing_email text, created_at timestamp with time zone, user_count bigint, mission_count bigint, client_count bigint, storage_used_mb numeric, last_activity timestamp with time zone)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NOT public.is_platform_admin('support') THEN
    RAISE EXCEPTION 'Accès refusé : réservé aux administrateurs plateforme';
  END IF;

  RETURN QUERY
  SELECT
    o.id, o.name, o.slug, o.subscription_plan,
    o.max_users, o.max_storage_gb,
    o.is_active, o.suspended_at, o.trial_ends_at,
    o.country, o.city, o.billing_email,
    o.created_at,
    (SELECT COUNT(*) FROM profiles p WHERE p.organization_id = o.id),
    (SELECT COUNT(*) FROM missions m WHERE m.organization_id = o.id),
    (SELECT COUNT(*) FROM clients c WHERE c.organization_id = o.id),
    COALESCE((SELECT ROUND(SUM((so.metadata->>'size')::numeric) / 1048576.0, 1)
                FROM storage.objects so
               WHERE (storage.foldername(so.name))[1] = o.id::text), 0),
    (SELECT MAX(p.last_seen_at) FROM profiles p WHERE p.organization_id = o.id)
  FROM organizations o
  ORDER BY o.created_at DESC;
END;
$function$
;

-- super_admin_growth(_months integer)
CREATE OR REPLACE FUNCTION public.super_admin_growth(_months integer DEFAULT 12)
 RETURNS TABLE(period text, new_orgs bigint, new_users bigint, cumulative_orgs bigint)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NOT public.is_platform_admin('support') THEN
    RAISE EXCEPTION 'Accès refusé : réservé aux administrateurs plateforme';
  END IF;

  RETURN QUERY
  WITH months AS (
    SELECT generate_series(
      date_trunc('month', CURRENT_DATE) - make_interval(months => _months - 1),
      date_trunc('month', CURRENT_DATE), '1 month'
    )::date AS m
  )
  SELECT
    to_char(months.m, 'YYYY-MM'),
    (SELECT COUNT(*) FROM organizations o
      WHERE date_trunc('month', o.created_at)::date = months.m),
    (SELECT COUNT(*) FROM profiles p
      WHERE date_trunc('month', p.created_at)::date = months.m),
    (SELECT COUNT(*) FROM organizations o
      WHERE o.created_at < months.m + INTERVAL '1 month')
  FROM months ORDER BY months.m;
END;
$function$
;

-- super_admin_health()
CREATE OR REPLACE FUNCTION public.super_admin_health()
 RETURNS TABLE(org_id uuid, org_name text, subscription_plan text, users_used bigint, users_max integer, users_pct numeric, storage_used_gb numeric, storage_max_gb integer, storage_pct numeric, alert_level text)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NOT public.is_platform_admin('support') THEN
    RAISE EXCEPTION 'Accès refusé : réservé aux administrateurs plateforme';
  END IF;

  RETURN QUERY
  WITH usage AS (
    SELECT o.id, o.name, o.subscription_plan, o.max_users, o.max_storage_gb,
      (SELECT COUNT(*) FROM profiles p WHERE p.organization_id = o.id) AS u_used,
      COALESCE((SELECT ROUND(SUM((so.metadata->>'size')::numeric)/1073741824.0, 2)
                  FROM storage.objects so
                 WHERE (storage.foldername(so.name))[1] = o.id::text), 0) AS s_used
    FROM organizations o WHERE o.is_active
  )
  SELECT u.id, u.name, u.subscription_plan,
    u.u_used, u.max_users,
    CASE WHEN u.max_users > 0 THEN ROUND(u.u_used::numeric / u.max_users * 100) ELSE 0 END,
    u.s_used, u.max_storage_gb,
    CASE WHEN u.max_storage_gb > 0 THEN ROUND(u.s_used / u.max_storage_gb * 100) ELSE 0 END,
    CASE
      WHEN (u.max_users > 0 AND u.u_used >= u.max_users)
        OR (u.max_storage_gb > 0 AND u.s_used >= u.max_storage_gb) THEN 'depassement'
      WHEN (u.max_users > 0 AND u.u_used::numeric / u.max_users >= 0.8)
        OR (u.max_storage_gb > 0 AND u.s_used / u.max_storage_gb >= 0.8) THEN 'attention'
      ELSE 'ok'
    END
  FROM usage u
  ORDER BY 10, 6 DESC;
END;
$function$
;

-- super_admin_kpis()
CREATE OR REPLACE FUNCTION public.super_admin_kpis()
 RETURNS TABLE(total_orgs bigint, active_orgs bigint, suspended_orgs bigint, trial_orgs bigint, total_users bigint, active_users_30d bigint, total_missions bigint, total_clients bigint, new_orgs_30d bigint, storage_total_gb numeric)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NOT public.is_platform_admin('support') THEN
    RAISE EXCEPTION 'Accès refusé : réservé aux administrateurs plateforme';
  END IF;

  RETURN QUERY
  SELECT
    (SELECT COUNT(*) FROM organizations),
    (SELECT COUNT(*) FROM organizations WHERE is_active),
    (SELECT COUNT(*) FROM organizations WHERE NOT is_active),
    (SELECT COUNT(*) FROM organizations WHERE trial_ends_at >= CURRENT_DATE),
    (SELECT COUNT(*) FROM profiles),
    (SELECT COUNT(*) FROM profiles WHERE last_seen_at >= now() - INTERVAL '30 days'),
    (SELECT COUNT(*) FROM missions),
    (SELECT COUNT(*) FROM clients),
    (SELECT COUNT(*) FROM organizations WHERE created_at >= now() - INTERVAL '30 days'),
    COALESCE((SELECT ROUND(SUM((metadata->>'size')::numeric) / 1073741824.0, 2)
                FROM storage.objects), 0);
END;
$function$
;

-- super_admin_org_detail(_org_id uuid)
CREATE OR REPLACE FUNCTION public.super_admin_org_detail(_org_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _result jsonb;
BEGIN
  IF NOT public.is_platform_admin('support') THEN
    RAISE EXCEPTION 'Accès refusé : réservé aux administrateurs plateforme';
  END IF;

  SELECT jsonb_build_object(
    'organization', to_jsonb(o.*),
    'usage', jsonb_build_object(
      'users',        (SELECT COUNT(*) FROM profiles p WHERE p.organization_id = o.id),
      'missions',     (SELECT COUNT(*) FROM missions m WHERE m.organization_id = o.id),
      'projects',     (SELECT COUNT(*) FROM projects pj WHERE pj.organization_id = o.id),
      'clients',      (SELECT COUNT(*) FROM clients c WHERE c.organization_id = o.id),
      'documents',    (SELECT COUNT(*) FROM documents d WHERE d.organization_id = o.id),
      'storage_mb',   COALESCE((SELECT ROUND(SUM((so.metadata->>'size')::numeric)/1048576.0, 1)
                                  FROM storage.objects so
                                 WHERE (storage.foldername(so.name))[1] = o.id::text), 0)
    ),
    -- Membres : identité et rôle uniquement, aucune donnée métier
    'members', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
        'id', p.id, 'full_name', p.full_name, 'email', p.email,
        'grade', p.grade, 'grade_level', p.grade_level,
        'is_online', p.is_online, 'last_seen_at', p.last_seen_at,
        'created_at', p.created_at
      ) ORDER BY p.grade_level, p.full_name)
      FROM profiles p WHERE p.organization_id = o.id
    ), '[]'::jsonb),
    'plan_history', COALESCE((
      SELECT jsonb_agg(to_jsonb(pc.*) ORDER BY pc.created_at DESC)
      FROM plan_changes_log pc WHERE pc.organization_id = o.id
    ), '[]'::jsonb)
  ) INTO _result
  FROM organizations o WHERE o.id = _org_id;

  IF _result IS NULL THEN
    RAISE EXCEPTION 'Organisation introuvable';
  END IF;

  PERFORM public.log_super_admin_action('org_viewed', 'organization', _org_id,
    (_result->'organization'->>'name'));

  RETURN _result;
END;
$function$
;

-- super_admin_org_diagnostic(_org_id uuid)
CREATE OR REPLACE FUNCTION public.super_admin_org_diagnostic(_org_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _result jsonb;
BEGIN
  IF NOT public.is_platform_admin('support') THEN
    RAISE EXCEPTION 'Accès refusé : réservé aux administrateurs plateforme';
  END IF;

  SELECT jsonb_build_object(
    'organization', jsonb_build_object(
      'id', o.id, 'name', o.name, 'plan', o.subscription_plan,
      'is_active', o.is_active, 'suspended_at', o.suspended_at,
      'suspension_reason', o.suspension_reason,
      'created_at', o.created_at, 'trial_ends_at', o.trial_ends_at
    ),

    -- Santé de la configuration : les manques qui cassent l'usage
    'health_checks', jsonb_build_object(
      'users_without_grade', (
        SELECT COUNT(*) FROM profiles p
        WHERE p.organization_id = _org_id AND (p.grade IS NULL OR p.grade_level IS NULL)),
      'missions_without_director', (
        SELECT COUNT(*) FROM missions m
        WHERE m.organization_id = _org_id AND m.director_id IS NULL),
      'projects_without_lead', (
        SELECT COUNT(*) FROM projects pj
        WHERE pj.organization_id = _org_id AND pj.lead_id IS NULL),
      'orphan_records', (
        SELECT COUNT(*) FROM missions m
        WHERE m.organization_id IS NULL
          AND EXISTS (SELECT 1 FROM mission_members mm
                      JOIN profiles p ON p.id = mm.user_id
                      WHERE mm.mission_id = m.id AND p.organization_id = _org_id)),
      'has_daily_rates', EXISTS (
        SELECT 1 FROM daily_rates dr WHERE dr.organization_id = _org_id),
      'has_obligation_types', EXISTS (
        SELECT 1 FROM obligation_types ot WHERE ot.organization_id = _org_id)
    ),

    -- Activité récente : ce que les utilisateurs ont fait
    'recent_activity', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
        'created_at', al.created_at, 'action', al.action,
        'entity_type', al.entity_type, 'user_name', p.full_name,
        'metadata', al.metadata
      ) ORDER BY al.created_at DESC)
      FROM (SELECT * FROM activity_logs a
             WHERE a.organization_id = _org_id
             ORDER BY a.created_at DESC LIMIT 50) al
      LEFT JOIN profiles p ON p.id = al.user_id
    ), '[]'::jsonb),

    -- Connexions récentes : qui est actif, qui ne vient plus
    'recent_logins', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
        'full_name', p.full_name, 'email', p.email, 'grade', p.grade,
        'last_seen_at', p.last_seen_at, 'is_online', p.is_online
      ) ORDER BY p.last_seen_at DESC NULLS LAST)
      FROM profiles p WHERE p.organization_id = _org_id LIMIT 20
    ), '[]'::jsonb),

    -- Volumétrie : pour repérer un blocage (0 mission = jamais démarré)
    'volumes', jsonb_build_object(
      'users', (SELECT COUNT(*) FROM profiles WHERE organization_id = _org_id),
      'missions', (SELECT COUNT(*) FROM missions WHERE organization_id = _org_id),
      'projects', (SELECT COUNT(*) FROM projects WHERE organization_id = _org_id),
      'tasks', (SELECT COUNT(*) FROM tasks WHERE organization_id = _org_id),
      'clients', (SELECT COUNT(*) FROM clients WHERE organization_id = _org_id),
      'documents', (SELECT COUNT(*) FROM documents WHERE organization_id = _org_id),
      'time_entries', (SELECT COUNT(*) FROM time_entries WHERE organization_id = _org_id),
      'portal_users', (SELECT COUNT(*) FROM portal_users WHERE organization_id = _org_id)
    )
  ) INTO _result
  FROM organizations o WHERE o.id = _org_id;

  IF _result IS NULL THEN RAISE EXCEPTION 'Organisation introuvable'; END IF;

  PERFORM public.log_super_admin_action('org_diagnostic', 'organization', _org_id,
    (_result->'organization'->>'name'));

  RETURN _result;
END; $function$
;

-- super_admin_search_users(_query text)
CREATE OR REPLACE FUNCTION public.super_admin_search_users(_query text)
 RETURNS TABLE(id uuid, full_name text, email text, grade text, grade_level integer, organization_id uuid, organization_name text, is_online boolean, last_seen_at timestamp with time zone, created_at timestamp with time zone)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NOT public.is_platform_admin('support') THEN
    RAISE EXCEPTION 'Accès refusé : réservé aux administrateurs plateforme';
  END IF;

  IF _query IS NULL OR length(trim(_query)) < 3 THEN
    RAISE EXCEPTION 'Saisissez au moins 3 caractères';
  END IF;

  PERFORM public.log_super_admin_action('user_search', 'search', NULL, _query);

  RETURN QUERY
  SELECT p.id, p.full_name, p.email, p.grade, p.grade_level,
         p.organization_id, o.name, p.is_online, p.last_seen_at, p.created_at
  FROM profiles p
  LEFT JOIN organizations o ON o.id = p.organization_id
  WHERE p.email ILIKE '%' || _query || '%'
     OR p.full_name ILIKE '%' || _query || '%'
  ORDER BY p.last_seen_at DESC NULLS LAST
  LIMIT 50;
END;
$function$
;

-- super_admin_tickets(_status text)
CREATE OR REPLACE FUNCTION public.super_admin_tickets(_status text DEFAULT NULL::text)
 RETURNS TABLE(id uuid, reference text, subject text, category text, priority text, status text, organization_id uuid, organization_name text, created_by_name text, created_by_email text, message_count bigint, last_message_at timestamp with time zone, created_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NOT public.is_platform_admin('support') THEN
    RAISE EXCEPTION 'Accès refusé';
  END IF;

  RETURN QUERY
  SELECT t.id, t.reference, t.subject, t.category, t.priority, t.status,
         t.organization_id, o.name, p.full_name, p.email,
         (SELECT COUNT(*) FROM support_ticket_messages m WHERE m.ticket_id = t.id),
         (SELECT MAX(m.created_at) FROM support_ticket_messages m WHERE m.ticket_id = t.id),
         t.created_at
  FROM support_tickets t
  LEFT JOIN organizations o ON o.id = t.organization_id
  LEFT JOIN profiles p ON p.id = t.created_by
  WHERE (_status IS NULL OR t.status = _status)
  ORDER BY
    CASE t.priority WHEN 'urgente' THEN 1 WHEN 'haute' THEN 2
                    WHEN 'normale' THEN 3 ELSE 4 END,
    t.created_at DESC;
END; $function$
;

-- super_admin_toggle_org(_org_id uuid, _activate boolean, _reason text)
CREATE OR REPLACE FUNCTION public.super_admin_toggle_org(_org_id uuid, _activate boolean, _reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _name text;
BEGIN
  IF NOT public.is_platform_admin('admin') THEN
    RAISE EXCEPTION 'Accès refusé : action réservée aux administrateurs';
  END IF;

  IF NOT _activate AND (_reason IS NULL OR length(trim(_reason)) < 5) THEN
    RAISE EXCEPTION 'Le motif de suspension est obligatoire';
  END IF;

  SELECT o.name INTO _name FROM organizations o WHERE o.id = _org_id;
  IF _name IS NULL THEN RAISE EXCEPTION 'Organisation introuvable'; END IF;

  UPDATE organizations
     SET is_active = _activate,
         suspended_at = CASE WHEN _activate THEN NULL ELSE now() END,
         suspension_reason = CASE WHEN _activate THEN NULL ELSE _reason END,
         updated_at = now()
   WHERE id = _org_id;

  PERFORM public.log_super_admin_action(
    CASE WHEN _activate THEN 'org_reactivated' ELSE 'org_suspended' END,
    'organization', _org_id, _name, jsonb_build_object('reason', _reason));

  INSERT INTO notifications (user_id, type, title, content, entity_type, entity_id, priority)
  SELECT p.id, 'org_status',
    CASE WHEN _activate THEN 'Compte réactivé' ELSE 'Compte suspendu' END,
    CASE WHEN _activate THEN 'Votre accès à Mission-DGC a été rétabli.'
         ELSE 'Votre accès a été suspendu. Motif : ' || _reason END,
    'organization', _org_id, 'high'
  FROM profiles p WHERE p.organization_id = _org_id AND p.grade_level <= 2;

  RETURN jsonb_build_object('success', true, 'is_active', _activate);
END;
$function$
;

-- super_admin_update_org(_org_id uuid, _billing_email text, _billing_contact text, _phone text, _country text, _city text, _trial_ends_at date, _internal_notes text)
CREATE OR REPLACE FUNCTION public.super_admin_update_org(_org_id uuid, _billing_email text DEFAULT NULL::text, _billing_contact text DEFAULT NULL::text, _phone text DEFAULT NULL::text, _country text DEFAULT NULL::text, _city text DEFAULT NULL::text, _trial_ends_at date DEFAULT NULL::date, _internal_notes text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _name text;
BEGIN
  IF NOT public.is_platform_admin('admin') THEN
    RAISE EXCEPTION 'Accès refusé : action réservée aux administrateurs';
  END IF;

  SELECT o.name INTO _name FROM organizations o WHERE o.id = _org_id;
  IF _name IS NULL THEN RAISE EXCEPTION 'Organisation introuvable'; END IF;

  UPDATE organizations SET
    billing_email   = COALESCE(_billing_email, billing_email),
    billing_contact = COALESCE(_billing_contact, billing_contact),
    phone           = COALESCE(_phone, phone),
    country         = COALESCE(_country, country),
    city            = COALESCE(_city, city),
    trial_ends_at   = COALESCE(_trial_ends_at, trial_ends_at),
    internal_notes  = COALESCE(_internal_notes, internal_notes),
    updated_at      = now()
  WHERE id = _org_id;

  PERFORM public.log_super_admin_action('org_updated', 'organization', _org_id, _name);
  RETURN jsonb_build_object('success', true);
END;
$function$
;

-- super_admin_upsert_plan(_code text, _name text, _price_monthly numeric, _max_users integer, _max_missions integer, _max_storage_gb integer, _features jsonb, _description text, _is_active boolean, _is_public boolean)
CREATE OR REPLACE FUNCTION public.super_admin_upsert_plan(_code text, _name text, _price_monthly numeric, _max_users integer, _max_missions integer, _max_storage_gb integer, _features jsonb DEFAULT '[]'::jsonb, _description text DEFAULT NULL::text, _is_active boolean DEFAULT true, _is_public boolean DEFAULT true)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _existing RECORD;
BEGIN
  IF NOT public.is_platform_admin('admin') THEN
    RAISE EXCEPTION 'Accès refusé : action réservée aux administrateurs';
  END IF;

  SELECT * INTO _existing FROM subscription_plans WHERE code = _code;

  INSERT INTO subscription_plans
    (code, name, description, price_monthly, max_users, max_missions,
     max_storage_gb, features, is_active, is_public)
  VALUES (_code, _name, _description, _price_monthly, _max_users, _max_missions,
          _max_storage_gb, _features, _is_active, _is_public)
  ON CONFLICT (code) DO UPDATE SET
    name = EXCLUDED.name,
    description = EXCLUDED.description,
    price_monthly = EXCLUDED.price_monthly,
    max_users = EXCLUDED.max_users,
    max_missions = EXCLUDED.max_missions,
    max_storage_gb = EXCLUDED.max_storage_gb,
    features = EXCLUDED.features,
    is_active = EXCLUDED.is_active,
    is_public = EXCLUDED.is_public,
    updated_at = now();

  PERFORM public.log_super_admin_action(
    CASE WHEN _existing IS NULL THEN 'plan_created' ELSE 'plan_updated' END,
    'plan', NULL, _code,
    jsonb_build_object('name', _name, 'price', _price_monthly,
                       'old_price', _existing.price_monthly));

  RETURN jsonb_build_object('success', true, 'code', _code);
END; $function$
;

-- supprimer_compte(_cible uuid, _par uuid, _motif text)
CREATE OR REPLACE FUNCTION public.supprimer_compte(_cible uuid, _par uuid, _motif text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _c        public.profiles;
  _par_nom  text;
  _archive  text;
  _rattache record;
  _efface   jsonb := '{}'::jsonb;
  _nb       integer;
BEGIN
  -- Un « oui » explicite est exigé : un résultat inconnu vaut refus.
  IF public.peut_supprimer_compte_par(_par, _cible) IS NOT TRUE THEN
    RAISE EXCEPTION 'interdit';
  END IF;

  SELECT * INTO _c FROM public.profiles WHERE id = _cible FOR UPDATE;
  SELECT full_name INTO _par_nom FROM public.profiles WHERE id = _par;
  _archive := 'compte-supprime-' || replace(_cible::text, '-', '') || '@supprime.invalid';

  INSERT INTO public.journal_des_suppressions
    (user_id, organization_id, email, nom, grade, supprime_par, supprime_par_nom, motif)
  VALUES
    (_c.id, _c.organization_id, _c.email, _c.full_name, _c.grade, _par, _par_nom, NULLIF(trim(_motif), ''));

  -- Rattachements et données personnelles : effacés.
  FOR _rattache IN
    SELECT * FROM (VALUES
      ('mission_members', 'user_id'), ('project_members', 'user_id'),
      ('committee_members', 'user_id'), ('conversation_members', 'user_id'),
      ('meeting_participants', 'user_id'), ('mailing_group_recipients', 'user_id'),
      ('document_shares', 'shared_with'), ('notifications', 'user_id'),
      ('notes', 'user_id'), ('user_skills', 'user_id'),
      ('user_availability', 'user_id'), ('user_sessions', 'user_id'),
      ('user_roles', 'user_id'), ('mots_de_passe_provisoires', 'user_id')
    ) AS t(nom_table, colonne)
  LOOP
    IF to_regclass('public.' || _rattache.nom_table) IS NOT NULL THEN
      EXECUTE format('DELETE FROM public.%I WHERE %I = $1', _rattache.nom_table, _rattache.colonne)
        USING _cible;
      GET DIAGNOSTICS _nb = ROW_COUNT;
      IF _nb > 0 THEN _efface := _efface || jsonb_build_object(_rattache.nom_table, _nb); END IF;
    END IF;
  END LOOP;

  -- Ses invitations encore ouvertes ne servent plus.
  UPDATE public.invitations SET expires_at = now()
  WHERE invited_by = _cible AND status = 'pending' AND (expires_at IS NULL OR expires_at > now());

  -- La fiche passe en archive : hors du cabinet, adresse libérée.
  UPDATE public.profiles SET
    organization_id = NULL,
    email           = _archive,
    phone           = NULL,
    avatar_url      = NULL,
    skills          = '[]'::jsonb,
    is_online       = false,
    supprime_le     = now(),
    supprime_par    = _par
  WHERE id = _cible;

  RETURN jsonb_build_object('email_archive', _archive, 'efface', _efface);
END;
$function$
;

-- sync_period_status_from_docs()
CREATE OR REPLACE FUNCTION public.sync_period_status_from_docs()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _period_id uuid := COALESCE(NEW.obligation_period_id, OLD.obligation_period_id);
  _total_required integer;
  _received_required integer;
  _current_status text;
BEGIN
  SELECT status INTO _current_status FROM obligation_periods WHERE id = _period_id;

  -- Ne pas écraser un statut avancé (saisie, révision, déposé...)
  IF _current_status NOT IN ('a_faire', 'pieces_attendues', 'pieces_recues') THEN
    RETURN NEW;
  END IF;

  SELECT
    COUNT(*) FILTER (WHERE is_required),
    COUNT(*) FILTER (WHERE is_required AND status = 'recue')
  INTO _total_required, _received_required
  FROM obligation_documents
  WHERE obligation_period_id = _period_id;

  IF _total_required > 0 AND _received_required = _total_required THEN
    UPDATE obligation_periods SET status = 'pieces_recues'
     WHERE id = _period_id AND status <> 'pieces_recues';
  ELSIF EXISTS (
    SELECT 1 FROM obligation_documents
    WHERE obligation_period_id = _period_id AND status IN ('deposee', 'recue')
  ) THEN
    UPDATE obligation_periods SET status = 'pieces_attendues'
     WHERE id = _period_id AND status = 'a_faire';
  END IF;

  RETURN NEW;
END; $function$
;

-- tache_executee_pas_redefinie()
CREATE OR REPLACE FUNCTION public.tache_executee_pas_redefinie()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _me uuid := auth.uid();
  _change text[] := ARRAY[]::text[];
  -- Les seuls statuts que l'executant peut poser lui-meme. POUR EN AJOUTER :
  -- completez cette liste.
  _statuts_executant text[] := ARRAY['todo','in_progress','in_review'];
BEGIN
  -- Hors session utilisateur (migration, tache de fond), on ne juge pas.
  IF _me IS NULL THEN RETURN NEW; END IF;

  -- La direction redefinit ce qu'elle veut.
  IF public.peut_piloter_la_tache(_me, OLD.id) THEN RETURN NEW; END IF;

  -- Pour les autres : seules les colonnes d'execution peuvent bouger.
  IF NEW.title           IS DISTINCT FROM OLD.title           THEN _change := _change || 'le titre'::text; END IF;
  IF NEW.description     IS DISTINCT FROM OLD.description     THEN _change := _change || 'la description'::text; END IF;
  IF NEW.priority        IS DISTINCT FROM OLD.priority        THEN _change := _change || 'la priorite'::text; END IF;
  IF NEW.project_id      IS DISTINCT FROM OLD.project_id      THEN _change := _change || 'le projet'::text; END IF;
  IF NEW.activity_id     IS DISTINCT FROM OLD.activity_id     THEN _change := _change || 'l''activite'::text; END IF;
  IF NEW.parent_task_id  IS DISTINCT FROM OLD.parent_task_id  THEN _change := _change || 'la tache parente'::text; END IF;
  IF NEW.start_date      IS DISTINCT FROM OLD.start_date      THEN _change := _change || 'la date de debut'::text; END IF;
  IF NEW.due_date        IS DISTINCT FROM OLD.due_date        THEN _change := _change || 'l''echeance'::text; END IF;
  IF NEW.estimated_hours IS DISTINCT FROM OLD.estimated_hours THEN _change := _change || 'la charge estimee'::text; END IF;
  IF NEW.compartment     IS DISTINCT FROM OLD.compartment     THEN _change := _change || 'le compartiment'::text; END IF;
  IF NEW.order_index     IS DISTINCT FROM OLD.order_index     THEN _change := _change || 'l''ordre'::text; END IF;
  IF NEW.tags            IS DISTINCT FROM OLD.tags            THEN _change := _change || 'les etiquettes'::text; END IF;
  IF NEW.organization_id IS DISTINCT FROM OLD.organization_id THEN _change := _change || 'le cabinet'::text; END IF;
  IF NEW.created_by      IS DISTINCT FROM OLD.created_by      THEN _change := _change || 'l''auteur'::text; END IF;

  IF array_length(_change, 1) > 0 THEN
    RAISE EXCEPTION
      'Vous executez cette tache, vous ne la redefinissez pas : % releve du chef de mission. Vous pouvez avancer le statut, pointer vos heures et soumettre a revue.',
      array_to_string(_change, ', ');
  END IF;

  -- L'executant travaille et soumet ; il ne valide pas son propre travail.
  IF NEW.status IS DISTINCT FROM OLD.status
     AND NOT (NEW.status = ANY (_statuts_executant)) THEN
    RAISE EXCEPTION
      'Vous ne pouvez pas porter la tache a « % » : la revue et la validation reviennent au chef de mission. Portez-la a « in_review » pour la soumettre.',
      NEW.status;
  END IF;

  RETURN NEW;
END $function$
;

-- taches_imputables(_user_id uuid)
CREATE OR REPLACE FUNCTION public.taches_imputables(_user_id uuid DEFAULT NULL::uuid)
 RETURNS TABLE(tache_id uuid, intitule text, tache_generale boolean, mission_id uuid, mission text, projet text, m_est_affecte boolean, statut text, echeance date)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  WITH moi AS (SELECT COALESCE(_user_id, auth.uid()) AS id)
  SELECT t.id,
         t.title,
         (t.project_id IS NULL) AS tache_generale,
         p.mission_id,
         m.name,
         p.name,
         EXISTS (SELECT 1 FROM public.task_assignments ta
                  WHERE ta.task_id = t.id AND ta.user_id = (SELECT id FROM moi)),
         t.status,
         t.due_date
  FROM public.tasks t
  LEFT JOIN public.projects p ON p.id = t.project_id
  LEFT JOIN public.missions m ON m.id = p.mission_id
  JOIN public.profiles pr ON pr.id = (SELECT id FROM moi)
  WHERE t.organization_id = pr.organization_id
    AND t.status NOT IN ('completed','cancelled')
    AND (
      -- tache_generale : aucun projet, donc aucune mission. Imputable par tous.
      t.project_id IS NULL
      -- tache de mission : il faut avoir le droit de la voir.
      OR public.can_access_task((SELECT id FROM moi), t.id)
    )
  ORDER BY (t.project_id IS NULL) DESC, m.name NULLS FIRST, p.name, t.due_date NULLS LAST, t.title;
$function$
;

-- tracer_changement_de_grade()
CREATE OR REPLACE FUNCTION public.tracer_changement_de_grade()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _g RECORD; _ex smallint;
BEGIN
  IF NEW.grade IS NOT DISTINCT FROM OLD.grade
     AND NEW.grade_echelon IS NOT DISTINCT FROM OLD.grade_echelon
     AND NEW.practice IS NOT DISTINCT FROM OLD.practice THEN
    RETURN NEW;
  END IF;

  IF NEW.organization_id IS NULL OR NEW.practice IS NULL THEN
    RETURN NEW;   -- rien a historiser d'exploitable
  END IF;

  SELECT g.maps_to_grade AS grade, g.echelon, g.rank INTO _g
  FROM evaluation_grades g
  WHERE g.organization_id = NEW.organization_id
    AND g.practice = NEW.practice
    AND lower(btrim(g.echelon)) = lower(btrim(COALESCE(NEW.grade_echelon, '')))
  LIMIT 1;

  IF _g.echelon IS NULL THEN
    RETURN NEW;   -- echelon non reconnu : aucun rang a inscrire
  END IF;

  -- Si le dernier etat connu est deja celui-la, il n'y a rien a consigner :
  -- c'est le cas juste apres une promotion, qui a deja inscrit sa ligne.
  IF EXISTS (
    SELECT 1 FROM (
      SELECT h.grade_echelon, h.practice FROM grade_history h
      WHERE h.user_id = NEW.id
      ORDER BY h.effective_from DESC, h.decided_at DESC LIMIT 1) dernier
    WHERE lower(btrim(dernier.grade_echelon)) = lower(btrim(_g.echelon))
      AND dernier.practice = NEW.practice
  ) THEN
    RETURN NEW;
  END IF;

  _ex := public.fiscal_exercice(CURRENT_DATE, NEW.organization_id);

  INSERT INTO grade_history (organization_id, user_id, practice, grade,
                             grade_echelon, rank, effective_from, exercice,
                             motif, decided_by, origine)
  VALUES (NEW.organization_id, NEW.id, NEW.practice, _g.grade,
          _g.echelon, _g.rank, CURRENT_DATE, _ex,
          'modification directe de la fiche', auth.uid(), 'modification_fiche');

  RETURN NEW;
END; $function$
;

-- update_updated_at_column()
CREATE OR REPLACE FUNCTION public.update_updated_at_column()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  NEW.updated_at = now();
  RETURN NEW;
END;
$function$
;

-- upsert_activity_report(_report_date date, _first_activity timestamp with time zone, _last_activity timestamp with time zone, _active_seconds integer, _idle_seconds integer, _professional_seconds integer, _category_breakdown jsonb, _top_apps jsonb, _files_synced integer)
CREATE OR REPLACE FUNCTION public.upsert_activity_report(_report_date date, _first_activity timestamp with time zone, _last_activity timestamp with time zone, _active_seconds integer, _idle_seconds integer, _professional_seconds integer, _category_breakdown jsonb, _top_apps jsonb, _files_synced integer DEFAULT 0)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _report_id uuid;
  _org_id uuid;
BEGIN
  SELECT organization_id INTO _org_id FROM profiles WHERE id = auth.uid();

  INSERT INTO activity_reports (
    user_id, organization_id, report_date, first_activity, last_activity,
    active_seconds, idle_seconds, professional_seconds, category_breakdown, top_apps, files_synced
  )
  VALUES (
    auth.uid(), _org_id, _report_date, _first_activity, _last_activity,
    _active_seconds, _idle_seconds, _professional_seconds, _category_breakdown, _top_apps, _files_synced
  )
  ON CONFLICT (user_id, report_date) DO UPDATE SET
    last_activity = EXCLUDED.last_activity,
    active_seconds = EXCLUDED.active_seconds,
    idle_seconds = EXCLUDED.idle_seconds,
    professional_seconds = EXCLUDED.professional_seconds,
    category_breakdown = EXCLUDED.category_breakdown,
    top_apps = EXCLUDED.top_apps,
    files_synced = EXCLUDED.files_synced,
    updated_at = now()
  RETURNING id INTO _report_id;

  RETURN _report_id;
END;
$function$
;

-- validate_evaluation(_evaluation_id uuid, _final_comment text)
CREATE OR REPLACE FUNCTION public.validate_evaluation(_evaluation_id uuid, _final_comment text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _e RECORD; _res jsonb; _me RECORD;
BEGIN
  SELECT * INTO _e FROM evaluations WHERE id = _evaluation_id;
  IF _e IS NULL THEN RAISE EXCEPTION 'Évaluation introuvable'; END IF;

  SELECT p.id, p.organization_id, p.grade INTO _me
  FROM profiles p WHERE p.id = auth.uid();

  -- L'évaluateur note, le collaborateur observe, l'entretien a lieu, le
  -- Directeur Associé valide. L'évaluateur ne valide plus sa propre
  -- évaluation, sauf s'il est lui-même DA.
  IF _me.organization_id IS DISTINCT FROM _e.organization_id
     OR COALESCE(_me.grade, '') <> 'DA' THEN
    RAISE EXCEPTION 'Seul un Directeur Associé valide une évaluation';
  END IF;

  IF _e.status NOT IN ('observations_recues', 'revisee', 'envoyee') THEN
    RAISE EXCEPTION 'Cette évaluation ne peut pas être validée dans son état actuel';
  END IF;

  -- Le collaborateur doit avoir eu l'occasion de s'exprimer
  IF _e.observed_at IS NULL THEN
    RAISE EXCEPTION 'Le collaborateur doit d''abord avoir formulé ses observations';
  END IF;

  _res := public.compute_evaluation_score(_evaluation_id);

  UPDATE evaluations
     SET status = 'validee', validated_at = now(), validated_by = auth.uid(),
         evaluator_comment = COALESCE(_final_comment, evaluator_comment),
         updated_at = now()
   WHERE id = _evaluation_id;

  UPDATE evaluation_assignments SET status = 'terminee' WHERE id = _e.assignment_id;

  RETURN jsonb_build_object('success', true,
    'weighted_score', _res->>'weighted_score',
    'validee_par', (SELECT full_name FROM profiles WHERE id = auth.uid()));
END; $function$
;

-- validation_par_le_da()
CREATE OR REPLACE FUNCTION public.validation_par_le_da()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _me uuid := auth.uid();
BEGIN
  -- Hors session utilisateur (migration, tache de fond), on ne juge pas.
  IF _me IS NULL THEN RETURN NEW; END IF;

  -- Une imputation APPROUVEE est un constat : elle ne se reecrit plus, sauf
  -- par celui qui l'a approuvee — le directeur associe.
  IF TG_OP = 'UPDATE' AND OLD.status = 'approved'
     AND NOT public.est_directeur_associe(_me) THEN
    RAISE EXCEPTION 'Cette imputation est validee : elle ne se modifie plus. Seul le directeur associe peut la rouvrir.';
  END IF;

  -- Valider ou refuser : le directeur associe, et lui seul.
  IF NEW.status IN ('approved','rejected')
     AND (TG_OP = 'INSERT' OR NEW.status IS DISTINCT FROM OLD.status) THEN

    IF NOT public.est_directeur_associe(_me) THEN
      RAISE EXCEPTION 'Valider ou refuser une feuille de temps revient au directeur associe.';
    END IF;

    -- On trace qui a valide, et quand, sans se fier a ce que le front envoie.
    NEW.reviewer_id := _me;
    NEW.reviewed_at := now();
  END IF;

  -- On n'impute pas du temps au nom de quelqu'un d'autre.
  IF TG_OP = 'INSERT' AND NEW.user_id <> _me
     AND NOT public.est_directeur_associe(_me) THEN
    RAISE EXCEPTION 'On n''impute pas du temps au nom d''un autre collaborateur.';
  END IF;

  RETURN NEW;
END $function$
;


-- ═══════════════════════════════════════════════════════════════════════════
--  2. RLS ACTIVÉE (89)
--  Les tables protégées par des règles d'accès.
-- ═══════════════════════════════════════════════════════════════════════════

-- actions_elementaires
ALTER TABLE public.actions_elementaires ENABLE ROW LEVEL SECURITY;

-- activities
ALTER TABLE public.activities ENABLE ROW LEVEL SECURITY;

