-- actions_elementaires / actions_select
DROP POLICY IF EXISTS actions_select ON public.actions_elementaires;
CREATE POLICY actions_select ON public.actions_elementaires AS PERMISSIVE FOR SELECT TO public
  USING ((EXISTS ( SELECT 1
   FROM time_entries te
  WHERE ((te.id = actions_elementaires.time_entry_id) AND peut_voir_donnee_personnelle(auth.uid(), te.mission_id, te.user_id)))));

-- actions_elementaires / actions_write
DROP POLICY IF EXISTS actions_write ON public.actions_elementaires;
CREATE POLICY actions_write ON public.actions_elementaires AS PERMISSIVE FOR ALL TO public
  USING ((EXISTS ( SELECT 1
   FROM time_entries te
  WHERE ((te.id = actions_elementaires.time_entry_id) AND ((te.user_id = auth.uid()) OR est_directeur_associe(auth.uid()))))))
  WITH CHECK ((EXISTS ( SELECT 1
   FROM time_entries te
  WHERE ((te.id = actions_elementaires.time_entry_id) AND ((te.user_id = auth.uid()) OR est_directeur_associe(auth.uid()))))));

-- activities / activities_delete
DROP POLICY IF EXISTS activities_delete ON public.activities;
CREATE POLICY activities_delete ON public.activities AS PERMISSIVE FOR DELETE TO public
  USING ((project_id IN ( SELECT projects.id
   FROM projects
  WHERE (projects.organization_id = get_user_organization_id(auth.uid())))));

-- activities / activities_insert
DROP POLICY IF EXISTS activities_insert ON public.activities;
CREATE POLICY activities_insert ON public.activities AS PERMISSIVE FOR INSERT TO authenticated
  WITH CHECK ((project_id IN ( SELECT projects.id
   FROM projects
  WHERE (projects.organization_id = ( SELECT profiles.organization_id
           FROM profiles
          WHERE (profiles.id = auth.uid()))))));

-- activities / activities_select_v4_secure
DROP POLICY IF EXISTS activities_select_v4_secure ON public.activities;
CREATE POLICY activities_select_v4_secure ON public.activities AS PERMISSIVE FOR SELECT TO authenticated
  USING (can_access_project(auth.uid(), project_id));

-- activities / activities_update
DROP POLICY IF EXISTS activities_update ON public.activities;
CREATE POLICY activities_update ON public.activities AS PERMISSIVE FOR UPDATE TO public
  USING ((project_id IN ( SELECT projects.id
   FROM projects
  WHERE (projects.organization_id = get_user_organization_id(auth.uid())))));

-- activity_logs / activity_logs_insert
DROP POLICY IF EXISTS activity_logs_insert ON public.activity_logs;
CREATE POLICY activity_logs_insert ON public.activity_logs AS PERMISSIVE FOR INSERT TO authenticated
  WITH CHECK ((user_id = auth.uid()));

-- activity_logs / activity_logs_select
DROP POLICY IF EXISTS activity_logs_select ON public.activity_logs;
CREATE POLICY activity_logs_select ON public.activity_logs AS PERMISSIVE FOR SELECT TO public
  USING (((user_id = auth.uid()) OR ((organization_id = get_user_organization_id(auth.uid())) AND ((( SELECT profiles.grade_level
   FROM profiles
  WHERE (profiles.id = auth.uid())) <= 2) OR has_role(auth.uid(), 'admin'::app_role) OR has_role(auth.uid(), 'owner'::app_role)))));

-- activity_reports / activity_reports_own
DROP POLICY IF EXISTS activity_reports_own ON public.activity_reports;
CREATE POLICY activity_reports_own ON public.activity_reports AS PERMISSIVE FOR ALL TO authenticated
  USING (((user_id = auth.uid()) OR ((organization_id = ( SELECT profiles.organization_id
   FROM profiles
  WHERE (profiles.id = auth.uid()))) AND (( SELECT profiles.grade_level
   FROM profiles
  WHERE (profiles.id = auth.uid())) <= 2))))
  WITH CHECK ((user_id = auth.uid()));

-- activity_sessions / activity_sessions_own
DROP POLICY IF EXISTS activity_sessions_own ON public.activity_sessions;
CREATE POLICY activity_sessions_own ON public.activity_sessions AS PERMISSIVE FOR ALL TO authenticated
  USING (((user_id = auth.uid()) OR ((organization_id = ( SELECT profiles.organization_id
   FROM profiles
  WHERE (profiles.id = auth.uid()))) AND (( SELECT profiles.grade_level
   FROM profiles
