CREATE POLICY attendance_select ON public.attendance_events AS PERMISSIVE FOR SELECT TO authenticated
  USING (((user_id = auth.uid()) OR ((organization_id = ( SELECT p.organization_id
   FROM profiles p
  WHERE (p.id = auth.uid()))) AND (( SELECT p.grade_level
   FROM profiles p
  WHERE (p.id = auth.uid())) <= 3))));

-- attendance_events / attendance_update
DROP POLICY IF EXISTS attendance_update ON public.attendance_events;
CREATE POLICY attendance_update ON public.attendance_events AS PERMISSIVE FOR UPDATE TO authenticated
  USING (((user_id = auth.uid()) AND (event_date = CURRENT_DATE)));

