-- task_submissions / task_submissions_insert
DROP POLICY IF EXISTS task_submissions_insert ON public.task_submissions;
CREATE POLICY task_submissions_insert ON public.task_submissions AS PERMISSIVE FOR INSERT TO authenticated
  WITH CHECK ((task_id IN ( SELECT tasks.id
   FROM tasks
  WHERE (tasks.project_id IN ( SELECT projects.id
           FROM projects
          WHERE (projects.organization_id = ( SELECT profiles.organization_id
                   FROM profiles
                  WHERE (profiles.id = auth.uid()))))))));

-- task_submissions / task_submissions_select
DROP POLICY IF EXISTS task_submissions_select ON public.task_submissions;
CREATE POLICY task_submissions_select ON public.task_submissions AS PERMISSIVE FOR SELECT TO authenticated
  USING ((task_id IN ( SELECT tasks.id
   FROM tasks
  WHERE (tasks.project_id IN ( SELECT projects.id
           FROM projects
          WHERE (projects.organization_id = ( SELECT profiles.organization_id
                   FROM profiles
                  WHERE (profiles.id = auth.uid()))))))));

-- tasks / tasks_delete
DROP POLICY IF EXISTS tasks_delete ON public.tasks;
CREATE POLICY tasks_delete ON public.tasks AS PERMISSIVE FOR DELETE TO public
  USING (peut_piloter_la_tache(auth.uid(), id));

-- tasks / tasks_insert
DROP POLICY IF EXISTS tasks_insert ON public.tasks;
CREATE POLICY tasks_insert ON public.tasks AS PERMISSIVE FOR INSERT TO public
  WITH CHECK (((organization_id = ( SELECT p.organization_id
   FROM profiles p
  WHERE (p.id = auth.uid()))) AND (((project_id IS NOT NULL) AND peut_piloter_le_projet(auth.uid(), project_id)) OR ((project_id IS NULL) AND (COALESCE(( SELECT p.grade_level
   FROM profiles p
  WHERE (p.id = auth.uid())), 8) <= 3)))));

-- tasks / tasks_select_v5
DROP POLICY IF EXISTS tasks_select_v5 ON public.tasks;
CREATE POLICY tasks_select_v5 ON public.tasks AS PERMISSIVE FOR SELECT TO authenticated
  USING (((created_by = auth.uid()) OR can_access_task(auth.uid(), id)));

