DROP POLICY IF EXISTS tasks_update ON public.tasks;
CREATE POLICY tasks_update ON public.tasks AS PERMISSIVE FOR UPDATE TO public
  USING ((peut_piloter_la_tache(auth.uid(), id) OR est_affecte_a_la_tache(auth.uid(), id)))
  WITH CHECK ((peut_piloter_la_tache(auth.uid(), id) OR est_affecte_a_la_tache(auth.uid(), id)));

