  USING (((user_id = auth.uid()) AND (status = ANY (ARRAY['draft'::text, 'rejected'::text]))));

-- time_entries / te_superior_select
DROP POLICY IF EXISTS te_superior_select ON public.time_entries;
CREATE POLICY te_superior_select ON public.time_entries AS PERMISSIVE FOR SELECT TO authenticated
  USING (((user_id = auth.uid()) OR ((organization_id = ( SELECT p.organization_id
   FROM profiles p
  WHERE (p.id = auth.uid()))) AND (( SELECT p.grade_level
   FROM profiles p
  WHERE (p.id = auth.uid())) <= 3)) OR (EXISTS ( SELECT 1
   FROM projects pj
  WHERE ((pj.id = time_entries.project_id) AND (pj.lead_id = auth.uid())))) OR (EXISTS ( SELECT 1
   FROM missions m
  WHERE ((m.id = time_entries.mission_id) AND ((m.director_id = auth.uid()) OR (m.chief_id = auth.uid())))))));

-- time_entries / te_superior_update
DROP POLICY IF EXISTS te_superior_update ON public.time_entries;
CREATE POLICY te_superior_update ON public.time_entries AS PERMISSIVE FOR UPDATE TO public
  USING (((organization_id = get_user_organization_id(auth.uid())) AND (status <> 'approved'::text) AND peut_voir_donnee_personnelle(auth.uid(), mission_id, user_id) AND ((COALESCE(( SELECT p.grade_level
   FROM profiles p
  WHERE (p.id = auth.uid())), 8) <= 4) OR has_role(auth.uid(), 'admin'::app_role))))
  WITH CHECK (((organization_id = get_user_organization_id(auth.uid())) AND peut_voir_donnee_personnelle(auth.uid(), mission_id, user_id) AND ((COALESCE(( SELECT p.grade_level
   FROM profiles p
  WHERE (p.id = auth.uid())), 8) <= 4) OR has_role(auth.uid(), 'admin'::app_role))));

