  USING ((workspace_id IN ( SELECT personal_workspaces.id
   FROM personal_workspaces
  WHERE (personal_workspaces.user_id = auth.uid()))));

-- workspace_files / workspace_files_superior_select
DROP POLICY IF EXISTS workspace_files_superior_select ON public.workspace_files;
CREATE POLICY workspace_files_superior_select ON public.workspace_files AS PERMISSIVE FOR SELECT TO public
  USING ((((( SELECT profiles.grade_level
   FROM profiles
  WHERE (profiles.id = auth.uid())) = 1) AND (workspace_id IN ( SELECT pw.id
   FROM (personal_workspaces pw
     JOIN profiles p ON ((pw.user_id = p.id)))
  WHERE (p.organization_id = get_user_organization_id(auth.uid()))))) OR ((( SELECT profiles.grade_level
   FROM profiles
  WHERE (profiles.id = auth.uid())) = 2) AND (workspace_id IN ( SELECT pw.id
   FROM ((personal_workspaces pw
     JOIN mission_members mm ON ((pw.user_id = mm.user_id)))
     JOIN missions m ON ((mm.mission_id = m.id)))
  WHERE ((m.director_id = auth.uid()) OR (m.chief_id = auth.uid()))))) OR (workspace_id IN ( SELECT pw.id
   FROM ((personal_workspaces pw
     JOIN project_members pm ON ((pw.user_id = pm.user_id)))
     JOIN projects pr ON ((pm.project_id = pr.id)))
  WHERE (pr.lead_id = auth.uid())))));

