-- ═══════════════════════════════════════════════════════════════════════════
--  7. CONTRAINTES (134)
--  Ajoutées seulement si elles manquent.
-- ═══════════════════════════════════════════════════════════════════════════

-- actions_elementaires / actions_elementaires_etat_check
DO $c$ BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_constraint
                 WHERE conname = 'actions_elementaires_etat_check' AND conrelid = 'public.actions_elementaires'::regclass) THEN
    ALTER TABLE public.actions_elementaires ADD CONSTRAINT actions_elementaires_etat_check CHECK ((etat = ANY (ARRAY['a_faire'::text, 'en_cours'::text, 'fait'::text, 'bloque'::text])));
  END IF;
END $c$;

-- actions_elementaires / actions_elementaires_heures_check
DO $c$ BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_constraint
                 WHERE conname = 'actions_elementaires_heures_check' AND conrelid = 'public.actions_elementaires'::regclass) THEN
    ALTER TABLE public.actions_elementaires ADD CONSTRAINT actions_elementaires_heures_check CHECK (((heures IS NULL) OR ((heures > (0)::numeric) AND (heures <= (24)::numeric))));
  END IF;
END $c$;

-- actions_elementaires / actions_elementaires_intitule_check
DO $c$ BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_constraint
                 WHERE conname = 'actions_elementaires_intitule_check' AND conrelid = 'public.actions_elementaires'::regclass) THEN
    ALTER TABLE public.actions_elementaires ADD CONSTRAINT actions_elementaires_intitule_check CHECK ((length(TRIM(BOTH FROM intitule)) >= 3));
  END IF;
END $c$;

