-- ═══════════════════════════════════════════════════════════════════════════
--  8. INDEX UNIQUES (11)
--  Ajoutés seulement s'ils manquent.
-- ═══════════════════════════════════════════════════════════════════════════

-- idx_mailing_groups_committee_unique
CREATE UNIQUE INDEX IF NOT EXISTS idx_mailing_groups_committee_unique ON public.mailing_groups USING btree (committee_id) WHERE (committee_id IS NOT NULL);

-- uniq_departments_default_dossier
CREATE UNIQUE INDEX IF NOT EXISTS uniq_departments_default_dossier ON public.departments USING btree (organization_id) WHERE is_default_dossier;

-- uniq_designation_annuelle
CREATE UNIQUE INDEX IF NOT EXISTS uniq_designation_annuelle ON public.evaluation_assignments USING btree (evaluatee_id, COALESCE((exercice)::integer, 0)) WHERE ((status <> 'annulee'::text) AND (eval_type = 'annuelle'::eval_type));

-- uniq_designation_mission_dossier
CREATE UNIQUE INDEX IF NOT EXISTS uniq_designation_mission_dossier ON public.evaluation_assignments USING btree (COALESCE(mission_id, '00000000-0000-0000-0000-000000000000'::uuid), COALESCE(dossier_id, '00000000-0000-0000-0000-000000000000'::uuid), eval_type, COALESCE((exercice)::integer, 0), evaluatee_id, evaluator_id) WHERE ((status <> 'annulee'::text) AND (eval_type = ANY (ARRAY['mission'::eval_type, 'dossier'::eval_type, 'fin_stage'::eval_type])));

-- uniq_eval_feedback
CREATE UNIQUE INDEX IF NOT EXISTS uniq_eval_feedback ON public.evaluation_feedback USING btree (evaluation_id, contributor_id);

-- uniq_eval_grade_rang
CREATE UNIQUE INDEX IF NOT EXISTS uniq_eval_grade_rang ON public.evaluation_grades USING btree (organization_id, practice, rank);

-- uniq_eval_per_assignment
CREATE UNIQUE INDEX IF NOT EXISTS uniq_eval_per_assignment ON public.evaluations USING btree (assignment_id) WHERE (assignment_id IS NOT NULL);

-- uniq_pinv_pending
CREATE UNIQUE INDEX IF NOT EXISTS uniq_pinv_pending ON public.portal_invitations USING btree (client_id, lower(email)) WHERE (status = 'pending'::text);

-- uniq_staffing_active
CREATE UNIQUE INDEX IF NOT EXISTS uniq_staffing_active ON public.staffing_assignments USING btree (mission_id, COALESCE(project_id, '00000000-0000-0000-0000-000000000000'::uuid), user_id) WHERE (status = ANY (ARRAY['proposed'::text, 'accepted'::text, 'adjustment_requested'::text]));

-- uniq_taux_par_grade
CREATE UNIQUE INDEX IF NOT EXISTS uniq_taux_par_grade ON public.daily_rates USING btree (organization_id, grade);

-- uq_document_folders_mission_kind
CREATE UNIQUE INDEX IF NOT EXISTS uq_document_folders_mission_kind ON public.document_folders USING btree (mission_id, kind) WHERE (kind IS NOT NULL);


-- ═══════════════════════════════════════════════════════════════════════════
--  9. PRIVILÈGES PAR DÉFAUT (scripts 42a et 42b)
--  Les fonctions créées plus tard ne sont pas ouvertes aux visiteurs.
-- ═══════════════════════════════════════════════════════════════════════════

ALTER DEFAULT PRIVILEGES IN SCHEMA public REVOKE EXECUTE ON FUNCTIONS FROM anon;
DO $d$
DECLARE _r text;
BEGIN
  FOREACH _r IN ARRAY ARRAY['postgres', 'supabase_admin'] LOOP
    BEGIN
      EXECUTE format('ALTER DEFAULT PRIVILEGES FOR ROLE %I IN SCHEMA public REVOKE EXECUTE ON FUNCTIONS FROM anon', _r);
    EXCEPTION WHEN OTHERS THEN
      RAISE NOTICE 'privilege par defaut de % : non modifiable ici (%)', _r, SQLERRM;
    END;
  END LOOP;
END $d$;

